/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"법원의 종류","줄":[{"t":"성문법원: 헌법 / 법률 / 명령(대통령령·총리령·부령 = 시행령·시행규칙) / 조례 / 규칙 / 조약과 일반적으로 승인된 국제법규","src":"헌법 제6조 제75조 제95조 | 기출 2021-2, 2022-2, 2024-3"},{"t":"불문법원: 관습법 / 판례법 / 조리 (관습법·판례법·조리를 성문법원이라고 한 선지는 오답)","src":"보충(원문 미확인) | 기출 2021-2, 2025-2"},{"t":"헌법에 의해 체결·공포된 조약과 일반적으로 승인된 국제법규는 국내법과 같은 효력을 가진다(법원에 포함)","src":"헌법 제6조제1항 | 기출 2022-2, 2024-3"},{"t":"사회복지법의 법원에는 대통령령 / 조례 / 일반적으로 승인된 국제법규 / 규칙이 모두 해당한다","src":"헌법 제6조 제75조 지방자치법 제28조 제29조 | 기출 2022-2"},{"t":"사회복지법은 법원으로서 관습법 판례법도 인정되는 불문법을 포함하되 성문법원이 중심이다 (관습법은 법원이 될 수 없다는 선지는 오답)","src":"보충(원문 미확인) | 기출 2024-3"}]},{"머리":"법규범의 위계","줄":[{"t":"최상위 법규범은 헌법이고 그 다음이 법률. 명령(시행령·시행규칙)은 법률의 하위","src":"보충(원문 미확인) | 기출 2021-4, 2025-2"},{"t":"시행령은 대통령령이고 시행규칙은 총리령 또는 부령이다. 시행령이 시행규칙보다 상위","src":"헌법 제75조 제95조 | 기출 2021-4, 2025-2"},{"t":"대통령은 법률에서 구체적으로 범위를 정하여 위임받은 사항과 법률을 집행하기 위하여 필요한 사항에 관하여 대통령령을 발할 수 있다","src":"헌법 제75조 | 기출 2025-2"},{"t":"국무총리 또는 행정각부의 장은 소관사무에 관하여 법률이나 대통령령의 위임 또는 직권으로 총리령 또는 부령을 발할 수 있다","src":"헌법 제95조 | 기출 2021-4"},{"t":"법률은 국회에서 제정한다. 입법권은 국회에 속한다. 국회의원과 정부는 모두 법률안을 제출할 수 있다","src":"헌법 제40조 제52조 | 기출 2021-4, 2025-2, 2026-4"},{"t":"법률안의 확정·공포 절차: 국회 의결 법률안은 정부에 이송되어 15일 이내에 대통령이 공포한다. 이의가 있으면 15일 이내 이의서를 붙여 국회에 환부하고 재의를 요구할 수 있으나 법률안의 일부에 대하여 또는 수정하여 재의를 요구할 수 없다","src":"헌법 제53조제1항~제3항 | 기출 2026-4"},{"t":"재의 요구 후 재적의원 과반수 출석과 출석의원 3분의 2 이상의 찬성으로 전과 같이 의결하면 법률로 확정된다. 대통령이 기간 내에 공포나 재의 요구를 하지 않아도 확정","src":"헌법 제53조제4항·제5항"},{"t":"법률은 특별한 규정이 없는 한 공포한 날로부터 20일을 경과함으로써 효력을 발생한다(7일 아님)","src":"헌법 제53조제7항 | 기출 2026-4"},{"t":"법률이 헌법에 위반되는지는 법원의 제청으로 헌법재판소가 심판한다. 명령·규칙·처분의 위헌·위법 심사는 대법원이 최종 권한을 가진다","src":"헌법 제107조 제111조"}]},{"머리":"자치법규","줄":[{"t":"조례: 지방자치단체가 법령의 범위에서 그 사무에 관하여 제정한다. 주민의 권리 제한·의무 부과나 벌칙은 법률의 위임이 있어야 한다","src":"지방자치법 제28조제1항 | 기출 2021-3, 2023-7, 2025-8"},{"t":"조례는 지방의회의 의결로 제정한다(지방의회가 제정하고 지방자치단체의 장은 규칙 제정권)","src":"지방자치법 제28조 제32조 | 기출 2021-3, 2023-7, 2025-8"},{"t":"규칙: 지방자치단체의 장이 법령 또는 조례의 범위에서 그 권한에 속하는 사무에 관하여 제정","src":"지방자치법 제29조 | 기출 2021-3, 2025-8"},{"t":"시·군 및 자치구의 조례나 규칙은 시·도의 조례나 규칙을 위반해서는 아니 된다","src":"지방자치법 제30조 | 기출 2021-3, 2023-7, 2025-8"},{"t":"조례안 절차: 의결된 날부터 5일 이내에 지방의회 의장이 지방자치단체의 장에게 이송 → 이송받은 날부터 20일 이내 공포. 이의가 있으면 20일 이내 재의 요구(일부·수정 재의 요구 불가) → 재적 과반수 출석과 출석 3분의 2 이상 찬성이면 확정","src":"지방자치법 제32조 | 기출 2021-3"},{"t":"조례와 규칙은 특별한 규정이 없으면 공포한 날부터 20일이 지나면 효력이 발생한다","src":"지방자치법 제32조제8항"},{"t":"사회복지시설의 설치·운영 및 관리는 주민의 복지증진과 관련된 지방자치단체의 사무이다. 주민은 조례 제정을 청구할 수 있다","src":"지방자치법 | 기출 2023-7 | 보충(원문 미확인)"},{"t":"조례와 규칙 사이의 효력: 조례는 규칙보다 상위 법규범이다","src":"보충(원문 미확인) | 기출 2025-8"}]}],"함정":[{"x":"지방자치단체는 법령의 범위와 무관하게 조례를 제정할 수 있다.","o":"법령의 범위에서 제정할 수 있다.","src":"지방자치법 제28조제1항 | 기출 2021-3"},{"x":"시행령은 국무총리나 행정각부의 장이 발(發)하는 명령이다.","o":"시행령은 대통령이 발하는 대통령령. 국무총리·행정각부의 장이 발하는 것은 총리령·부령(시행규칙).","src":"헌법 제75조 제95조 | 기출 2021-4"},{"x":"지방의회는 규칙 제정권을 갖고 지방자치단체의 장은 조례 제정권을 갖는다.","o":"조례는 지방의회가 규칙은 지방자치단체의 장이 제정한다.","src":"지방자치법 제28조 제29조 | 기출 2023-7"},{"x":"관습법은 사회복지법의 법원이 될 수 없다.","o":"관습법도 불문법원으로서 법원이 될 수 있다.","src":"보충(원문 미확인) | 기출 2024-3"},{"x":"법률은 정부의 의결을 거쳐 제정ㆍ공포된 법을 말한다.","o":"법률은 국회의 의결을 거쳐 제정·공포된다.","src":"헌법 제40조 | 기출 2024-3"},{"x":"명령은 행정기관이 제정한 법규로 국회의 의결을 거쳐야 한다.","o":"명령은 국회 의결 없이 행정기관이 제정한다.","src":"헌법 제75조 제95조 | 기출 2024-3"},{"x":"일반적으로 승인된 국제법규는 사회복지법의 법원에 포함되지 않는다.","o":"국내법과 같은 효력을 가지므로 법원에 포함된다.","src":"헌법 제6조제1항 | 기출 2024-3"},{"x":"성문법원의 종류로 관습법, 판례법, 조리가 있다.","o":"관습법·판례법·조리는 불문법원이다.","src":"보충(원문 미확인) | 기출 2025-2"},{"x":"시행령과 시행규칙은 국회의 의결을 거쳐 제정, 공포된 법원이다.","o":"국회 의결 없이 행정부가 제정한다.","src":"헌법 제75조 제95조 | 기출 2025-2"},{"x":"시행령보다 시행규칙이 상위 법규범이다.","o":"시행령(대통령령)이 시행규칙(총리령·부령)보다 상위.","src":"보충(원문 미확인) | 기출 2025-2"},{"x":"정부는 법률안을 제출할 수 없다.","o":"국회의원과 정부가 법률안을 제출할 수 있다.","src":"헌법 제52조 | 기출 2025-2, 2026-4"},{"x":"시ㆍ군 및 자치구의 규칙은 시ㆍ도의 규칙보다 상위 법규범이다.","o":"시·군·자치구의 규칙은 시·도의 규칙을 위반할 수 없다(하위).","src":"지방자치법 제30조 | 기출 2025-8"},{"x":"입법권은 국회와 행정부에 속한다.","o":"입법권은 국회에 속한다.","src":"헌법 제40조 | 기출 2026-4"},{"x":"법률은 특별한 규정이 없는 한 공포한 날로부터 7일을 경과함으로써 효력을 발생한다.","o":"20일.","src":"헌법 제53조제7항 | 기출 2026-4"},{"x":"국회에서 의결된 법률안은 정부에 이송되어 15일 이내에 대통령이 공포한다.","o":"현행 헌법 제53조제1항은 15일 이내 공포로 정해져 이 문장 자체는 원문과 같다. 이 선지의 오답 표시는 기출 원문 재확인 필요.","src":"헌법 제53조제1항 | 기출 2026-4"},{"x":"대통령은 법률안을 수정하여 재의를 요구할 수 있다.","o":"이 문장은 현행 헌법 제53조제3항(수정 재의 요구 불가)과 어긋난다. 기출 정오 표시 재확인 필요. 법률안의 일부·수정 재의 요구는 불가.","src":"헌법 제53조제3항 | 기출 2026-4"}]},"#2":{"묶음":[{"머리":"법률 제정연도 순서 (연도는 모두 보충(원문 미확인))","줄":[{"t":"1960년대 제정: 아동복리법(1961) / 산업재해보상보험법(1963) / 생활보호법(1961)","src":"보충(원문 미확인) | 기출 2021-1, 2023-1, 2025-1, 2025-3"},{"t":"1970년대 제정: 사회복지사업법(1970) / 국민복지연금법(1973) / 의료보호법(1977)","src":"보충(원문 미확인) | 기출 2021-1, 2023-1, 2023-3"},{"t":"1980년대: 노인복지법(1981 제정) / 심신장애자복지법(1981) → 1989 장애인복지법으로 전부개정 / 아동복리법 → 1981 아동복지법으로 전부개정 / 국민복지연금법 → 1986 국민연금법으로 전부개정 / 모자복지법(1989) → 한부모가족지원법의 전신","src":"보충(원문 미확인) | 기출 2022-3, 2023-3, 2024-2, 2025-3, 2026-2"},{"t":"1990년대: 영유아보육법(1991) / 고용보험법(1993) / 사회보장기본법(1995) / 정신보건법(1995) / 사회복지공동모금회법(1997) / 국민의료보험법(1997) / 국민건강보험법(1999) / 국민기초생활보장법(1999)","src":"보충(원문 미확인) | 기출 2021-1, 2022-3, 2023-1, 2023-3, 2025-1, 2026-1"},{"t":"2000년대: 의료급여법(2001) / 긴급복지지원법(2005) / 자원봉사활동기본법(2005) / 노인장기요양보험법(2007) / 다문화가족지원법(2008)","src":"보충(원문 미확인) | 기출 2024-2, 2025-3, 2026-1"},{"t":"2010년대: 장애인연금법(2010) / 기초연금법(2014) / 사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률(2014 제정)","src":"보충(원문 미확인) | 기출 2023-3, 2026-2"},{"t":"가장 최근에 제정된 법률: 2026 기출 선지(국민건강보험법 / 다문화가족지원법 / 노인 일자리 및 사회활동 지원에 관한 법률 / 사회보장기본법 / 긴급복지지원법) 중 노인 일자리 및 사회활동 지원에 관한 법률이 정답","src":"보충(원문 미확인) | 기출 2026-1"}]},{"머리":"법률의 개정·개칭 관계","줄":[{"t":"아동복리법(1961) → 아동복지법(1981 전부개정)","src":"보충(원문 미확인) | 기출 2025-3, 2026-2"},{"t":"심신장애자복지법(1981) → 장애인복지법(1989 전부개정)","src":"보충(원문 미확인) | 기출 2025-3, 2026-2"},{"t":"국민복지연금법(1973) → 국민연금법(1986 전부개정). 국민연금법으로 개정된 전신이 국민복지연금법이다","src":"보충(원문 미확인) | 기출 2023-3, 2026-2"},{"t":"정신보건법(1995) → 정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률(2016 전부개정)","src":"보충(원문 미확인) | 기출 2026-2"},{"t":"기초노령연금법(2007) → 기초연금법(2014 대체) → 장애인연금법과 개정 관계 없음. 기초연금법에서 장애인연금법으로 바뀐 것이 아니다","src":"보충(원문 미확인) | 기출 2023-3, 2026-2"},{"t":"국민의료보험법(1997 제정) → 국민건강보험법(1999 제정으로 대체)","src":"보충(원문 미확인) | 기출 2023-3"},{"t":"노인복지법은 1981년 제정. 노인장기요양보험법은 2007년 제정","src":"보충(원문 미확인) | 기출 2025-3"}]}],"함정":[{"x":"2014년 기초노령연금법이 제정되면서 기초연금법은 폐지되었다.","o":"2014년 기초연금법이 제정되어 기초노령연금법을 대체했다(순서가 반대).","src":"보충(원문 미확인) | 기출 2023-3"},{"x":"1999년 제정된 국민의료보험법은 국민건강보험법을 대체한 것이다.","o":"국민의료보험법(1997)이 국민건강보험법(1999)으로 대체되었다.","src":"보충(원문 미확인) | 기출 2023-3"},{"x":"1961년 제정된 아동복리법은 1989년 아동복지법으로 개정되었다.","o":"1981년 아동복지법으로 개정.","src":"보충(원문 미확인) | 기출 2025-3"},{"x":"2017년 12월 30일에 제정, 2018년 7월 1일부터 시행되었다.","o":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률은 2014년 12월 30일 제정, 2015년 7월 1일 시행.","src":"보충(원문 미확인) | 기출 2021-8"}]},"#3":{"묶음":[{"머리":"헌법 제10조 · 제34조 인간다운 생활","줄":[{"t":"모든 국민은 인간으로서의 존엄과 가치를 가지며 행복을 추구할 권리를 가진다. 국가는 개인이 가지는 불가침의 기본적 인권을 확인하고 이를 보장할 의무를 진다 (행복추구권이 헌법 제10조)","src":"헌법 제10조 | 기출 2024-1"},{"t":"제34조 ①: 모든 국민은 인간다운 생활을 할 권리를 가진다","src":"헌법 제34조제1항 | 기출 2026-3"},{"t":"제34조 ②: 국가는 사회보장·사회복지의 증진에 노력할 의무를 진다 (공공부조 아님)","src":"헌법 제34조제2항 | 기출 2023-2, 2026-3"},{"t":"제34조 ③: 국가는 여자의 복지와 권익의 향상을 위하여 노력하여야 한다","src":"헌법 제34조제3항 | 기출 2022-1"},{"t":"제34조 ④: 국가는 노인과 청소년의 복지향상을 위한 정책을 실시할 의무를 진다","src":"헌법 제34조제4항 | 기출 2026-3"},{"t":"제34조 ⑤: 신체장애자 및 질병·노령 기타의 사유로 생활능력이 없는 국민은 법률이 정하는 바에 의하여 국가의 보호를 받는다(헌법이 정하는 바가 아니라 법률)","src":"헌법 제34조제5항 | 기출 2023-2"},{"t":"제34조 ⑥: 국가는 재해를 예방하고 그 위험으로부터 국민을 보호하기 위하여 노력하여야 한다","src":"헌법 제34조제6항"}]},{"머리":"기타 사회적 기본권","줄":[{"t":"제31조 교육을 받을 권리: ① 능력에 따라 균등하게 교육을 받을 권리 ② 보호하는 자녀에게 적어도 초등교육과 법률이 정하는 교육을 받게 할 의무 ③ 의무교육 무상 ④ 교육의 자주성·전문성·정치적 중립성·대학의 자율성 ⑤ 국가는 평생교육을 진흥하여야 한다 ⑥ 교육제도 기본 사항은 법률로 정한다","src":"헌법 제31조 | 기출 2022-1"},{"t":"제32조 근로의 권리: ① 근로의 권리. 국가는 사회적·경제적 방법으로 고용의 증진과 적정임금의 보장에 노력하여야 하며 법률에 따라 최저임금제를 시행하여야 한다 ② 근로의 의무 ③ 근로조건 기준은 인간의 존엄성 보장 ④ 여자의 근로 특별 보호와 부당한 차별 금지 ⑤ 연소자 근로 특별 보호 ⑥ 국가유공자·상이군경·전몰군경 유가족 우선적 근로 기회","src":"헌법 제32조 | 기출 2022-1"},{"t":"제33조 노동3권: ① 근로자는 자주적인 단결권·단체교섭권·단체행동권을 가진다 ② 공무원인 근로자는 법률이 정하는 자에 한하여 노동3권을 가진다(모든 공무원 보장이 아님) ③ 주요방위산업체 근로자의 단체행동권은 법률로 제한·부인 가능","src":"헌법 제33조 | 기출 2022-1"},{"t":"제35조: ① 건강하고 쾌적한 환경에서 생활할 권리(환경권) ② 환경권 내용·행사는 법률로 ③ 국가는 주택개발정책 등을 통하여 쾌적한 주거생활을 위해 노력","src":"헌법 제35조"},{"t":"제36조: ① 혼인과 가족생활은 개인의 존엄과 양성의 평등을 기초로 성립·유지 ② 국가는 모성의 보호를 위하여 노력 ③ 모든 국민은 보건에 관하여 국가의 보호를 받는다(제36조제3항)","src":"헌법 제36조 | 기출 2022-1, 2026-3"},{"t":"제37조: 국민의 자유와 권리는 헌법에 열거되지 아니한 이유로 경시되지 아니한다. 국가안전보장·질서유지·공공복리를 위하여 필요한 경우에 한하여 법률로써 제한할 수 있고 본질적인 내용은 침해할 수 없다","src":"헌법 제37조 | 기출 2021-25"},{"t":"제19조 양심의 자유: 모든 국민은 양심의 자유를 가진다 (자유권. 사회적 기본권이 아님)","src":"헌법 제19조 | 기출 2026-3 | 보충(원문 미확인)"}]},{"머리":"사회적 기본권의 성격과 사회복지수급권","줄":[{"t":"사회적 기본권은 국가에 대하여 적극적 급부·배려를 요구하는 권리로 자유권과 대비된다","src":"보충(원문 미확인)"},{"t":"사회적 기본권의 법적 성격을 보는 학설: 프로그램규정설(입법 방침) / 추상적 권리설(법률이 있어야 구체화) / 구체적 권리설. 인간다운 생활을 할 권리는 헌법재판소가 최소한의 물질적 생활 보장을 요구할 수 있는 한도에서 구체적 권리로 보되 입법 형성의 자유를 넓게 인정한다는 취지","src":"보충(추정)"},{"t":"사회복지수급권은 법률에 의해 구체화된 권리. 사회보장기본법상 수급권은 양도·담보 제공·압류가 금지되고 제한·정지는 원칙적으로 불가하며 필요한 최소한의 범위에서만 가능","src":"사회보장기본법 제12조 제13조"},{"t":"장애인고용부담금 헌재 결정(2001헌바96): 기업의 경제상 자유는 공공복리를 위해 법률로 제한할 수 있고 국가는 경제민주화를 위해 규제·조정할 수 있다. 고용부담금제도는 고용의무제 실효성 확보 수단으로 입법목적의 정당성이 인정되며 고용의무를 이행하는 사업주와 아닌 사업주 사이의 경제적 부담의 불균형을 조정하는 기능을 한다. 구 장애인고용촉진등에관한법률 제35조제1항 본문은 헌법에 합치(합헌)한다는 취지","src":"보충(판례 추정) | 기출 2021-25"}]}],"함정":[{"x":"국가는 모든 공무원인 근로자의 단결권ㆍ단체교섭권 및 단체행동권을 보장하여야 한다.","o":"공무원인 근로자는 법률이 정하는 자에 한하여 노동3권을 가진다.","src":"헌법 제33조제2항 | 기출 2022-1"},{"x":"모든 국민은 보건에 관하여 국가의 보호를 받는다.","o":"문장 자체는 헌법 제36조제3항 내용이다. 제34조에는 없다(제34조는 인간다운 생활 / 사회보장·사회복지 / 여자 / 노인·청소년 / 생활능력 없는 국민 / 재해예방).","src":"헌법 제36조제3항 | 기출 2026-3"},{"x":"구 장애인고용촉진등에관한법률 제35조제1항 본문은 헌법에 불합치한다.","o":"출제 오답(판례 결론은 합헌 취지로 추정).","src":"보충(판례 추정) | 기출 2021-25"}]},"#4":{"묶음":[{"머리":"목적·이념·정의","줄":[{"t":"사회보장기본법 목적: 사회보장에 관한 국민의 권리와 국가·지방자치단체의 책임을 정하고, 사회보장정책의 수립·추진과 관련 제도의 기본 사항을 규정해 국민의 복지증진에 이바지함","src":"사회보장기본법 제1조"},{"t":"기본 이념: 자립 지원, 사회참여·자아실현에 필요한 제도와 여건 조성으로 사회통합과 행복한 복지사회 실현","src":"사회보장기본법 제2조"},{"t":"다른 사회보장 법률을 제정·개정할 때는 이 법에 부합되도록 하여야 한다","src":"사회보장기본법 제4조 | 기출 2024-10"},{"t":"사회보장: 출산·양육·실업·노령·장애·질병·빈곤·사망 등 사회적 위험으로부터 모든 국민을 보호하고 삶의 질을 향상시키는 데 필요한 소득·서비스를 보장하는 사회보험·공공부조·사회서비스","src":"사회보장기본법 제3조제1호"},{"t":"사회보험: 사회적 위험을 보험의 방식으로 대처하여 국민의 건강과 소득을 보장하는 제도","src":"사회보장기본법 제3조제2호 | 기출 2021-7"},{"t":"공공부조: 국가와 지방자치단체의 책임 하에 생활 유지 능력이 없거나 생활이 어려운 국민의 최저생활을 보장하고 자립을 지원하는 제도","src":"사회보장기본법 제3조제3호 | 기출 2021-7"},{"t":"사회서비스: 국가·지방자치단체·민간부문의 도움이 필요한 모든 국민에게 복지·보건의료·교육·고용·주거·문화·환경 등의 분야에서 상담·재활·돌봄·정보제공·시설이용·역량개발·사회참여 지원 등으로 삶의 질을 높이는 제도","src":"사회보장기본법 제3조제4호"},{"t":"평생사회안전망: 생애주기에 걸쳐 보편적으로 충족되어야 하는 기본욕구와 특정 사회위험으로 생기는 특수욕구를 동시에 고려해 소득·서비스를 보장하는 맞춤형 사회보장제도","src":"사회보장기본법 제3조제5호 | 기출 2021-7"},{"t":"사회보장 행정데이터: 국가·지방자치단체·공공기관·법인이 법령에 따라 생성·취득해 관리하는 자료·정보로서 사회보장 정책 수행에 필요한 것","src":"사회보장기본법 제3조제6호"}]},{"머리":"책임과 국민의 의무","줄":[{"t":"국가와 지방자치단체는 모든 국민의 인간다운 생활을 유지·증진하는 책임을 가진다","src":"사회보장기본법 제5조제1항 | 기출 2022-5"},{"t":"국가와 지방자치단체는 사회보장에 관한 책임과 역할을 합리적으로 분담하여야 한다","src":"사회보장기본법 제5조제2항 | 기출 2022-5"},{"t":"국가와 지방자치단체는 지속가능한 사회보장제도를 확립하고 매년 필요한 재원을 조달하여야 한다","src":"사회보장기본법 제5조제3항 | 기출 2022-5"},{"t":"국가와 지방자치단체는 가정이 건전하게 유지되고 그 기능이 향상되도록 노력하여야 하며 제도 시행 때 가정과 지역공동체의 자발적 복지활동을 촉진하여야 한다","src":"사회보장기본법 제6조 | 기출 2022-5"},{"t":"국민의 책임: 자립·자활 노력, 보호가 필요한 사람에게 지속적 관심과 사회환경 조성 협력, 관계 법령에 따른 비용 부담·정보 제공 등 정책 협력","src":"사회보장기본법 제7조"},{"t":"외국인 적용: 국내 거주 외국인에게는 상호주의 원칙에 따르되 관계 법령에서 정하는 바에 따른다","src":"사회보장기본법 제8조"}]},{"머리":"사회보장수급권","줄":[{"t":"사회보장수급권: 모든 국민이 사회보장 관계 법령에서 정하는 바에 따라 사회보장급여를 받을 권리","src":"사회보장기본법 제9조 | 기출 2021-5"},{"t":"사회보장급여 수준: 국가와 지방자치단체는 급여 수준 향상에 노력하고, 국가는 관계 법령에 따라 최저보장수준과 최저임금을 매년 공표하며 국가와 지방자치단체는 이를 고려해 급여 수준을 결정한다","src":"사회보장기본법 제10조 | 기출 2024-8, 2026-5"},{"t":"신청: 급여를 받으려는 사람은 관계 법령에 따라 국가나 지방자치단체에 신청하여야 한다. 관계 법령에 따로 정하면 국가나 지방자치단체가 신청을 대신할 수 있다","src":"사회보장기본법 제11조제1항 | 기출 2023-5"},{"t":"다른 기관에 신청한 경우 그 기관은 지체 없이 정당한 권한이 있는 기관에 이송하여야 하고, 이송된 날을 신청일로 본다","src":"사회보장기본법 제11조제2항"},{"t":"보호: 사회보장수급권은 관계 법령에서 정하는 바에 따라 양도·담보 제공을 할 수 없고 압류할 수 없다","src":"사회보장기본법 제12조 | 기출 2021-5, 2023-5, 2025-4"},{"t":"제한·정지: 사회보장수급권은 제한되거나 정지될 수 없다. 관계 법령에 따로 정한 경우는 예외","src":"사회보장기본법 제13조제1항 | 기출 2023-5"},{"t":"제한·정지하는 경우에도 그 목적에 필요한 최소한의 범위에 그쳐야 한다","src":"사회보장기본법 제13조제2항 | 기출 2024-8"},{"t":"포기: 정당한 권한이 있는 기관에 서면으로 통지하여 포기할 수 있다(구두 통지는 안 됨)","src":"사회보장기본법 제14조제1항 | 기출 2021-5, 2023-5, 2024-8, 2025-4"},{"t":"포기의 취소: 포기는 취소할 수 있다","src":"사회보장기본법 제14조제2항 | 기출 2021-5, 2023-5, 2025-4"},{"t":"포기 제한: 포기하는 것이 다른 사람에게 피해를 주거나 사회보장 관계 법령에 위반되면 포기할 수 없다","src":"사회보장기본법 제14조제3항 | 기출 2024-8, 2025-4"},{"t":"구상권: 제3자의 불법행위로 피해를 입은 국민이 수급권을 가지게 된 경우, 사회보장제도를 운영하는 자는 책임 있는 자에게 관계 법령에 따라 구상권을 행사할 수 있다","src":"사회보장기본법 제15조 | 기출 2024-10"},{"t":"권리구제: 위법·부당한 처분을 받거나 필요한 처분을 받지 못한 국민은 행정심판법에 따른 행정심판 또는 행정소송법에 따른 행정소송을 청구할 수 있다","src":"사회보장기본법 제39조"}]},{"머리":"기본계획·시행계획·지역계획","줄":[{"t":"사회보장 기본계획: 보건복지부장관이 관계 중앙행정기관의 장과 협의하여 5년마다 수립","src":"사회보장기본법 제16조제1항 | 기출 2025-5, 2026-5"},{"t":"기본계획 포함 사항: 국내외 사회보장환경의 변화와 전망 / 기본목표 및 중장기 추진방향 / 주요 추진과제 및 추진방법 / 필요한 재원의 규모와 조달방안 / 사회보장 관련 기금 운용방안 / 사회보장 전달체계 / 그 밖에 정책 추진에 필요한 사항","src":"사회보장기본법 제16조제2항 | 기출 2024-10"},{"t":"기본계획은 사회보장위원회와 국무회의의 심의를 거쳐 확정한다. 대통령령으로 정하는 중요한 사항을 변경할 때도 같다","src":"사회보장기본법 제16조제3항 | 기출 2025-5"},{"t":"기본계획은 다른 법령에 따라 수립되는 사회보장 계획에 우선하며 그 계획의 기본이 된다","src":"사회보장기본법 제17조"},{"t":"연도별 시행계획: 보건복지부장관 및 관계 중앙행정기관의 장이 기본계획에 따라 소관 주요 시책의 시행계획을 매년 수립·시행","src":"사회보장기본법 제18조제1항"},{"t":"시행계획과 전년도 추진실적은 관계 중앙행정기관의 장이 매년 보건복지부장관에게 제출하고, 보건복지부장관이 이를 종합해 성과를 평가한 뒤 사회보장위원회에 보고","src":"사회보장기본법 제18조제2항·제3항"},{"t":"지역계획: 시·도지사와 시장·군수·구청장이 관계 법령에 따라 사회보장에 관한 지역계획을 수립·시행하며 기본계획과 연계되어야 한다","src":"사회보장기본법 제19조"},{"t":"중장기 사회보장 재정추계: 보건복지부장관이 적어도 3년마다 실시하고 공표","src":"사회보장기본법 제30조의3 | 기출 2022-5, 2026-5"}]},{"머리":"사회보장위원회","줄":[{"t":"설치: 사회보장에 관한 주요 시책을 심의·조정하기 위해 국무총리 소속으로 사회보장위원회를 둔다","src":"사회보장기본법 제20조제1항 | 기출 2023-6, 2025-7"},{"t":"심의·조정 사항: 기본계획 / 사회보장 관련 주요 계획 / 제도의 평가 및 개선 / 제도 신설·변경에 따른 우선순위 / 둘 이상 중앙행정기관이 관련된 주요 정책 / 급여 및 비용 부담 / 국가와 지방자치단체의 역할 및 비용 분담 / 재정추계 및 재원조달 방안 / 전달체계 운영 및 개선 / 사회보장통계 / 사회보장정보의 보호 및 관리 / 제26조제4항에 따른 조정 / 위원장이 심의에 부치는 사항","src":"사회보장기본법 제20조제2항 | 기출 2025-5"},{"t":"관계 중앙행정기관의 장과 지방자치단체의 장은 위원회의 심의·조정 사항을 반영하여 사회보장제도를 운영 또는 개선하여야 한다","src":"사회보장기본법 제20조제4항 | 기출 2023-6, 2025-7"},{"t":"구성: 위원장 1명, 부위원장 3명, 행정안전부장관·고용노동부장관·성평등가족부장관·국토교통부장관을 포함한 30명 이내의 위원 (2023 기출 당시 부위원장 2명, 40명 이내)","src":"사회보장기본법 제21조제1항 | 기출 2022-6, 2023-6, 2025-7"},{"t":"위원장은 국무총리, 부위원장은 교육부장관·보건복지부장관·기획예산처장관","src":"사회보장기본법 제21조제2항"},{"t":"위원 구성: 대통령령으로 정하는 관계 중앙행정기관의 장 + 대통령이 위촉하는 근로자 대표·사용자 대표·사회보장 등 관련 분야 학식 경험자·변호사 자격이 있는 사람","src":"사회보장기본법 제21조제3항"},{"t":"위원 임기: 2년. 공무원인 위원은 재임 기간. 기관·단체 대표자 자격으로 위촉된 위원은 대표 지위를 유지하는 기간 (2023·2024·2025 기출에서 3년·4년은 모두 오답)","src":"사회보장기본법 제21조제4항 | 기출 2023-6, 2024-10, 2025-7"},{"t":"보궐위원의 임기는 전임자 임기의 남은 기간","src":"사회보장기본법 제21조제5항"},{"t":"실무위원회를 두고 실무위원회에 분야별 전문위원회를 둘 수 있다. 실무위원회 의결 사항은 위원장에게 보고하고 위원회 심의를 거친다(경미한 사항은 실무위원회 의결로 갈음 가능)","src":"사회보장기본법 제21조제6항·제7항 | 기출 2025-7"},{"t":"사무국: 보건복지부에 둔다(국무총리실·고용노동부 아님)","src":"사회보장기본법 제21조제8항 | 기출 2023-6, 2026-5"}]},{"머리":"운영원칙·비용 부담","줄":[{"t":"운영원칙: 필요로 하는 모든 국민에게 적용 / 급여 수준과 비용 부담에서 형평성 유지 / 정책 결정·시행 과정에 공익의 대표자·이해관계인 참여로 민주적 결정 / 연계성과 전문성 제고","src":"사회보장기본법 제25조제1항~제4항 | 기출 2023-4"},{"t":"책임 주체: 사회보험은 국가의 책임, 공공부조와 사회서비스는 국가와 지방자치단체의 책임으로 시행. 재정 형편 등을 고려해 협의·조정 가능","src":"사회보장기본법 제25조제5항 | 기출 2022-4, 2023-4, 2024-9"},{"t":"사회보장제도 신설·변경 시: 국가와 지방자치단체는 기존 제도와의 관계, 전달체계·재정에 미치는 영향, 지역별 특성을 사전 검토하고 급여가 중복·누락되지 않게 하여야 한다","src":"사회보장기본법 제26조제1항"},{"t":"중앙행정기관의 장과 지방자치단체의 장은 제도를 신설·변경할 때 대통령령에 따라 보건복지부장관과 협의하여야 한다(합의 아님, 기획예산처장관 아님)","src":"사회보장기본법 제26조제2항 | 기출 2024-9, 2026-5"},{"t":"협의가 이루어지지 않으면 사회보장위원회에 조정을 신청할 수 있다. 보건복지부장관은 급여 업무에 공통 적용되는 기준을 마련할 수 있다","src":"사회보장기본법 제26조제4항·제5항"},{"t":"비용 부담 일반: 목적에 따라 국가·지방자치단체·민간부문 간에 합리적으로 조정","src":"사회보장기본법 제28조제1항 | 기출 2025-9"},{"t":"사회보험 비용: 사용자·피용자·자영업자가 부담함을 원칙으로 하되 관계 법령에 따라 국가가 일부 부담할 수 있다","src":"사회보장기본법 제28조제2항 | 기출 2025-9"},{"t":"공공부조 및 일정 소득 수준 이하 국민의 사회서비스 비용: 전부 또는 일부를 국가와 지방자치단체가 부담(지방자치단체 전부 부담 아님)","src":"사회보장기본법 제28조제3항 | 기출 2024-9, 2025-9"},{"t":"부담 능력이 있는 국민의 사회서비스 비용: 수익자 부담 원칙. 국가와 지방자치단체가 일부 부담할 수 있다","src":"사회보장기본법 제28조제4항 | 기출 2024-9, 2025-9"},{"t":"민간 참여: 국가와 지방자치단체는 민간 참여 유도 정책을 개발·시행하고 자원봉사·기부 활성화, 상호협력체계 구축 지원 사업 등을 시책에 포함할 수 있다","src":"사회보장기본법 제27조"}]},{"머리":"전달체계·관리·평가·통계·정보","줄":[{"t":"전달체계: 지역적·기능적으로 균형 잡힌 사회보장 전달체계를 구축하고, 조직·인력·예산을 갖추며, 공공과 민간 전달체계를 연계하도록 노력","src":"사회보장기본법 제29조"},{"t":"급여 관리체계 구축 대상: 수급권자 권리구제 / 사각지대 발굴 / 부정·오류 관리 / 과오지급액 환수 등 관리","src":"사회보장기본법 제30조제1항"},{"t":"보건복지부장관은 사회서비스 품질기준 마련·평가·개선을 위한 전담기구를 설치할 수 있다","src":"사회보장기본법 제30조제2항"},{"t":"사회보장제도의 평가: 보건복지부장관이 장기간 대규모 예산이 투입되는 사업 등 대통령령으로 정하는 제도에 대해 실시할 수 있고, 결과를 사회보장위원회에 보고","src":"사회보장기본법 제30조의2 | 기출 2026-8"},{"t":"사회보장통계: 국가와 지방자치단체가 작성·관리. 관계 중앙행정기관의 장과 지방자치단체의 장이 보건복지부장관에게 제출, 보건복지부장관이 종합해 위원회에 제출(통계청장 아님)","src":"사회보장기본법 제32조 | 기출 2024-9, 2026-8"},{"t":"사회보장에 관한 상담: 국가와 지방자치단체는 관계 법령에 따라 상담에 응하여야 한다. 설명은 노력 의무, 통지는 관계 법령에 따라 알려야 한다","src":"사회보장기본법 제34조~제36조 | 기출 2024-9"},{"t":"국민 등 의견수렴: 국민생활에 중대한 영향을 미치는 계획·정책 수립 시 공청회·정보통신망 등으로 국민과 전문가 의견을 충분히 수렴","src":"사회보장기본법 제40조"},{"t":"행정데이터 분석센터: 보건복지부장관이 설치·운영할 수 있다. 설치·운영 사항은 보건복지부령","src":"사회보장기본법 제43조 | 기출 2026-8"},{"t":"전문인력 양성, 학술 조사·연구, 국제 교류 증진에 노력","src":"사회보장기본법 제31조"}]},{"머리":"사회보장급여법 정의·신청·조사·결정","줄":[{"t":"사회보장급여: 보장기관이 사회보장기본법 제3조제1호에 따라 제공하는 현금·현물·서비스 및 그 이용권","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제2조제1호"},{"t":"수급권자: 사회보장급여를 제공받을 권리를 가진 사람 / 수급자: 사회보장급여를 받고 있는 사람 / 지원대상자: 사회보장급여를 필요로 하는 사람 / 보장기관: 관계 법령에 따라 사회보장급여를 제공하는 국가기관과 지방자치단체","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제2조제2호~제5호 | 기출 2021-8, 2023-8, 2024-12"},{"t":"기본원칙: 필요한 사람은 누구든지 자신의 의사에 따라 신청할 수 있고 보장기관은 안내·상담 등을 충분히 제공 / 누락 방지를 위해 지원대상자를 적극 발굴 / 공정·투명·적정 제공 / 민간 법인·단체·시설의 복지혜택과 연계 / 편리한 이용 / 지역의 사회보장 수준이 균등하게 실현되도록 노력","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제4조 | 기출 2022-7, 2024-11"},{"t":"신청 주체: 지원대상자와 그 친족, 민법에 따른 후견인, 청소년기본법에 따른 청소년상담사·청소년지도사, 지원대상자를 사실상 보호하고 있는 자(관련 기관·단체의 장 포함) 등이 지원대상자의 주소지 관할 보장기관에 신청 (사회복지시설의 장은 사실상 보호하는 자에 해당할 수 있는 신청권자이나 직권 신청 주체는 보장기관의 업무담당자)","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제5조제1항 | 기출 2024-11, 2024-12"},{"t":"직권 신청: 보장기관의 업무담당자가 지원대상자 누락 방지를 위해 직권으로 신청할 수 있다. 이 경우 지원대상자의 동의를 받아야 하며 동의를 받으면 지원대상자가 신청한 것으로 본다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제5조제2항 | 기출 2021-8"},{"t":"심신미약·심신상실 등 대통령령으로 정하는 경우에는 동의 없이도 직권 신청할 수 있고 이 경우 직권 신청 사실을 보장기관의 장에게 지체 없이 보고","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제5조제3항 | 기출 2023-8"},{"t":"신청 시 업무담당자는 근거 법령·조사의 목적·범위·이용방법 / 변동 신고의무 / 정보의 보유기간 및 파기를 고지하여야 한다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제5조제5항"},{"t":"조사: 보장기관의 장은 신청을 받으면 사회보장 요구(요구 사항 / 건강상태·가구 구성 등 생활실태 / 필요한 급여)를 조사하여야 한다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제6조"},{"t":"수급자격 조사 사항: ① 인적사항 및 가족관계 확인 ② 소득·재산·근로능력 및 취업상태 ③ 사회보장급여 수급이력 ④ 그 밖에 수급권자를 선정하기 위해 보장기관의 장이 필요하다고 인정하는 사항. 대상은 지원대상자와 그 부양의무자(배우자와 1촌 직계혈족 및 그 배우자)","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제7조제1항 | 기출 2022-8"},{"t":"조사 과정에서 지원대상자에게 의견을 진술할 기회를 제공하고 조사 방해·기피 또는 자료 제출 요구를 두 번 이상 거부하면 신청을 각하할 수 있다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제7조제5항·제6항"},{"t":"금융정보 등 조사: 금융정보(예금 평균잔액 등)·신용정보(채무액 등)·보험정보(보험료 등) 제공 동의 서면을 받아야 한다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제8조"},{"t":"급여 제공 결정: 제공 여부와 유형을 결정하되 이미 제공받는 급여와 보장내용이 중복되지 않게 하고 서면으로 통지","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제9조"}]},{"머리":"위기가구 발굴·신고의무","줄":[{"t":"위기가구 발굴: 보장기관의 장이 위기가구(관계 기관 공유 정보와 자료 처리 결과 위기상황으로 판단한 가구 / 자살자·자살시도자가 발생한 가구)를 발굴하기 위해 노력하고 지원","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제9조의2 | 기출 2024-11"},{"t":"발굴조사: 보장기관의 장이 지원대상자에 대한 발굴조사를 분기마다 정기적으로 실시(긴급복지지원법 제7조의2에 따른 발굴조사를 실시한 경우 제외). 보건복지부장관은 발굴체계의 운영 실태를 매년 정기적으로 점검하고 개선방안을 마련","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제12조의2 | 기출 2022-7, 2023-8, 2024-12"},{"t":"신고의무: 누구든지 지원대상자를 발견하면 보장기관에 알려야 한다. 직무상 중대한 위기에 처한 지원대상자를 발견한 신고의무자는 지체 없이 알리고 신속히 지원받도록 노력","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제13조제1항·제2항 | 기출 2022-7, 2026-6"},{"t":"신고의무자 26종: 사회복지시설의 장과 종사자 / 장애인활동지원기관 / 의료인·의료기관의 장 / 의료기사 / 응급구조사 / 소방 구조대·구급대원 / 경찰공무원 / 자치경찰공무원 / 정신건강복지센터 종사자 / 어린이집 원장 등 보육교직원 / 유아교육법상 교직원·강사 / 초·중등교육법상 교직원·전문상담교사 / 학원 운영자·강사·직원과 교습소 교습자 / 성폭력피해상담소·보호시설 종사자 / 성매매 지원시설·상담소 종사자 / 가정폭력 상담소·보호시설 종사자 / 건강가정지원센터·가족센터 종사자 / 장기요양기관의 장과 종사자 / 보건소 방문간호 종사자 / 다문화가족지원센터 종사자 / 행정리 이장·통장 / 공동주택 관리주체 / 자살예방센터 종사자 / 전기·수도·도시가스 검침·안전점검 종사자 / 국민연금공단·건강보험공단·근로복지공단의 민원·상담 종사자 / 우편집배원. 고등교육법상 교직원은 포함되지 않는다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제13조제2항 | 기출 2026-6"},{"t":"민관협력: 보장기관과 관계 기관·법인·단체·시설은 지역사회 내 지원대상자 발굴과 가정·지역공동체의 자발적 협조를 위해 노력. 시장·군수·구청장은 지원대상자 발굴 활동 비용을 지원할 수 있다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제14조"}]},{"머리":"이의신청·환수·사후관리","줄":[{"t":"이의신청: 처분을 받은 날부터 90일 이내에 처분을 결정한 보장기관의 장에게 할 수 있다. 정당한 사유로 기간 내 못한 경우 사유가 소멸한 때부터 60일 이내. 보장기관의 장은 신청을 받은 날부터 10일 이내 결정·통지","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제17조 | 기출 2022-7"},{"t":"적정성 확인조사: 보장기관의 장은 수급자에 대한 급여의 적정성을 확인하기 위해 수급자격 조사 사항을 조사할 수 있다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제19조"},{"t":"부정수급 실태조사: 보건복지부장관이 3년마다 실시하고 결과를 공개","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제19조의2 | 기출 2021-8, 2023-8"},{"t":"변동신고: 정기 또는 기간을 정해 급여를 받는 수급자는 거주지·세대원·소득·재산·근로능력·다른 급여 수급이력 등이 변동되면 지체 없이 신고","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제20조"},{"t":"변경·중지: 적정성 확인조사와 변동신고에 따라 직권 또는 신청으로 종류·지급방법을 변경할 수 있고 급여가 필요 없게 되면 중지·변경하여야 한다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제21조"},{"t":"환수: 신고를 고의로 회피하거나 부정한 방법으로 받은 경우 환수할 수 있고(임의) 수급권이 없는 자에게 제공했거나 과잉지급분이 있으면 반환을 명하여야 한다(필요적. 소비한 경우 등 면제 가능)","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제22조"},{"t":"압류 금지: 사회보장급여로 지급된 금품과 이를 받을 권리는 압류하지 못한다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제50조"},{"t":"비밀유지의무와 벌칙: 직무상 비밀 누설은 5년 이하 징역 또는 5천만원 이하 벌금. 부정수급자는 1년 이하 징역 또는 1천만원 이하 벌금","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제49조 제54조"}]},{"머리":"한국사회보장정보원·사회복지전담공무원","줄":[{"t":"한국사회보장정보원: 사회보장정보시스템의 운영·지원을 위해 설립한 법인. 정부는 설립·운영에 필요한 비용을 출연하거나 지원할 수 있다. 업무는 시스템 구축·유지 / 자료·정보 처리 / 급여 업무 전자적 처리지원 / 사회서비스이용권 정보시스템 / 민간 전자화 지원 / 정책·통계정보 생산·분석 / 대국민 포털 운영 등","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제29조 | 기출 2024-11"},{"t":"사회보장사무 전담기구: 특별자치시장·시장·군수·구청장이 업무 효율을 위해 별도 설치할 수 있고 사회보장정보시스템을 활용해 종합 안내","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제42조"},{"t":"사회복지전담공무원: 시·도, 시·군·구, 읍·면·동 또는 전담기구에 둘 수 있고 사회복지사 자격을 가진 사람. 국가는 보수 등 비용의 전부 또는 일부를 보조할 수 있다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제43조"}]},{"머리":"지역사회보장계획·협의체·위원회","줄":[{"t":"지역사회보장계획: 시·도지사 및 시장·군수·구청장이 4년마다 수립하고 매년 연차별 시행계획을 수립. 사회보장 기본계획과 연계","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제35조제1항 | 기출 2025-5"},{"t":"시·군·구 계획: 이해관계인 의견 청취 후 수립 → 지역사회보장협의체 심의 → 시·군·구 의회 보고 → 시·도지사에게 제출. 시·도 계획: 시·도사회보장위원회 심의 → 시·도 의회 보고 → 보건복지부장관에게 제출(보건복지부장관은 사회보장위원회에 보고)","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제35조제2항~제5항 | 기출 2025-5"},{"t":"시·군·구 계획 포함 사항: 수요 측정·목표·추진전략 / 지역사회보장지표 / 분야별 추진전략·연계협력 / 전달체계 / 사각지대 발굴·지원 / 재원 규모·조달 / 통계 수집·관리 / 부정수급 현황 및 방지대책 / 그 밖의 사항","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제36조제1항"},{"t":"시·도 계획 포함 사항: 시·군·구 지원 목표·전략 / 지표 / 급여 이용·제공 기반 구축 / 시·군·구 급여 담당 인력의 양성·전문성 제고 방안 / 통계자료 / 부정수급 방지 지원. 특별자치시 계획은 시·군·구 계획 사항 + 기반 구축 + 인력 양성 방안","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제36조제2항·제3항 | 기출 2024-11"},{"t":"시·도사회보장위원회: 시·도지사가 시·도의 사회보장 증진을 위해 둔다. 심의·자문: 시·도 지역사회보장계획 수립·시행·평가 / 조사·지표 / 급여 제공 / 사회보장 추진 중요 사항 / 특별자치시는 읍·면·동 협의체와 연계·협력","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제40조 | 기출 2025-5, 2026-7, 2026-8"},{"t":"지역사회보장협의체: 시장·군수·구청장이 시·군·구에 둔다. 심의·자문: 시·군·구 계획 수립·시행·평가 / 조사·지표 / 급여 제공 / 사회보장 추진 / 읍·면·동 협의체 구성·운영 / 그 밖의 사항 (국가와 지방자치단체의 역할 및 비용 부담은 포함되지 않는다). 읍·면·동 단위 협의체는 특별자치시장·시장·군수·구청장이 둔다","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제41조 | 기출 2026-7"}]}],"함정":[{"x":"사회보장수급권은 정당한 권한이 있는 기관에게 구두로 통지하여 포기할 수 있다.","o":"서면으로 통지하여 포기할 수 있다.","src":"사회보장기본법 제14조제1항 | 기출 2021-5, 2023-5, 2024-8"},{"x":"사회보장수급권의 포기는 취소할 수 없다.","o":"포기는 취소할 수 있다.","src":"사회보장기본법 제14조제2항 | 기출 2021-5, 2025-4"},{"x":"사회보장수급권은 수급자 임의로 다른 사람에게 양도할 수 있다.","o":"양도·담보 제공 불가, 압류 불가","src":"사회보장기본법 제12조 | 기출 2021-5"},{"x":"사회보장 기본계획은 7년 주기로 수립된다.","o":"5년마다 수립한다. 3년마다도 오답.","src":"사회보장기본법 제16조제1항 | 기출 2025-5, 2026-5"},{"x":"사회보장 기본계획은 사회보장위원회의 심의사항이 아니다.","o":"사회보장위원회와 국무회의의 심의를 거쳐 확정한다.","src":"사회보장기본법 제16조제3항 | 기출 2025-5"},{"x":"사회보험은 지방자치단체의 책임으로 시행하는 것을 원칙으로 한다.","o":"사회보험은 국가의 책임으로 시행한다.","src":"사회보장기본법 제25조제5항 | 기출 2023-4"},{"x":"사회보험은 국가와 지방자치단체의 책임으로 시행한다.","o":"사회보험은 국가의 책임. 공공부조와 사회서비스가 국가와 지방자치단체의 책임.","src":"사회보장기본법 제25조제5항 | 기출 2024-9"},{"x":"일정 소득 수준 이하의 국민에 대한 사회서비스에 드는 비용은 수익자 부담을 원칙으로 한다.","o":"그 비용은 국가와 지방자치단체가 전부 또는 일부 부담한다. 수익자 부담은 부담 능력이 있는 국민의 사회서비스.","src":"사회보장기본법 제28조제3항·제4항 | 기출 2024-9"},{"x":"공공부조에 드는 비용은 지방자치단체가 전부 부담한다.","o":"공공부조 비용은 국가와 지방자치단체가 전부 또는 일부 부담한다.","src":"사회보장기본법 제28조제3항 | 기출 2025-9"},{"x":"통계청장은 제출된 사회보장통계를 종합하여 사회보장위원회에 제출하여야 한다.","o":"보건복지부장관이 종합하여 위원회에 제출한다.","src":"사회보장기본법 제32조제3항 | 기출 2024-9"},{"x":"지방자치단체의 장은 사회보장제도를 신설할 경우 보건복지부장관과 합의하여야 한다.","o":"보건복지부장관과 협의하여야 한다. 기획예산처장관과 협의도 오답.","src":"사회보장기본법 제26조제2항 | 기출 2024-9, 2026-5"},{"x":"지방자치단체가 사회보장제도를 신설할 경우 기획예산처장관과 협의하여야 한다.","o":"보건복지부장관과 협의하여야 한다.","src":"사회보장기본법 제26조제2항 | 기출 2026-5"},{"x":"사회보장위원회의 위원 임기는 3년으로 한다.","o":"위원 임기는 2년이다. 4년도 오답.","src":"사회보장기본법 제21조제4항 | 기출 2024-10, 2023-6, 2025-7"},{"x":"사회보장위원회의 사무국은 국무총리실에 둔다.","o":"보건복지부에 둔다. 고용노동부도 오답.","src":"사회보장기본법 제21조제8항 | 기출 2026-5, 2023-6"},{"x":"사회보장위원회는 대통령 소속의 위원회이다.","o":"국무총리 소속이다.","src":"사회보장기본법 제20조제1항 | 기출 2023-6"},{"x":"국가는 최저보장수준과 최저임금을 2년마다 공표하여야 한다.","o":"국가는 관계 법령에 따라 매년 공표한다. 지방자치단체가 공표한다는 말도 오답.","src":"사회보장기본법 제10조제2항 | 기출 2026-5, 2024-8"},{"x":"지원대상자가 누락되지 않도록 하기 위해 보장기관의 업무담당자는 지원대상자의 동의를 받지 않고도 직권으로 사회보장급여의 제공을 신청할 수 있다.","o":"원칙은 지원대상자의 동의를 받아야 하고 심신미약 등 대통령령 경우에만 동의 없이 가능.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제5조 | 기출 2021-8"},{"x":"보건복지부 장관은 사회보장급여 부정수급 실태조사를 5년마다 실시하고 그 결과를 공개해야 한다.","o":"3년마다.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제19조의2 | 기출 2021-8"},{"x":"이 법에 따른 처분에 이의가 있는 수급권자등은 그 처분을 받은 날부터 30일 이내에 처분을 결정한 보장기관의 장에게 이의신청을 해야 한다.","o":"90일 이내에 할 수 있다.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제17조 | 기출 2021-8"},{"x":"국가와 지방자치단체는 사회보장제도의 안정적인 운영을 위하여 중장기 사회보장 재정추계를 매년 실시하고 이를 공표하여야 한다.","o":"보건복지부장관이 적어도 3년마다 실시하고 공표한다.","src":"사회보장기본법 제30조의3 | 기출 2022-5"},{"x":"보장기관의 장은 「긴급복지지원법」 제7조의2에 따른 발굴조사를 실시한 경우를 제외하고 지원대상자에 대한 발굴조사를 1년마다 정기적으로 실시하여야 한다.","o":"분기마다.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제12조의2 | 기출 2022-7"},{"x":"사회보장수급권은 구두로 통지하여 포기할 수 있다.","o":"서면으로 통지하여 포기할 수 있다.","src":"사회보장기본법 제14조제1항 | 기출 2023-5"},{"x":"“수급권자”란 사회보장급여를 제공하는 국가기관과 지방자치단체를 말한다.","o":"그것은 보장기관. 수급권자는 급여를 제공받을 권리를 가진 사람.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제2조 | 기출 2023-8"},{"x":"보장기관의 업무담당자는 지원대상자가 심신미약 등 대통령령으로 정하는 경우에 해당하면 지원대상자의 동의하에서만 직권으로 사회보장급여의 제공을 신청할 수 있다.","o":"이 경우에는 동의 없이 직권으로 신청할 수 있다.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제5조제3항 | 기출 2023-8"},{"x":"보장기관의 장은 지원대상자 발굴체계의 운영 실태를 3년마다 점검하고 개선방안을 마련하여야 한다.","o":"보건복지부장관이 매년 정기적으로 점검.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제12조의2 | 기출 2023-8"},{"x":"정부는 한국사회보장정보원의 설립ㆍ운영에 필요한 비용을 출연할 수 없다.","o":"출연하거나 지원할 수 있다.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제29조제4항 | 기출 2024-11"},{"x":"“지원대상자”란 사회보장급여를 제공받을 권리를 가진 사람을 말한다.","o":"사회보장급여를 필요로 하는 사람. 급여를 제공받을 권리를 가진 사람은 수급권자.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제2조 | 기출 2024-12"},{"x":"사회복지시설의 장은 사회보장급여의 제공을 직권으로 신청할 수 있다.","o":"직권 신청은 보장기관의 업무담당자가 한다. 시설의 장은 사실상 보호하는 자로서 지원대상자의 주소지 관할 보장기관에 신청할 수 있는 신청권자.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제5조 | 기출 2024-12"},{"x":"국민건강보험공단 이사장은 보험료를 7개월 이상 체납한 사람의 가구정보를 사회보장정보시스템을 통하여 처리할 수 있다.","o":"출제 오답(바른 체납 기간 수치 미확인). 보장기관의 장은 법 제12조에 따라 체납 등 위기정보를 처리할 수 있고 기간은 시행령이 정한다.","src":"보충(원문 미확인) | 기출 2024-12"},{"x":"시ㆍ도지사는 지원대상자에 대한 발굴조사를 1년마다 정기적으로 실시하여야 한다.","o":"보장기관의 장이 분기마다.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제12조의2 | 기출 2024-12"},{"x":"지방자치단체의 장은 지역사회보장계획을 5년마다 수립해야 한다.","o":"시·도지사와 시장·군수·구청장이 4년마다 수립한다.","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제35조제1항 | 기출 2025-5"},{"x":"시ㆍ도 지역사회보장협의체와 시ㆍ군ㆍ구의 사회보장위원회는 지역사회보장계획을 심의ㆍ 의결한다.","o":"시·도사회보장위원회와 시·군·구 지역사회보장협의체가 심의한다(명칭이 뒤바뀜).","src":"사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률 제35조 | 기출 2025-5"},{"x":"보건복지부장관은 사회보장에 관한 기본계획을 3년마다 수립하여야 한다.","o":"5년마다.","src":"사회보장기본법 제16조제1항 | 기출 2026-5"}]},"#5":{"묶음":[{"머리":"기본이념·정의·원칙","줄":[{"t":"기본이념 ①: 사회복지를 필요로 하는 사람은 누구든지 자신의 의사에 따라 서비스를 신청하고 제공받을 수 있다","src":"사회복지사업법 제1조의2제1항 | 기출 2022-9, 2026-11"},{"t":"기본이념 ②: 사회복지법인 및 사회복지시설은 공공성을 가지며 사업 시행에서 공공성을 확보하여야 한다","src":"사회복지사업법 제1조의2제2항"},{"t":"기본이념 ③: 사회복지를 제공하는 자는 필요로 하는 사람의 인권을 보장하여야 한다","src":"사회복지사업법 제1조의2제3항"},{"t":"기본이념 ④: 서비스 제공자는 필요한 정보를 제공하는 등 이용자의 선택권을 보장하여야 한다","src":"사회복지사업법 제1조의2제4항 | 기출 2021-9, 2026-11"},{"t":"사회복지사업 관련 법률(제2조제1호): 국민기초생활 보장법 / 아동복지법 / 노인복지법 / 장애인복지법 / 한부모가족지원법 / 영유아보육법 / 성매매방지 및 피해자보호 등에 관한 법률 / 정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률 / 성폭력방지 및 피해자보호 등에 관한 법률 / 국내입양에 관한 특별법 및 국제입양에 관한 법률 / 일제하 일본군위안부 피해자에 대한 생활안정지원 및 기념사업 등에 관한 법률 / 사회복지공동모금회법 / 장애인·노인·임산부 등의 편의증진 보장에 관한 법률 / 가정폭력방지 및 피해자보호 등에 관한 법률 / 농어촌주민의 보건복지증진을 위한 특별법 / 식품등 기부 활성화에 관한 법률 / 의료급여법 / 기초연금법 / 긴급복지지원법 / 다문화가족지원법 / 장애인연금법 / 장애인활동 지원에 관한 법률 / 노숙인 등의 복지 및 자립지원에 관한 법률 / 보호관찰 등에 관한 법률 / 장애아동 복지지원법 / 발달장애인 권리보장 및 지원에 관한 법률 / 청소년복지 지원법 / 스토킹방지 및 피해자보호 등에 관한 법률 / 그 밖에 대통령령으로 정하는 법률","src":"사회복지사업법 제2조제1호 | 기출 2024-4, 2026-11"},{"t":"지역사회복지: 주민의 복지증진과 삶의 질 향상을 위해 지역사회 차원에서 전개하는 사회복지","src":"사회복지사업법 제2조제2호"},{"t":"사회복지법인: 사회복지사업을 할 목적으로 설립된 법인","src":"사회복지사업법 제2조제3호"},{"t":"사회복지시설: 사회복지사업을 할 목적으로 설치된 시설","src":"사회복지사업법 제2조제4호"},{"t":"사회복지관: 지역사회를 기반으로 일정한 시설과 전문인력을 갖추고 주민의 참여와 협력으로 지역사회의 복지문제를 예방·해결하기 위해 종합적인 복지서비스를 제공하는 시설","src":"사회복지사업법 제2조제5호"},{"t":"사회복지서비스: 사회보장기본법 제3조제4호의 사회서비스 중 사회복지사업을 통한 서비스(사회서비스가 사회복지서비스보다 넓은 개념)","src":"사회복지사업법 제2조제6호 | 기출 2021-10"},{"t":"보건의료서비스: 국민의 건강을 보호·증진하기 위해 보건의료인이 하는 모든 활동","src":"사회복지사업법 제2조제7호"},{"t":"이 법은 제2조제1호 각 목의 법률에 특별한 규정이 없는 사회복지사업의 내용·절차에 적용되고 그 법률을 개정할 때는 이 법에 부합하도록 하여야 한다","src":"사회복지사업법 제3조"},{"t":"국가와 지방자치단체의 책임: 서비스 증진 / 인권침해 예방·차별 금지·인권 옹호 / 사회복지서비스와 보건의료서비스 연계 / 시설의 균형 설치 노력 / 인권교육 강화 / 긴급한 인권침해 신속 대응체계 / 시설 거주자 희망을 반영한 지역사회보호체계 서비스 / 서비스 정보 제공 / 권리침해 사람을 위한 간이·신속한 구제조치","src":"사회복지사업법 제4조"},{"t":"복지업무 종사자는 인권을 존중하고 차별 없이 최대로 봉사하여야 한다. 인권침해 행위가 있으면 국가와 지방자치단체가 처분하고 사실을 공표하는 등 조치","src":"사회복지사업법 제5조"},{"t":"사회복지사업을 하는 자는 필요한 경우 주민의 복지 욕구를 조사할 수 있다","src":"사회복지사업법 제4조제3항 | 기출 2026-11"},{"t":"사회복지의 날: 매년 9월 7일. 그날부터 1주간을 사회복지주간으로 한다","src":"사회복지사업법 제15조의2 | 기출 2021-11"}]},{"머리":"서비스 제공 원칙·자원봉사","줄":[{"t":"서비스 제공은 현물 제공이 원칙이다(현금·현물 병행 아님)","src":"사회복지사업법 제5조의2제1항 | 기출 2021-10, 2023-9, 2024-7, 2026-11"},{"t":"시장·군수·구청장은 국가·지방자치단체 외의 자가 서비스를 제공하게 하는 경우 보호대상자에게 사회복지서비스 이용권을 지급할 수 있다","src":"사회복지사업법 제5조의2제2항 | 기출 2023-9"},{"t":"국가와 지방자치단체는 서비스 품질향상과 원활한 제공을 위해 필요한 시책을 마련하여야 한다","src":"사회복지사업법 제5조의2제3항 | 기출 2023-9"},{"t":"국가와 지방자치단체는 서비스 환경·서비스 제공 인력의 전문성 등을 평가할 수 있다. 보건복지부장관은 평가기관을 설치·운영하거나 평가의 전부 또는 일부를 관계 기관·단체에 위탁할 수 있다(위탁 금지 아님)","src":"사회복지사업법 제5조의2제4항·제5항 | 기출 2023-9"},{"t":"누구든지 정당한 이유 없이 사회복지시설의 설치를 방해하여서는 아니 된다. 시장·군수·구청장도 정당한 이유 없이 설치를 지연시키거나 제한하는 조치를 하여서는 아니 된다","src":"사회복지사업법 제6조 | 기출 2022-9"},{"t":"사회복지 자원봉사활동 지원·육성: 국가와 지방자치단체가 자원봉사활동의 홍보 및 교육 / 프로그램 개발·보급 / 활동 중 재해 대비 시책 개발 / 그 밖의 지원 사항을 실시하여야 한다. 사회복지법인 등 비영리법인·단체에 위탁할 수 있다","src":"사회복지사업법 제9조 | 기출 2024-7"},{"t":"보건복지부장관은 공무원과 사회복지사업 종사자의 자질 향상을 위해 인권교육 등 지도와 훈련을 할 수 있다","src":"사회복지사업법 제10조"}]},{"머리":"사회복지사","줄":[{"t":"자격증 발급: 보건복지부장관이 사회복지에 관한 전문지식과 기술을 가진 사람에게 발급할 수 있다(시·도지사 아님). 신청일 기준 결격사유에 해당하면 발급 불가","src":"사회복지사업법 제11조제1항 | 기출 2024-7"},{"t":"등급은 1급·2급이고 정신건강·의료·학교 영역은 정신건강사회복지사·의료사회복지사·학교사회복지사 자격을 부여할 수 있다","src":"사회복지사업법 제11조제2항 | 기출 2023-10"},{"t":"1급은 국가시험 합격자에게 부여한다. 영역별 사회복지사는 1급 자격자 중 보건복지부령으로 정하는 수련기관에서 수련을 받은 사람에게 부여한다","src":"사회복지사업법 제11조제3항"},{"t":"자격증을 다른 사람에게 빌려주거나 빌리면 안 되고 알선도 금지. 위반 시 1년 이하의 징역 또는 1천만원 이하의 벌금(10년·1억원 아님)","src":"사회복지사업법 제11조제6항·제7항 제54조 | 기출 2023-10, 2024-7"},{"t":"사회복지사 결격사유: 피성년후견인 / 금고 이상 실형 선고 후 집행이 끝나거나 면제되지 않은 사람 / 금고 이상 집행유예 기간 중인 사람 / 법원 판결로 자격이 상실·정지된 사람 / 마약·대마·향정신성의약품 중독자 / 정신질환자(전문의가 적합하다고 인정하는 사람은 제외). 피한정후견인은 이 목록에 없다","src":"사회복지사업법 제11조의2 | 기출 2025-10"},{"t":"자격 취소·정지: 보건복지부장관은 자격을 취소하거나 1년의 범위에서 정지시킬 수 있다. 제1호~제3호는 반드시 취소","src":"사회복지사업법 제11조의3제1항 | 기출 2021-10, 2022-9, 2023-10, 2025-10"},{"t":"필요적 취소 사유: ① 거짓이나 그 밖의 부정한 방법으로 자격 취득 ② 결격사유에 해당하게 됨 ③ 자격증 대여·양도 또는 위조·변조","src":"사회복지사업법 제11조의3제1항제1호~제3호 | 기출 2022-9, 2023-10"},{"t":"취소·정지 임의 사유: ④ 업무수행 중 고의·중대한 과실로 타인에게 손해를 입힘 ⑤ 자격정지 처분 3회 이상 또는 정지 종료 후 3년 이내 재차 정지 해당 행위 ⑥ 자격정지 기간에 자격증을 사용해 업무 수행","src":"사회복지사업법 제11조의3제1항제4호~제6호 | 기출 2025-10"},{"t":"④에 해당해 취소·정지하려면 한국사회복지사협회의 장 등 관계 전문가의 의견을 들을 수 있다","src":"사회복지사업법 제11조의3제2항"},{"t":"취소된 사람은 취소된 날부터 15일 내에 자격증을 반납하고 취소된 날부터 2년 이내에는 재교부를 받지 못한다","src":"사회복지사업법 제11조의3제3항·제4항 | 기출 2025-10"},{"t":"사회복지사가 아니면 사회복지사 또는 유사한 명칭을 사용하지 못한다","src":"사회복지사업법 제11조의4"},{"t":"국가시험은 보건복지부장관이 시행하고 관리는 전문기관에 위탁할 수 있다","src":"사회복지사업법 제12조"},{"t":"사회복지법인·시설 운영자는 사회복지사를 종사자로 채용하고 임면 사항을 시·도지사 또는 시장·군수·구청장에게 보고하여야 한다(대통령령으로 정하는 시설 제외)","src":"사회복지사업법 제13조제1항"},{"t":"보수교육: 법인·시설에 종사하는 사회복지사는 정기적으로 인권에 관한 내용이 포함된 보수교육을 받아야 한다. 교육을 이유로 불리한 처분을 하여서는 아니 된다","src":"사회복지사업법 제13조제2항·제3항 | 기출 2023-10, 2025-10"},{"t":"한국사회복지사협회: 사회복지사의 전문지식·기술 개발·보급 / 교육훈련 / 복지증진을 위해 설립한 법인. 민법 중 사단법인 규정 준용","src":"사회복지사업법 제46조 | 기출 2024-7"},{"t":"사회복지에 관한 조사·연구 및 정책 건의는 사회복지협의회의 업무(협회 아님). 협의회는 중앙(한국사회복지협의회)·시·도·시·군·구 3단계이고 사회복지법인으로 한다","src":"사회복지사업법 제33조 | 기출 2024-7"}]},{"머리":"사회복지법인","줄":[{"t":"설립허가: 대통령령에 따라 시·도지사의 허가(보건복지부장관 허가·시·도지사 인가 아님). 허가 후 주된 사무소 소재지에서 설립등기","src":"사회복지사업법 제16조 | 기출 2021-10, 2022-9, 2026-10"},{"t":"정관 필수 기재 11가지: 목적 / 명칭 / 주된 사무소의 소재지 / 사업의 종류 / 자산 및 회계에 관한 사항 / 임원의 임면 등에 관한 사항 / 회의에 관한 사항 / 수익사업이 있는 경우 그에 관한 사항 / 정관의 변경에 관한 사항 / 존립시기와 해산 사유를 정한 경우 그 시기·사유 및 남은 재산의 처리방법 / 공고 및 공고방법","src":"사회복지사업법 제17조제1항 | 기출 2024-5, 2026-10"},{"t":"정관 변경은 시·도지사의 인가(경미한 사항은 제외)","src":"사회복지사업법 제17조제2항"},{"t":"임원 수: 대표이사를 포함한 이사 7명 이상과 감사 2명 이상","src":"사회복지사업법 제18조제1항 | 기출 2022-11"},{"t":"이사 정수의 3분의 1 이상은 시·도사회보장위원회 또는 지역사회보장협의체가 3배수로 추천한 사람 중에서 선임","src":"사회복지사업법 제18조제2항"},{"t":"특별한 관계에 있는 사람은 이사 현원의 5분의 1을 초과할 수 없다. 외국인 이사는 이사 현원의 2분의 1 미만","src":"사회복지사업법 제18조제3항·제5항"},{"t":"임기: 이사 3년 감사 2년 각각 연임할 수 있다(이사·감사 모두 3년이라는 선지는 오답)","src":"사회복지사업법 제18조제4항 | 기출 2026-10"},{"t":"임원을 임면하면 지체 없이 시·도지사에게 보고하여야 한다","src":"사회복지사업법 제18조제6항 | 기출 2024-5"},{"t":"감사는 이사와 특별한 관계가 없어야 하고 감사 중 1명은 법률 또는 회계 지식이 있는 사람 중에서 선임","src":"사회복지사업법 제18조제7항"},{"t":"임원 결격사유: 미성년자 / 피성년후견인 또는 피한정후견인 / 파산선고를 받고 복권되지 아니한 사람 / 법원 판결로 자격 상실·정지 / 금고 이상 실형 집행 종료·면제 후 3년 미경과 / 금고 이상 집행유예 기간 중 / 사회복지사업 관련 범죄 등(벌금 100만원 이상 확정 후 5년, 집행유예 확정 후 7년, 징역형 집행 종료 후 7년) / 성폭력·아동청소년 성범죄 10년 / 아동학대관련범죄 / 해임명령으로 해임된 날부터 5년 / 설립허가 취소 법인의 임원이었던 사람 5년 / 시설의 장에서 해임된 날부터 5년 / 폐쇄명령 후 3년 / 사회복지분야 6급 이상 공무원 퇴직 3년 미경과","src":"사회복지사업법 제19조제1항 | 기출 2022-11"},{"t":"임원이 결격사유에 해당하게 되면 자격을 상실한다","src":"사회복지사업법 제19조제2항"},{"t":"결원 보충: 이사 또는 감사 중 결원이 생기면 2개월 이내에 보충(3개월 아님)","src":"사회복지사업법 제20조 | 기출 2024-5"},{"t":"겸직 금지: 이사는 법인이 설치한 시설의 장을 제외한 그 시설의 직원을 겸할 수 없다(시설의 장은 겸할 수 있음). 감사는 이사·시설의 장·시설 직원을 겸할 수 없다","src":"사회복지사업법 제21조 | 기출 2022-11, 2026-10"},{"t":"임원 해임명령: 시·도지사가 명령 불이행 / 회계부정·인권침해 등 불법행위 / 보고 지연·거짓 보고 / 제18조 위반 선임 / 겸직 금지 위반 / 직무집행 정지명령 불이행 / 그 밖의 법 위반 시. 시정 요구 후 15일이 지나도 응하지 않은 경우에 한함(중대한 비리는 시정요구 없이 가능). 해임명령을 받은 법인은 2개월 이내에 이사회를 소집하여야 한다","src":"사회복지사업법 제22조"},{"t":"재산: 사업 운영에 필요한 재산을 소유하여야 한다. 기본재산과 보통재산으로 구분하고 기본재산 목록·가액은 정관에 기재","src":"사회복지사업법 제23조제1항·제2항 | 기출 2024-5"},{"t":"기본재산의 매도·증여·교환·임대·담보제공·용도변경이나 일정 금액 이상 1년 이상 장기차입은 시·도지사의 허가","src":"사회복지사업법 제23조제3항"},{"t":"재산을 취득하면 지체 없이 법인 재산으로 편입하고 취득 사유·종류·수량·가액을 매년 시·도지사에게 보고","src":"사회복지사업법 제24조"},{"t":"회의록: 개의·회의 중지·산회 일시 / 안건 / 의사 / 출석 임원 성명 / 표결수 / 그 밖에 대표이사가 필요하다고 인정하는 사항을 기재. 출석임원 전원이 날인하고 2매 이상이면 간인. 회의록은 공개(대통령령 사항은 이사회 의결로 비공개 가능)","src":"사회복지사업법 제25조 | 기출 2022-11"},{"t":"설립허가 취소: 시·도지사가 시정명령 또는 취소할 수 있다. 제1호(거짓·부정한 방법으로 허가)와 제7호(설립 후 기본재산 미출연)는 반드시 취소","src":"사회복지사업법 제26조제1항 | 기출 2022-9, 2025-11"},{"t":"임의적 취소·시정명령 사유: 설립허가 조건 위반 / 목적 달성 불가능 / 목적사업 외의 사업 / 허가일부터 6개월 이내 미시작 또는 1년 이상 사업실적 없음 / 시설에서 반복적·집단적 성폭력범죄·학대관련범죄 / 중대하고 반복적인 회계부정·불법행위 / 임원정수 위반 / 제18조제2항 위반 이사 선임 / 해임명령 불이행 / 그 밖의 법령·정관 위반","src":"사회복지사업법 제26조제1항 | 기출 2024-5, 2025-11"},{"t":"해산한 법인의 남은 재산은 정관으로 정하는 바에 따라 국가 또는 지방자치단체에 귀속된다(유사 목적 다른 법인 귀속 아님)","src":"사회복지사업법 제27조 | 기출 2022-11, 2026-10"},{"t":"수익사업: 설립 목적 수행에 지장 없는 범위에서 가능. 수익은 법인·시설 운영 외 목적에 사용 금지. 회계는 구분 처리","src":"사회복지사업법 제28조"},{"t":"합병: 시·도지사의 허가. 주된 사무소가 서로 다른 시·도에 있으면 보건복지부장관의 허가","src":"사회복지사업법 제30조"}]},{"머리":"사회복지시설","줄":[{"t":"설치: 국가나 지방자치단체는 시설을 설치·운영할 수 있다. 국가·지방자치단체 외의 자는 시장·군수·구청장에게 신고(보건복지부 신고·허가 아님)","src":"사회복지사업법 제34조제1항·제2항 | 기출 2022-10, 2023-11, 2024-6, 2025-12, 2026-9"},{"t":"신고 불가 사유: 폐쇄명령 후 3년 미경과 / 임원 결격사유(제19조제1항 일부)에 해당하는 개인 또는 그 개인이 임원인 법인","src":"사회복지사업법 제34조제2항"},{"t":"시장·군수·구청장은 신고 내용이 이 법에 적합하면 수리하여야 한다","src":"사회복지사업법 제34조제3항"},{"t":"국가·지방자치단체가 설치한 시설은 사회복지법인이나 비영리법인에 위탁 운영하게 할 수 있다","src":"사회복지사업법 제34조제5항"},{"t":"통합 설치·운영: 둘 이상의 시설을 하나로 설치하거나 하나의 시설에서 둘 이상의 사회복지사업을 통합 수행할 수 있다","src":"사회복지사업법 제34조의2 | 기출 2023-11"},{"t":"보험가입 의무: 시설 운영자는 화재 및 화재 외 안전사고로 인한 손해배상책임을 위해 책임보험 또는 한국사회복지공제회 책임공제에 가입하여야 한다. 국가·지방자치단체는 비용의 전부 또는 일부를 보조할 수 있다(전부 보조 의무 아님)","src":"사회복지사업법 제34조의3 | 기출 2022-10, 2024-6, 2023-11"},{"t":"안전점검: 시설의 장이 정기 및 수시 안전점검을 실시하고 결과를 시장·군수·구청장에게 제출한다(법인의 대표·시장이 실시하는 것 아님). 시장·군수·구청장은 보완·개수·보수를 요구할 수 있다","src":"사회복지사업법 제34조의4 | 기출 2022-10, 2026-9"},{"t":"사회복지관 사업: 지역 특성과 복지욕구를 고려한 서비스 제공 / 사례관리 / 복지자원 관리·주민교육·조직화 / 그 밖에 지역사회가 요청하는 사업","src":"사회복지사업법 제34조의5제1항"},{"t":"사회복지관 우선 제공 대상: 기초생활보장 수급자 및 차상위계층 / 장애인·노인·한부모가족·다문화가족 / 직업 및 취업 알선이 필요한 사람 / 보호와 교육이 필요한 유아·아동·청소년 / 그 밖에 필요하다고 인정되는 사람","src":"사회복지사업법 제34조의5제2항 | 기출 2024-6, 2025-12, 2026-9"},{"t":"시설의 장은 상근하여야 한다(비상근 겸직 불가)","src":"사회복지사업법 제35조제1항 | 기출 2023-11, 2025-12"},{"t":"시설의 장 결격: 임원 결격사유 등 해당자 / 해임명령으로 해임된 날부터 5년 미경과 / 6급 이상 사회복지분야 공무원 퇴직 3년 미경과","src":"사회복지사업법 제35조제2항"},{"t":"종사자: 법인·시설 운영자는 시설에 근무할 종사자를 채용할 수 있다. 결격사유(제19조제1항제1호의7~제1호의9 등)에 해당하면 종사자가 될 수 없다","src":"사회복지사업법 제35조의2 | 기출 2022-10"},{"t":"운영위원회: 시설의 장이 시설 운영에 관한 사항을 심의하기 위해 두어야 한다(심의기구이고 의결기구 아님)","src":"사회복지사업법 제36조제1항 | 기출 2022-10, 2023-11, 2025-12"},{"t":"운영위원회 심의 사항: 시설운영계획 수립·평가 / 사회복지 프로그램 개발·평가 / 종사자 근무환경 개선 / 거주자 생활환경 개선 및 고충 처리 / 종사자·거주자 인권보호 및 권익증진 / 시설과 지역사회의 협력 / 그 밖에 시설의 장이 회의에 부치는 사항","src":"사회복지사업법 제36조제1항 | 기출 2024-6"},{"t":"운영위원 구성: 시설의 장 / 거주자 대표 / 거주자 보호자 대표 / 종사자 대표 / 해당 시·군·구 사회복지업무 담당 공무원 / 후원자 대표 또는 지역주민 / 공익단체 추천인 / 전문 지식·경험이 풍부한 사람. 관할 시장·군수·구청장이 임명하거나 위촉","src":"사회복지사업법 제36조제2항"},{"t":"시설의 장이 운영위원회에 보고할 사항: 회계 및 예산·결산 / 후원금 조성 및 집행 / 시설운영 관련 사건·사고","src":"사회복지사업법 제36조제3항"},{"t":"휴지·재개·폐지: 시설 운영자는 운영을 일정 기간 중단하거나 다시 시작하거나 폐지하려면 시장·군수·구청장에게 신고하여야 한다","src":"사회복지사업법 제38조제2항 | 기출 2026-9"},{"t":"개선·사업정지·장 교체·폐쇄 명령: 보건복지부장관·시·도지사·시장·군수·구청장이 설치기준 미달 / 법인 설립허가 취소 / 설치 목적 달성 / 회계부정·불법행위 / 무신고 설치·운영 / 운영위원회 미설치·미운영 / 보고·자료제출 거부 / 검사·질문 거부 / 성폭력·학대관련범죄 발생 / 1년 이상 휴지 후 재개 권고 불응 시 명할 수 있다","src":"사회복지사업법 제40조제1항 | 기출 2024-6, 2026-9"},{"t":"수용인원: 각 시설의 수용인원은 300명 초과 불가(대통령령 정하는 경우 제외). 200명이라는 선지는 오답","src":"사회복지사업법 제41조 | 기출 2025-12"},{"t":"재가복지서비스: 가정봉사서비스(가사·개인활동 지원·정서활동 지원)와 주간·단기 보호서비스. 시설 입소에 우선하여 제공하여야 한다","src":"사회복지사업법 제41조의2"},{"t":"보조금: 국가·지방자치단체가 운영비 등을 보조할 수 있다. 목적 외 사용 금지. 거짓·부정 수령과 목적 외 사용은 반환을 명하여야 한다","src":"사회복지사업법 제42조"},{"t":"서비스 최저기준: 보건복지부장관이 마련하여야 하며 시설 운영자는 이 기준 이상을 유지하여야 한다(적정기준 아님)","src":"사회복지사업법 제43조 | 기출 2021-10, 2023-16"},{"t":"시설 평가: 보건복지부장관과 시·도지사가 정기적으로 평가하고 결과를 공표하거나 감독·지원에 반영할 수 있다","src":"사회복지사업법 제43조의2"},{"t":"후원금: 법인 대표이사와 시설의 장은 후원금 수입·지출 내용을 공개하여야 한다","src":"사회복지사업법 제45조"},{"t":"비밀누설 금지 / 이 법과 관련 법률에 따라 지급된 금품과 받을 권리는 압류 불가","src":"사회복지사업법 제47조 제48조"},{"t":"비용 징수: 복지조치 비용을 부담한 지방자치단체의 장이나 시설 운영자는 수혜자 본인 또는 부양의무자로부터 비용의 전부 또는 일부를 징수할 수 있다","src":"사회복지사업법 제44조"},{"t":"벌칙: 기본재산 허가 위반과 보조금 목적 외 사용은 5년 이하 징역 또는 5천만원 이하 벌금. 시설 설치방해 / 자격증 대여·알선 / 무신고 시설 운영 / 비밀누설 등은 1년 이하 징역 또는 1천만원 이하 벌금. 사회복지사 임면 보고 위반은 300만원 이하 벌금","src":"사회복지사업법 제53조~제55조"}]},{"머리":"시행령·서비스 최저기준 적용 시설","줄":[{"t":"서비스 최저기준 대상 시설 예: 사회복지관 / 아동양육시설 / 장애인 지역사회재활시설 / 부자가족복지시설 등. 자원봉사센터는 최저기준 마련 대상이 아님","src":"기출 2023-16 | 보충(원문 미확인)"}]}],"함정":[{"x":"보건복지부장관은 사회복지서비스 품질 평가를 위한 전문기관을 직접 설치ㆍ운영해야 하며, 관계기관 등에 위탁하여서는 아니 된다.","o":"평가기관을 설치·운영하거나 전부 또는 일부를 위탁할 수 있다.","src":"사회복지사업법 제5조의2제5항 | 기출 2023-9"},{"x":"대통령령으로 정하는 경우를 제외하고, 각 시설의 수용인원은 200명을 초과할 수 없다.","o":"300명.","src":"사회복지사업법 제41조 | 기출 2025-12"},{"x":"시설의 장은 비상근 겸직할 수 있다.","o":"상근하여야 한다.","src":"사회복지사업법 제35조제1항 | 기출 2025-12"},{"x":"법인을 설립하려는 자는 시ㆍ도지사의 인가를 받아야 한다.","o":"허가를 받아야 한다.","src":"사회복지사업법 제16조제1항 | 기출 2026-10"},{"x":"사회복지서비스는 현물과 현금으로 제공되는 것을 원칙으로 한다.","o":"현물 제공이 원칙.","src":"사회복지사업법 제5조의2제1항 | 기출 2026-11"},{"x":"사회복지서비스는 현금과 현물로 제공하는 것을 원칙으로 한다.","o":"현물로 제공하는 것이 원칙이다.","src":"사회복지사업법 제5조의2제1항 | 기출 2024-7, 2026-11"},{"x":"사회복지법인은 보건복지부장관의 허가를 받아 설립한다.","o":"시·도지사의 허가를 받아 설립한다.","src":"사회복지사업법 제16조제1항 | 기출 2021-10"},{"x":"사회복지법인이 설립 후 기본재산을 출연하지 아니한 때 시·도지사는 시정명령을 내릴 수 있다.","o":"기본재산을 출연하지 아니한 때는 설립허가를 반드시 취소하여야 한다.","src":"사회복지사업법 제26조제1항제7호 | 기출 2022-9, 2025-11"},{"x":"사회복지사 자격은 1년을 초과하여 정지시킬 수 있다.","o":"보건복지부장관은 1년의 범위에서 정지시킬 수 있다.","src":"사회복지사업법 제11조의3제1항 | 기출 2021-10"},{"x":"보건복지부장관은 사회복지사가 거짓이나 그 밖의 부정한 방법으로 자격을 취득한 경우 그 자격을 1년의 범위에서 정지할 수 있다.","o":"이 경우 자격을 취소하여야 한다.","src":"사회복지사업법 제11조의3제1항제1호 | 기출 2023-10"},{"x":"보건복지부장관은 시설에서 제공하는 서비스의 적정기준을 마련하여야 한다.","o":"서비스의 최저기준을 마련하여야 한다.","src":"사회복지사업법 제43조제1항 | 기출 2021-10"},{"x":"피성년후견인 또는 피한정후견인은 사회복지사가 될 수 없다.","o":"사회복지사 결격사유는 피성년후견인이다(피한정후견인은 해당하지 않음). 임원 결격사유에는 피한정후견인도 포함.","src":"사회복지사업법 제11조의2 제19조 | 기출 2025-10"},{"x":"사회복지사 자격증을 다른 사람에게 빌려주거나 빌린 사람은 10년 이하의 징역 또는 1억원 이하의 벌금에 처한다.","o":"1년 이하의 징역 또는 1천만원 이하의 벌금.","src":"사회복지사업법 제54조제1호의2 | 기출 2024-7"},{"x":"시ㆍ도지사는 사회복지에 관한 전문지식과 기술을 가진 사람에게 사회복지사 자격증을 발급할 수 있다.","o":"보건복지부장관이 발급한다.","src":"사회복지사업법 제11조제1항 | 기출 2024-7"},{"x":"사회복지에 관한 조사ㆍ연구 및 정책 건의를 위하여 한국사회복지사협회를 둔다.","o":"사회복지협의회를 둔다.","src":"사회복지사업법 제33조 | 기출 2024-7"},{"x":"보건복지부장관은 사회복지서비스 품질 평가를 위한 전문기관을 직접 설치ㆍ운영해야 하며 관계기관 등에 위탁하여서는 아니 된다.","o":"평가기관을 설치·운영하거나 평가의 전부 또는 일부를 위탁할 수 있다.","src":"사회복지사업법 제5조의2제5항 | 기출 2023-9"},{"x":"지방자치단체가 시설을 설치ㆍ운영하려는 경우에는 보건복지부에 신고하여야 한다.","o":"국가나 지방자치단체는 신고 없이 설치·운영할 수 있다. 국가·지방자치단체 외의 자가 시장·군수·구청장에게 신고한다.","src":"사회복지사업법 제34조 | 기출 2022-10"},{"x":"지방자치단체는 사회복지시설을 설치ㆍ운영하여서는 아니 된다.","o":"국가나 지방자치단체는 시설을 설치·운영할 수 있다.","src":"사회복지사업법 제34조제1항 | 기출 2023-11"},{"x":"사회복지법인의 대표는 시설에 대하여 정기 및 수시 안전점검을 실시하여야 한다.","o":"시설의 장이 실시한다.","src":"사회복지사업법 제34조의4제1항 | 기출 2022-10"},{"x":"시장ㆍ군수ㆍ구청장은 시설에 대하여 정기 및 수시 안전점검을 실시하여야 한다.","o":"시설의 장이 실시하고 결과를 시장·군수·구청장에게 제출한다.","src":"사회복지사업법 제34조의4 | 기출 2026-9"},{"x":"시설의 장은 시설의 운영에 관한 사항을 의결하기 위하여 시설에 운영위원회를 두어야 한다.","o":"운영위원회는 심의하기 위해 둔다.","src":"사회복지사업법 제36조제1항 | 기출 2022-10, 2025-12"},{"x":"사회복지시설 운영위원회는 심의ㆍ의결기구이다.","o":"심의기구이다.","src":"사회복지사업법 제36조제1항 | 기출 2023-11"},{"x":"지방자치단체는 시설의 책임보험 가입에 드는 비용의 전부를 보조하여야 한다.","o":"비용의 전부 또는 일부를 보조할 수 있다.","src":"사회복지사업법 제34조의3제2항 | 기출 2022-10"},{"x":"지방자치단체는 시설의 책임보험 가입에 드는 비용의 전부를 보조할 수 없다.","o":"전부 또는 일부를 보조할 수 있다(전부 보조도 가능).","src":"사회복지사업법 제34조의3제2항 | 기출 2024-6"},{"x":"사회복지시설은 손해배상책임의 면책사업자이다.","o":"시설 운영자는 책임보험 또는 책임공제에 가입하여야 한다.","src":"사회복지사업법 제34조의3 | 기출 2023-11"},{"x":"사회복지시설의 장은 비상근으로 근무할 수 있다.","o":"시설의 장은 상근하여야 한다.","src":"사회복지사업법 제35조제1항 | 기출 2023-11, 2025-12"},{"x":"사회복지관은 사회복지서비스를 직업 및 취업 알선이 필요한 사람에게 우선 제공할 수 없다.","o":"우선 제공하여야 한다.","src":"사회복지사업법 제34조의5제2항 | 기출 2025-12"},{"x":"법인이 설치한 사회복지시설의 장과 직원은 그 법인의 이사를 겸할 수 없다.","o":"이사는 시설의 장을 겸할 수 있다. 시설의 직원은 겸할 수 없다.","src":"사회복지사업법 제21조제1항 | 기출 2022-11"},{"x":"이사는 법인이 설치한 사회복지시설의 장을 겸할 수 없다.","o":"시설의 장은 겸할 수 있다.","src":"사회복지사업법 제21조제1항 | 기출 2026-10"},{"x":"해산한 법인의 남은 재산은 유사한 목적을 가진 다른 법인에 귀속된다.","o":"정관으로 정하는 바에 따라 국가 또는 지방자치단체에 귀속된다.","src":"사회복지사업법 제27조 | 기출 2026-10"},{"x":"법인의 이사와 감사의 임기는 3년으로 한다.","o":"이사 3년 감사 2년.","src":"사회복지사업법 제18조제4항 | 기출 2026-10"},{"x":"감사 중에 결원이 생겼을 때 3개월 이내에 보충하여야 한다.","o":"2개월 이내에 보충한다.","src":"사회복지사업법 제20조 | 기출 2024-5"},{"x":"「사회보장기본법」상 사회서비스는 사회복지서비스의 범위에 포함되는 개념이다.","o":"사회복지서비스가 사회서비스의 범위에 포함된다(사회서비스 중 사회복지사업을 통한 서비스).","src":"사회복지사업법 제2조제6호 | 기출 2021-10"},{"x":"사회복지를 필요로 하는 사람은 누구든지 자신의 의사와 상관없이 서비스를 신청하고 제공받을 수 있다.","o":"자신의 의사에 따라 신청하고 제공받는다.","src":"사회복지사업법 제1조의2제1항 | 기출 2026-11"},{"x":"사회복지사업을 하는 자는 주민의 복지 욕구를 조사할 수 없다.","o":"필요한 경우 주민의 복지 욕구를 조사할 수 있다.","src":"사회복지사업법 제4조제3항 | 기출 2026-11"},{"x":"사회복지서비스를 제공하는 자는 사회복지서비스를 이용하는 사람의 선택권을 보장하지 않아도 된다.","o":"선택권을 보장하여야 한다.","src":"사회복지사업법 제1조의2제4항 | 기출 2026-11"}]},"#6":{"묶음":[{"머리":"기초생활보장법 목적·정의·원칙","줄":[{"t":"국민기초생활 보장법 목적: 생활이 어려운 사람에게 필요한 급여를 실시해 최저생활을 보장하고 자활을 돕는 것","src":"국민기초생활 보장법 제1조"},{"t":"수급권자: 이 법에 따른 급여를 받을 수 있는 자격을 가진 사람","src":"국민기초생활 보장법 제2조제1호"},{"t":"수급자: 이 법에 따른 급여를 받는 사람","src":"국민기초생활 보장법 제2조제2호"},{"t":"수급품: 수급자에게 지급하거나 대여하는 금전 또는 물품","src":"국민기초생활 보장법 제2조제3호"},{"t":"보장기관: 이 법에 따른 급여를 실시하는 국가 또는 지방자치단체","src":"국민기초생활 보장법 제2조제4호"},{"t":"부양의무자: 수급권자의 1촌의 직계혈족 및 그 배우자(사망한 1촌 직계혈족의 배우자는 제외)","src":"국민기초생활 보장법 제2조제5호"},{"t":"최저보장수준: 국민의 소득·지출 수준과 가구 유형 등 생활실태 물가상승률 등을 고려해 제6조에 따라 급여 종류별로 공표하는 금액이나 보장수준","src":"국민기초생활 보장법 제2조제6호 | 기출 2026-12"},{"t":"최저생계비: 건강하고 문화적인 생활 유지에 필요한 최소한의 비용으로 보건복지부장관이 계측하는 금액","src":"국민기초생활 보장법 제2조제7호"},{"t":"개별가구: 급여를 받거나 자격요건 조사를 받는 기본단위로서 수급자 또는 수급권자로 구성된 가구","src":"국민기초생활 보장법 제2조제8호"},{"t":"소득인정액: 개별가구의 소득평가액과 재산의 소득환산액을 합산한 금액","src":"국민기초생활 보장법 제2조제9호 | 기출 2026-12"},{"t":"차상위계층: 수급권자에 해당하지 않는 계층으로서 소득인정액이 대통령령으로 정하는 기준 이하인 계층","src":"국민기초생활 보장법 제2조제10호"},{"t":"기준 중위소득: 보건복지부장관이 중앙생활보장위원회 심의·의결을 거쳐 고시하는 국민 가구소득의 중위값","src":"국민기초생활 보장법 제2조제11호"},{"t":"급여의 기본원칙: 수급자가 소득·재산·근로능력 등을 활용해 최대한 노력하는 것을 전제로 이를 보충·발전시킨다(보충급여·근로능력 활용)","src":"국민기초생활 보장법 제3조제1항 | 기출 2023-13"},{"t":"부양의무자의 부양과 다른 법령에 따른 보호가 이 법의 급여에 우선한다(타법 우선). 다른 법령의 보호 수준이 이 법의 수준에 못 미치면 나머지는 이 법에 따라 받을 권리를 잃지 않는다","src":"국민기초생활 보장법 제3조제2항 | 기출 2023-13"},{"t":"급여는 건강하고 문화적인 최저생활을 유지할 수 있어야 한다. 기준은 연령 가구 규모 거주지역 생활여건 등을 고려해 급여 종류별로 보건복지부장관이 정하거나 소관 중앙행정기관의 장이 보건복지부장관과 협의해 정한다","src":"국민기초생활 보장법 제4조제1항·제2항"},{"t":"급여는 개별가구 단위로 실시한다. 장애 정도가 심한 장애인 등 필요한 경우 개인 단위로 실시할 수 있다","src":"국민기초생활 보장법 제4조제3항"},{"t":"지방자치단체는 조례로 정하는 바에 따라 이 법의 급여 범위·수준을 초과하여 급여를 실시할 수 있다. 초과 비용은 해당 지방자치단체가 부담","src":"국민기초생활 보장법 제4조제4항 제43조제5항"},{"t":"외국인 특례: 국내 체류 외국인 중 ① 대한민국 국민과 혼인해 본인 또는 배우자가 임신 중인 사람 ② 대한민국 국적의 미성년 자녀를 양육하는 사람 ③ 배우자의 대한민국 국적인 직계존속과 생계나 주거를 같이하는 사람으로서 대통령령으로 정하는 사람이 급여 자격을 가진 경우 수급권자가 된다(직계비속·성인 장애인 동거는 아님)","src":"국민기초생활 보장법 제5조의2 | 기출 2021-12, 2025-18"},{"t":"최저보장수준 결정: 보건복지부장관 또는 소관 중앙행정기관의 장이 급여 종류별 수급자 선정기준과 최저보장수준을 결정하고, 매년 8월 1일까지 중앙생활보장위원회 심의·의결을 거쳐 다음 연도 기준을 공표","src":"국민기초생활 보장법 제6조 | 기출 2026-12"},{"t":"기준 중위소득 산정: 국가데이터처가 공표하는 통계자료의 가구 경상소득(근로·사업·재산·이전소득 합산)의 중간값에 가구소득 평균 증가율 가구규모별 소득수준 차이를 반영해 가구규모별로 산정","src":"국민기초생활 보장법 제6조의2"},{"t":"소득평가액: 근로소득 사업소득 재산소득 이전소득을 합한 실제소득에서 장애·질병·양육 등 가구 특성 지출요인 근로유인 요인 등을 감한 금액","src":"국민기초생활 보장법 제6조의3제1항"},{"t":"재산의 소득환산액: (재산가액 - 기본재산액 - 부채) x 소득환산율. 재산 범위는 일반재산 금융재산 자동차","src":"국민기초생활 보장법 제6조의3제2항"}]},{"머리":"급여의 종류","줄":[{"t":"급여의 종류 7가지: 생계급여 / 주거급여 / 의료급여 / 교육급여 / 해산급여 / 장제급여 / 자활급여","src":"국민기초생활 보장법 제7조제1항 | 기출 2023-12, 2024-13"},{"t":"수급권자에 대한 급여는 수급자의 필요에 따라 전부 또는 일부를 실시한다","src":"국민기초생활 보장법 제7조제2항"},{"t":"차상위자 급여: 보장기관이 가구별 생활여건을 고려해 예산 범위에서 주거·의료·교육·장제·자활급여(생계급여 제외 해산급여 제외)의 전부 또는 일부를 실시할 수 있다","src":"국민기초생활 보장법 제7조제3항 | 기출 2023-12"},{"t":"생계급여 내용: 의복 음식물 연료비 등 일상생활에 기본적으로 필요한 금품을 지급해 생계를 유지하게 함","src":"국민기초생활 보장법 제8조제1항"},{"t":"생계급여 선정기준: 소득인정액이 중앙생활보장위원회 심의·의결로 정하는 금액 이하(기준 중위소득의 100분의 30 이상)이고 부양의무자가 없거나 부양능력이 없거나 부양을 받을 수 없는 사람 (2023 기출에서 100분의 50은 오답)","src":"국민기초생활 보장법 제8조제2항 | 기출 2023-12"},{"t":"생계급여 최저보장수준은 생계급여와 소득인정액을 포함해 선정기준 이상이 되도록 한다","src":"국민기초생활 보장법 제8조제3항"},{"t":"부양능력 없음으로 보는 경우: 기준 중위소득 수준을 고려해 대통령령으로 정하는 소득·재산 기준 미만 / 직계존속 또는 중증장애인인 직계비속을 자신의 주거에서 부양하는 경우로 고시하는 경우 / 질병 교육 가구 특성 등으로 부양능력이 없다고 보건복지부장관이 정하는 경우","src":"국민기초생활 보장법 제8조의2제1항"},{"t":"부양을 받을 수 없는 것으로 보는 경우: 병역법에 따라 징집·소집된 경우 / 해외이주자 / 교도소·구치소·치료감호시설 등 수용 중 / 실종선고 절차 진행 중 / 보장시설에서 급여를 받고 있는 경우 / 가출·행방불명 신고 후 1개월이 지났거나 시장·군수·구청장이 확인한 경우 / 부양 기피·거부 / 그 밖에 보건복지부장관이 정하는 경우. 아동복지법상 보호조치된 부양 대상 아동도 포함","src":"국민기초생활 보장법 제8조의2제2항·제3항 | 기출 2023-12"},{"t":"생계급여 방법: 금전 지급이 원칙이고 금전으로 지급할 수 없거나 적당하지 않으면 물품 지급 가능(물품 지급 불가 아님). 매월 정기적으로 지급(반기 지급 아님). 수급자에게 직접 지급","src":"국민기초생활 보장법 제9조제1항~제3항 | 기출 2023-12, 2024-13"},{"t":"생계급여는 소득인정액 등을 고려해 차등지급할 수 있다. 근로능력이 있는 수급자에게는 자활사업 참가를 조건으로 실시할 수 있다","src":"국민기초생활 보장법 제9조제4항·제5항"},{"t":"생계급여는 수급자의 주거에서 실시한다. 주거가 없거나 목적 달성이 불가능하거나 수급자가 희망하면 보장시설이나 타인의 가정에 위탁 실시","src":"국민기초생활 보장법 제10조제1항"},{"t":"주거급여: 임차료 수선유지비 그 밖의 수급품을 지급(주택 매입비 아님). 필요한 사항은 따로 법률(주거급여법)에서 정함","src":"국민기초생활 보장법 제11조 | 기출 2023-12, 2024-13"},{"t":"교육급여: 입학금 수업료 학용품비 그 밖의 수급품 지급. 교육부장관 소관. 선정기준은 기준 중위소득의 100분의 50 이상","src":"국민기초생활 보장법 제12조 | 기출 2024-13"},{"t":"의료급여(이 법): 각종 검사 및 치료 등을 지급. 선정기준은 기준 중위소득의 100분의 40 이상. 필요한 사항은 따로 법률(의료급여법)에서 정함","src":"국민기초생활 보장법 제12조의3"},{"t":"해산급여: 생계·주거·의료급여 중 하나 이상을 받는 수급자에게 조산 및 분만 전후 필요한 조치와 보호를 실시","src":"국민기초생활 보장법 제13조 | 기출 2024-13"},{"t":"장제급여: 생계·주거·의료급여 중 하나 이상을 받는 수급자가 사망한 경우 검안 운반 화장 또는 매장 등 장제조치를 실시(자활급여 수급자 사망 아님). 실제 장제를 실시하는 사람에게 비용 지급","src":"국민기초생활 보장법 제14조 | 기출 2024-13"},{"t":"급여의 특례: 수급권자에 해당하지 않아도 생활이 어려워 일정 기간 급여가 필요하다고 보건복지부장관 또는 소관 중앙행정기관의 장이 정하는 사람은 수급권자로 본다","src":"국민기초생활 보장법 제14조의2"},{"t":"자활급여 8가지: 자활에 필요한 금품의 지급 또는 대여 / 근로능력 향상 및 기능습득 지원 / 취업알선 등 정보 제공 / 자활을 위한 근로기회 제공 / 시설 및 장비의 대여 / 창업교육 기능훈련 기술·경영 지도 등 창업지원 / 자산형성 지원 / 그 밖에 대통령령으로 정하는 지원","src":"국민기초생활 보장법 제15조제1항"},{"t":"자활급여는 관련 공공기관·비영리법인·시설 등에 위탁해 실시할 수 있고 비용은 보장기관이 부담","src":"국민기초생활 보장법 제15조제2항 | 기출 2024-13"}]},{"머리":"자활 지원 체계","줄":[{"t":"지역자활센터: 보장기관이 사회복지법인 사회적협동조합 등 비영리법인·단체를 신청받아 지정. 수급자 및 차상위자의 자활 촉진 사업 수행","src":"국민기초생활 보장법 제16조제1항"},{"t":"지역자활센터 사업: 자활의욕 고취 교육 / 자활을 위한 정보제공 상담 직업교육 취업알선 / 생업을 위한 자금융자 알선 / 자영창업 지원 및 기술·경영 지도 / 자활기업의 설립·운영 지원 / 그 밖에 자활을 위한 사업. 사업자금 융자는 센터 사업이 아니라 자활기업 지원(제18조)","src":"국민기초생활 보장법 제16조제1항 | 기출 2024-14"},{"t":"센터 지원: 설립·운영 비용 또는 사업수행 비용의 전부 또는 일부 / 국유·공유 재산 무상임대 / 보장기관 사업의 우선 위탁. 정기 평가 후 자활촉진을 달성하지 못하면 지정 취소 가능. 지역자활센터협회를 설립할 수 있다","src":"국민기초생활 보장법 제16조제2항~제4항"},{"t":"자활기관협의체: 시장·군수·구청장이 지역자활센터 직업안정기관 사회복지시설의 장 등과 상시 협의체계를 구축하여야 한다","src":"국민기초생활 보장법 제17조"},{"t":"자활기업 설립·운영: 수급자 및 차상위자가 상호 협력하여 설립. 요건은 조합 또는 부가가치세법상 사업자 형태 / 수급자 또는 차상위자를 2인 이상 포함 / 보건복지부장관이 정하는 운영기준. 보장기관의 인정을 받아야 함","src":"국민기초생활 보장법 제18조제1항·제2항"},{"t":"자활기업 지원: 자활을 위한 사업자금 융자 / 국유지·공유지 우선 임대 / 국가·지방자치단체 사업 우선 위탁 / 경영·세무 교육 및 컨설팅 / 그 밖의 사업","src":"국민기초생활 보장법 제18조제3항"},{"t":"자활지원계획: 시장·군수·구청장이 조사 결과를 고려해 수급자 가구별로 수립하고 그에 따라 급여를 실시. 자활여건 변화와 급여 실시 결과를 정기적으로 평가해 변경 가능","src":"국민기초생활 보장법 제28조"},{"t":"자활지원사업 통합정보전산망 사용 시 수행기관은 보건복지부장관에게 사용을 요청하고 개인정보 보호대책(보안교육 등)을 마련하여야 한다. 정보주체의 사전 동의를 받아야 한다. 수급이력 등 개인정보는 기관의 장의 취급승인을 받은 담당자만 취급. 업무 종사자였던 사람도 알게 된 정보를 다른 용도로 사용 금지","src":"국민기초생활 보장법 제18조의10·제18조의11 | 기출 2025-19 | 보충(조문 원문 미확인)"}]},{"머리":"보장기관·위원회·계획","줄":[{"t":"보장기관(급여 실시 주체): 수급권자 또는 수급자의 거주지를 관할하는 시·도지사와 시장·군수·구청장. 교육급여는 시·도교육감. 주거가 일정하지 않으면 실제 거주 지역 관할 시장·군수·구청장","src":"국민기초생활 보장법 제19조제1항 | 기출 2022-12, 2023-17"},{"t":"보장기관은 조사·결정·실시 업무를 위해 사회복지 전담공무원을 배치하여야 하고 자활급여 업무 담당자는 따로 배치","src":"국민기초생활 보장법 제19조제4항"},{"t":"생활보장위원회: 생활보장사업의 기획·조사·실시 등을 심의·의결하기 위해 보건복지부와 시·도 및 시·군·구에 각각 둔다(심의·의결기구, 자문기구 아님)","src":"국민기초생활 보장법 제20조제1항 | 기출 2023-8, 2023-17"},{"t":"중앙생활보장위원회 심의·의결 사항: 기초생활보장 종합계획 수립 / 소득인정액 산정방식과 기준 중위소득 결정 / 급여 종류별 수급자 선정기준과 최저보장수준 결정 / 급여기준 적정성 평가 및 실태조사 / 급여 누락·중복 및 차상위계층 지원사업 조정 / 자활기금 적립·관리·사용 지침 / 위원장이 회의에 부치는 사항","src":"국민기초생활 보장법 제20조제2항"},{"t":"중앙생활보장위원회는 위원장 포함 16명 이내로 구성하고 위원장은 보건복지부장관. 위원은 공공부조·사회복지 전문가(조교수 이상 또는 연구원) 5명 이내 + 공익대표 5명 이내 + 관계 행정기관 3급 이상 공무원 등 5명 이내","src":"국민기초생활 보장법 제20조제3항"},{"t":"시·도 및 시·군·구 생활보장위원회 위원장은 시·도지사 또는 시장·군수·구청장","src":"국민기초생활 보장법 제20조제4항"},{"t":"기초생활보장 계획: 소관 중앙행정기관의 장이 3년마다 기초생활보장 기본계획을 수립해 보건복지부장관에게 제출하고, 보건복지부장관이 이를 종합해 종합계획을 수립해 중앙생활보장위원회 심의를 받는다. 실태조사는 3년마다 실시·공표 (5년마다 시행계획은 오답)","src":"국민기초생활 보장법 제20조의2 | 기출 2023-17"}]},{"머리":"급여 신청·조사·결정","줄":[{"t":"신청: 수급권자와 그 친족 그 밖의 관계인이 관할 시장·군수·구청장에게 신청. 사회복지 전담공무원은 수급권자 동의를 구해 직권 신청 가능","src":"국민기초생활 보장법 제21조제1항·제2항"},{"t":"신청 시 수급권자와 부양의무자는 금융정보·신용정보·보험정보 제공에 동의한다는 서면을 제출","src":"국민기초생활 보장법 제21조제3항"},{"t":"시장·군수·구청장은 신청자에게 급여 신청의 철회나 포기를 유도하는 행위를 하여서는 아니 된다","src":"국민기초생활 보장법 제21조제5항"},{"t":"신청에 의한 조사 사항: 부양의무자 유무·부양능력 / 수급권자·부양의무자의 소득·재산 / 근로능력 취업상태 자활욕구 / 건강상태 가구 특성 등 생활실태","src":"국민기초생활 보장법 제22조제1항"},{"t":"조사·자료제출 요구를 2회 이상 거부·방해·기피하면 급여신청을 각하할 수 있다","src":"국민기초생활 보장법 제22조제8항"},{"t":"확인조사: 시장·군수·구청장이 매년 연간조사계획을 세워 관할 수급자를 매년 1회 이상 정기 조사. 보건복지부장관이 정하는 사항은 분기마다 조사. 거부 시 급여 결정 취소 또는 정지·중지 가능","src":"국민기초생활 보장법 제23조"},{"t":"급여 결정: 조사 후 지체 없이 급여 실시 여부와 내용을 결정. 신청일부터 30일 이내 서면 통지. 부양의무자 조사에 시일이 걸리는 특별 사유나 조사 거부 시 60일 이내 통지 가능","src":"국민기초생활 보장법 제26조"},{"t":"급여는 신청일부터 시작한다(매년 1월 새로 수급자가 되는 사람은 그 해 1월 1일). 긴급한 필요가 있으면 결정 전이라도 급여의 일부를 실시할 수 있다","src":"국민기초생활 보장법 제27조"},{"t":"급여는 수급자 신청에 따라 수급자 명의의 급여수급계좌로 입금","src":"국민기초생활 보장법 제27조의2"},{"t":"급여 변경: 소득·재산·근로능력 등이 변동되면 직권 또는 신청으로 종류·방법을 변경할 수 있다. 서면으로 이유를 밝혀 통지","src":"국민기초생활 보장법 제29조"},{"t":"급여 중지: 급여가 필요 없게 된 경우 또는 수급자가 거부한 경우 전부 또는 일부를 중지하여야 한다","src":"국민기초생활 보장법 제30조제1항"}]},{"머리":"보장시설·권리보호·이의신청","줄":[{"t":"보장시설: ① 장애인복지법 장애인 거주시설 ② 노인복지법 노인주거복지시설·노인의료복지시설 ③ 아동복지시설 및 통합시설 ④ 정신요양시설·정신재활시설 ⑤ 노숙인재활시설·노숙인요양시설 ⑥ 가정폭력피해자 보호시설 ⑦ 성매매피해자등 지원시설 ⑧ 성폭력피해자보호시설 ⑨ 한부모가족복지시설 ⑩ 결핵 및 한센병요양시설 ⑪ 그 밖에 보건복지부령으로 정하는 시설","src":"국민기초생활 보장법 제32조 | 기출 2022-12"},{"t":"보장시설의 장의 의무: 위탁을 정당한 사유 없이 거부 금지 / 최저기준 이상의 급여 / 성별·신앙·사회적 신분 등 차별 금지 / 자유로운 생활 보장 / 종교상의 행위 강제 금지","src":"국민기초생활 보장법 제33조"},{"t":"수급품과 받을 권리는 압류할 수 없고 급여수급계좌 예금 채권도 압류 불가. 급여를 받을 권리는 양도할 수 없다","src":"국민기초생활 보장법 제35조 제36조"},{"t":"수급자는 거주지역 세대구성 임대차 계약내용 등이 변동되면 지체 없이 관할 보장기관에 신고","src":"국민기초생활 보장법 제37조"},{"t":"이의신청 1단계: 시장·군수·구청장(교육급여는 시·도교육감)의 처분에 이의가 있으면 결정 통지를 받은 날부터 90일 이내에 해당 보장기관을 거쳐 시·도지사에게 서면 또는 구두로 신청. 시장·군수·구청장은 10일 이내 의견서와 관계 서류를 시·도지사에게 송부","src":"국민기초생활 보장법 제38조"},{"t":"시·도지사는 30일 이내에 심사해 각하·기각하거나 처분을 변경·취소하거나 필요한 급여를 명하고 신청인과 시장·군수·구청장에게 서면 통지","src":"국민기초생활 보장법 제39조"},{"t":"이의신청 2단계: 시·도지사 처분에 이의가 있으면 통지를 받은 날부터 90일 이내에 시·도지사를 거쳐 보건복지부장관(주거·교육급여는 소관 중앙행정기관의 장)에게 신청. 시·도지사는 10일 이내 송부, 보건복지부장관 등은 30일 이내 심사·결정하고 통지","src":"국민기초생활 보장법 제40조 제41조"}]},{"머리":"보장비용·징수·벌칙","줄":[{"t":"보장비용: 보장업무 인건비·사무비 / 생활보장위원회 운영비 / 급여 실시 비용 / 그 밖의 비용","src":"국민기초생활 보장법 제42조"},{"t":"비용 부담: 국가 또는 시·도가 직접 수행하는 업무 비용은 국가 또는 해당 시·도 부담. 시·군·구 보장비용 중 급여 실시 비용 등은 국가가 100분의 40 이상 100분의 90 이하를 부담하고 시·도는 나머지 중 100분의 30 이상 100분의 70 이하를 부담하며 나머지는 시·군·구가 부담","src":"국민기초생활 보장법 제43조제1항"},{"t":"유류금품: 장제급여 시 사망자에게 부양의무자가 없으면 시장·군수·구청장이 유류 금전·유가증권으로 비용에 충당하고 부족액은 유류물품 매각대금으로 충당할 수 있다","src":"국민기초생활 보장법 제45조"},{"t":"비용 징수: 부양능력 있는 부양의무자가 있으면 생활보장위원회 심의·의결을 거쳐 비용의 전부 또는 일부를 징수할 수 있다. 부정수급자로부터도 징수할 수 있다","src":"국민기초생활 보장법 제46조"},{"t":"반환명령: 급여 변경·정지·중지로 과잉지급분이 생기면 즉시 반환을 명하여야 한다. 이미 소비했거나 부득이한 사유가 있으면 면제할 수 있다","src":"국민기초생활 보장법 제47조제1항"},{"t":"벌칙(현행): 금융정보등 사용·제공·누설은 5년 이하 징역 또는 5천만원 이하 벌금 / 조사로 얻은 정보·자료 목적 외 사용·제공은 3년 이하 징역 또는 3천만원 이하 벌금 / 거짓·부정한 방법으로 급여를 받거나 받게 한 자와 급여 목적 외 사용은 1년 이하 징역 1천만원 이하 벌금 구류 또는 과료 / 직무상 비밀 누설은 1년 이하 징역 또는 1천만원 이하 벌금 / 보장시설 위탁 거부·종교행위 강제는 300만원 이하 벌금 구류 또는 과료 (2021 기출 당시 부정수급 5년 이하 5천만원이 정답 선지였음)","src":"국민기초생활 보장법 제48조~제50조 | 기출 2021-13"}]},{"머리":"의료급여법 총칙·수급권자","줄":[{"t":"의료급여법 목적: 생활이 어려운 사람에게 의료급여를 함으로써 국민보건의 향상과 사회복지의 증진에 이바지","src":"의료급여법 제1조"},{"t":"수급권자: 이 법에 따라 의료급여를 받을 수 있는 자격을 가진 사람","src":"의료급여법 제2조제1호"},{"t":"의료급여기관: 수급권자에 대한 진료·조제 또는 투약 등을 담당하는 의료기관 및 약국 등","src":"의료급여법 제2조제2호 | 기출 2026-14"},{"t":"부양의무자: 수급권자의 1촌 직계혈족 및 그 배우자","src":"의료급여법 제2조제3호"},{"t":"수급권자 10가지: ① 기초생활보장법상 의료급여 수급자 ② 재해구호법상 이재민으로 보건복지부장관이 필요하다고 인정한 사람 ③ 의사상자 등 예우 및 지원에 관한 법률에 따라 의료급여를 받는 사람 ④ 국내입양에 관한 특별법에 따라 입양된 18세 미만 아동 ⑤ 독립유공자·국가유공자·보훈보상대상자와 그 가족으로 국가보훈부장관이 추천해 보건복지부장관이 인정한 사람 ⑥ 국가무형유산 보유자(명예보유자 포함)와 그 가족으로 국가유산청장이 추천해 보건복지부장관이 인정한 사람 ⑦ 북한이탈주민과 그 가족으로 보건복지부장관이 인정한 사람 ⑧ 5·18민주화운동 관련 보상금등을 받은 사람과 그 가족으로 보건복지부장관이 인정한 사람 ⑨ 노숙인 등으로 보건복지부장관이 인정한 사람 ⑩ 그 밖에 대통령령으로 정하는 사람","src":"의료급여법 제3조제1항 | 기출 2025-21, 2026-14"},{"t":"난민 특례: 난민법에 따른 난민인정자로 기초생활보장법상 의료급여 수급권자 범위에 해당하는 사람은 수급권자로 본다","src":"의료급여법 제3조의2 | 기출 2022-23"},{"t":"적용 배제: 업무 또는 공무로 생긴 질병·부상·재해로 다른 법령에 따른 급여나 보상을 받게 되면 의료급여를 하지 아니한다. 다른 법령으로 의료급여에 상당하는 급여를 받으면 그 한도에서 하지 않는다","src":"의료급여법 제4조 | 기출 2025-21"},{"t":"보장기관: 수급권자의 거주지를 관할하는 시·도지사(특별시장·광역시장·도지사)와 시장·군수·구청장. 주거가 일정하지 않으면 실제 거주지 관할 시장·군수·구청장(출생지 아님)","src":"의료급여법 제5조 | 기출 2025-21"},{"t":"의료급여심의위원회: 보건복지부 시·도 시·군·구에 각각 둔다. 중앙위원회 심의 사항은 의료급여사업의 기본방향 및 대책 / 의료급여의 기준 및 수가 / 그 밖에 보건복지부장관 또는 위원장이 부의하는 사항. 위원장 포함 15명 이내이고 위원장은 보건복지부차관","src":"의료급여법 제6조 | 기출 2024-15"}]},{"머리":"의료급여 내용·기관·비용","줄":[{"t":"의료급여의 내용 7가지: 진찰·검사 / 약제·치료재료의 지급 / 처치·수술과 그 밖의 치료 / 예방·재활 / 입원 / 간호 / 이송과 그 밖의 의료목적 달성을 위한 조치 (장제조치는 포함되지 않음)","src":"의료급여법 제7조제1항 | 기출 2022-13"},{"t":"의료급여의 기준은 보건복지부령 수가기준은 보건복지부장관이 정한다. 업무·일상생활에 지장 없는 질환 등은 대상에서 제외할 수 있다","src":"의료급여법 제7조제2항·제3항"},{"t":"의료급여증: 시장·군수·구청장이 수급권자 신청 시 발급하여야 한다(시·도지사 아님). 부득이한 경우 의료급여증명서로 갈음. 신분증명서로 자격 확인이 되면 증 제출 생략 가능. 증의 양도·대여 금지","src":"의료급여법 제8조 | 기출 2024-15"},{"t":"의료급여기관: 의료법에 따른 의료기관 / 보건소·보건의료원·보건지소 / 보건진료소 / 약국 및 한국희귀·필수의약품센터. 보건소도 의료급여기관이 될 수 있다","src":"의료급여법 제9조제1항 | 기출 2025-21"},{"t":"의료급여기관 구분: 제1차(개설신고 의료기관 + 보건소 등 + 약국) / 제2차(개설허가 의료기관) / 제3차(제2차 중 보건복지부장관이 지정). 정당한 이유 없이 의료급여를 거부하지 못한다","src":"의료급여법 제9조제2항·제3항"},{"t":"급여비용은 대통령령에 따라 전부 또는 일부를 의료급여기금에서 부담하고 일부 부담 시 나머지는 본인이 부담","src":"의료급여법 제10조"},{"t":"급여비용 청구: 의료급여기관이 급여비용심사기관에 심사청구 → 심사기관이 심사 후 시장·군수·구청장과 의료급여기관에 통보 → 시장·군수·구청장이 지급. 평가결과에 따라 가산 또는 감액 조정","src":"의료급여법 제11조"},{"t":"요양비: 긴급하거나 부득이한 사유로 의료급여기관이 아닌 곳에서 의료급여를 받거나 의료급여기관이 아닌 장소에서 출산한 경우 시장·군수·구청장이 수급권자에게 요양비로 지급","src":"의료급여법 제12조"},{"t":"장애인 및 임산부 특례: 등록장애인 수급권자에게 보조기기 급여 실시 가능. 임신한 수급권자의 진료비(출산비용 포함)에 추가급여 가능","src":"의료급여법 제13조"},{"t":"건강검진: 시장·군수·구청장이 수급권자에 대해 질병의 조기발견과 그에 따른 의료급여를 위해 할 수 있다","src":"의료급여법 제14조 | 기출 2026-14"}]},{"머리":"제한·변경·중지·권리보호","줄":[{"t":"의료급여 제한: 시장·군수·구청장은 ① 고의 또는 중대한 과실로 인한 범죄행위에 원인이 있거나 고의로 사고를 일으킨 경우 ② 정당한 이유 없이 법이나 진료 지시에 따르지 않은 경우 의료급여를 하지 아니한다. 보건복지부장관이 필요하다고 인정하면 예외","src":"의료급여법 제15조 | 기출 2025-21"},{"t":"변경: 소득·재산상황·근로능력 등이 변동되면 직권 또는 신청으로 변경하고 서면으로 이유를 알림","src":"의료급여법 제16조"},{"t":"중지: 시장·군수·구청장은 의료급여가 필요 없게 된 경우 또는 수급권자가 의료급여를 거부한 경우 의료급여를 중지하여야 한다. 거부한 경우에는 가구원 전부에 대해 중지","src":"의료급여법 제17조 | 기출 2024-15, 2026-14"},{"t":"수급권 보호: 의료급여를 받을 권리는 양도하거나 압류할 수 없다","src":"의료급여법 제18조"},{"t":"구상권: 제3자의 행위로 의료급여를 한 경우 시장·군수·구청장은 급여비용 범위에서 제3자에게 손해배상 청구권을 얻는다","src":"의료급여법 제19조"},{"t":"대지급: 급여비용의 일부를 기금에서 부담하는 경우 나머지 비용(보건복지부장관이 정한 금액)은 수급권자 또는 부양의무자의 신청으로 기금에서 대지급할 수 있다. 상환은 무이자로 거주지 관할 시장·군수·구청장에게 하고 상환받은 금액은 의료급여기금에 납입한다(시·도지사 아님)","src":"의료급여법 제20조~제22조 | 기출 2024-15"},{"t":"대지급금 독촉: 납부기한이 지난 날부터 6개월 이내 기간을 정해 독촉장 발급 → 지방세 체납처분의 예에 따라 징수","src":"의료급여법 제22조"},{"t":"부당이득 징수: 속임수 등 부당한 방법으로 급여를 받은 사람 / 의료급여기관 등. 독촉 시 10일 이상 15일 이내 납부기한","src":"의료급여법 제23조"},{"t":"의료급여기금: 시·도에 설치한다(보건복지부에 설치하는 것이 아님). 재원은 국고보조금 / 지방자치단체 출연금 / 상환받은 대지급금 / 부당이득금 / 과징금 / 결산상 잉여금 및 그 밖의 수입금. 일반회계와 구분해 별도 계정으로 관리","src":"의료급여법 제25조·제26조 | 기출 2024-15"},{"t":"업무정지: 보건복지부장관이 의료급여기관에 1년의 범위에서 업무정지 명령(속임수 급여비용 부담 / 본인부담금 미리 청구 및 다른 명목 비용 청구 / 보고·서류제출 거부 등). 제3차 의료급여기관은 지정 취소 가능하고 취소일부터 1년 내 재지정 불가","src":"의료급여법 제28조"},{"t":"과징금: 업무정지가 수급권자에게 심한 불편을 주면 갈음하여 속임수로 부담하게 한 급여비용의 5배 이하 금액을 부과. 12개월 범위에서 분할 납부 가능","src":"의료급여법 제29조"},{"t":"이의신청: 시장·군수·구청장에게 처분이 있음을 안 날부터 90일 이내 문서로 하고 처분이 있은 날부터 180일이 지나면 제기 불가","src":"의료급여법 제30조"},{"t":"소멸시효 3년: 의료급여를 받을 권리 / 급여비용을 받을 권리 / 대지급금을 상환받을 권리. 급여비용 청구와 대지급금 납입 고지·독촉으로 중단","src":"의료급여법 제31조"},{"t":"권한 위탁: 시장·군수·구청장 업무 중 수급권자 관리 급여비용 심사·조정 적정성 평가 급여 대상 확인 급여비용 지급을 관계 전문기관에 위탁할 수 있다","src":"의료급여법 제33조"}]},{"머리":"긴급복지지원법","줄":[{"t":"긴급복지지원법 목적: 생계곤란 등 위기상황에 처한 사람을 신속하게 지원해 위기상황에서 벗어나 건강하고 인간다운 생활을 하게 함","src":"긴급복지지원법 제1조"},{"t":"위기상황 사유 9가지: ① 주소득자가 사망 가출 행방불명 구금시설 수용 등으로 소득 상실 ② 중한 질병 또는 부상 ③ 가구구성원으로부터 방임 또는 유기되거나 학대 등을 당함 ④ 가정폭력으로 원만한 가정생활이 곤란하거나 가구구성원으로부터 성폭력을 당함 ⑤ 화재 또는 자연재해 등으로 주택 또는 건물에서 생활 곤란 ⑥ 주소득자 또는 부소득자의 휴업 폐업 또는 사업장 화재 등으로 영업 곤란 ⑦ 주소득자 또는 부소득자의 실직으로 소득 상실 ⑧ 보건복지부령 기준에 따라 지방자치단체 조례로 정한 사유 ⑨ 그 밖에 보건복지부장관이 정하여 고시하는 사유","src":"긴급복지지원법 제2조 | 기출 2023-14, 2026-13"},{"t":"기본원칙: 위기상황에 처한 사람에게 일시적으로 신속하게 지원. 다른 법률(재해구호법 기초생활보장법 의료급여법 사회복지사업법 가정폭력방지법 성폭력방지법 등)로 동일 내용 지원을 받고 있으면 이 법에 따른 지원을 하지 않는다","src":"긴급복지지원법 제3조"},{"t":"국가 및 지방자치단체의 책무: 위기상황에 처한 사람을 찾아내 신속 지원 노력 / 지원 후에도 위기상황이 해소되지 않으면 다른 법률에 따른 구호·보호·지원을 받도록 노력 / 어려우면 민간기관·단체와 연계","src":"긴급복지지원법 제4조"},{"t":"외국인 특례: 국내 체류 외국인 중 대통령령으로 정하는 사람이 긴급지원대상자가 될 수 있다","src":"긴급복지지원법 제5조의2"},{"t":"긴급지원기관: 긴급지원대상자의 거주지를 관할하는 시장·군수·구청장. 거주지가 분명하지 않으면 지원요청·신고를 받은 시장·군수·구청장. 긴급지원담당공무원을 지정","src":"긴급복지지원법 제6조"},{"t":"지원요청: 긴급지원대상자와 친족 그 밖의 관계인이 구술 또는 서면으로 요청. 누구든지 대상자를 발견하면 신고하여야 한다","src":"긴급복지지원법 제7조제1항·제2항"},{"t":"직무상 신고 노력 의무자 10종 + 보건복지부령 지정자: 의료기관 종사자 / 유아교육법·초중등교육법·고등교육법에 따른 교원·직원·산학겸임교사·강사 / 사회복지시설 종사자 / 국가공무원·지방공무원 / 장애인활동지원기관의 장 및 종사자와 활동지원인력 / 학원 운영자·강사·직원 및 교습소 교습자·직원 / 건강가정지원센터·가족센터의 장과 종사자 / 청소년시설·청소년단체의 장과 종사자 / 청소년 보호·재활센터의 장과 종사자 / 평생교육기관의 장과 종사자 / 그 밖에 보건복지부령으로 정하는 자 (국가무형유산 보유자는 해당하지 않음)","src":"긴급복지지원법 제7조제3항 | 기출 2022-15"},{"t":"위기상황 발굴: 국가 및 지방자치단체가 발굴조사를 연 1회 이상 정기적으로 실시. 발굴체계 운영 실태를 정기적으로 점검하고 개선방안을 수립","src":"긴급복지지원법 제7조의2"},{"t":"현장 확인: 지원요청·신고를 받으면 지체 없이 긴급지원담당공무원이 거주지 등을 방문해 위기상황 확인. 확인되면 지체 없이 지원의 종류·내용을 결정해 지원. 우선 필요한 지원을 하게 할 수 있다","src":"긴급복지지원법 제8조"},{"t":"금융정보 등 제공동의서: 지원 요청 시 또는 위기상황 확인 시 긴급지원대상자와 가구구성원이 금융·신용·보험 정보 제공 동의 서면을 제출(의식불명 등은 지원 후 제출)","src":"긴급복지지원법 제8조의2"}]},{"머리":"긴급지원의 종류·기간·심의","줄":[{"t":"직접지원 6가지: 생계지원(식료품비·의복비 등) / 의료지원(각종 검사 및 치료) / 주거지원(임시거소 제공 또는 비용) / 사회복지시설 이용 지원 / 교육지원(초·중·고등학생의 수업료 입학금 학교운영지원비 학용품비) / 그 밖의 지원(연료비 등)","src":"긴급복지지원법 제9조제1항제1호"},{"t":"민간기관·단체와의 연계 지원: 대한적십자사 사회복지공동모금회 등과의 연계 지원 / 상담·정보제공 그 밖의 지원","src":"긴급복지지원법 제9조제1항제2호"},{"t":"생계지원과 주거지원은 각각 기준 중위소득의 100분의 40을 한도로 한다","src":"긴급복지지원법 제9조제2항"},{"t":"지원 기간: 생계지원 3개월. 주거지원·사회복지시설 이용 지원·그 밖의 지원 1개월. 이 중 주거·시설·그 밖의 지원은 위기상황이 계속되면 1개월씩 두 번 연장 가능. 의료지원과 교육지원은 각각 한 번 실시","src":"긴급복지지원법 제10조제1항·제2항"},{"t":"심의로 연장 시 한도: 생계·시설·그 밖의 지원은 총 6개월 초과 불가 / 주거지원은 총 12개월 초과 불가 / 의료지원은 총 2번 / 교육지원은 총 4번","src":"긴급복지지원법 제10조제3항"},{"t":"담당기구: 보건복지부장관이 상담·정보제공·연계서비스를 위한 담당기구를 설치·운영할 수 있다","src":"긴급복지지원법 제11조"},{"t":"긴급지원심의위원회: 시·군·구에 둔다. 심의 사항은 지원연장 결정 / 긴급지원의 적정성 심사 / 중단 또는 비용환수 결정 / 위원장이 부의하는 사항. 위원장 1명 포함 15명 이내이고 위원장은 시장·군수·구청장. 사회보장 학식경험자와 비영리민간단체 추천자가 2분의 1 이상","src":"긴급복지지원법 제12조"},{"t":"사후조사: 시장·군수·구청장이 지원받은 대상자의 소득·재산 등을 조사해 지원이 적정한지 확인. 적정성 심사 후 부정한 방법이면 지체 없이 지원 중단 및 비용 환수(필요적). 적정하지 않으면 중단·환수 가능(임의적)","src":"긴급복지지원법 제13조~제15조"},{"t":"이의신청: 처분을 고지받은 날부터 30일 이내에 시장·군수·구청장을 거쳐 시·도지사에게 서면. 시장·군수·구청장은 10일 이내 송부 시·도지사는 15일 이내 검토","src":"긴급복지지원법 제16조"},{"t":"압류 등 금지: 지급되는 금전·현물과 긴급지원수급계좌의 긴급지원금은 압류할 수 없고 생계유지 목적 외로 양도·담보 제공할 수 없다","src":"긴급복지지원법 제18조"},{"t":"벌칙: 사후조사로 얻은 정보·자료를 목적 외 사용·제공하면 3년 이하 징역 또는 3천만원 이하 벌금","src":"긴급복지지원법 제19조"}]},{"머리":"기초연금법","줄":[{"t":"기초연금법 목적: 노인에게 기초연금을 지급해 안정적인 소득기반을 제공함으로써 노인의 생활안정을 지원하고 복지를 증진","src":"기초연금법 제1조"},{"t":"소득인정액: 본인 및 배우자의 소득평가액과 재산의 소득환산액을 합산한 금액","src":"기초연금법 제2조제4호"},{"t":"수급권자: 65세 이상으로 소득인정액이 보건복지부장관이 고시하는 선정기준액 이하인 사람. 선정기준액은 65세 이상 중 기초연금 수급자가 100분의 70 수준이 되도록 정한다","src":"기초연금법 제3조제1항·제2항 | 기출 2021-15, 2026-15"},{"t":"지급 제외: 공무원연금·군인연금·사학연금·별정우체국연금의 퇴직연금 등 수급권자와 그 배우자(대통령령으로 정하는 사람 포함) 및 직역재직기간 10년 이상인 연계퇴직연금 수급자","src":"기초연금법 제3조제3항"},{"t":"국가와 지방자치단체의 책무: 기초연금이 필요한 수준이 되도록 최대한 노력 / 재원 조성(국민연금기금은 기초연금 지급 재원으로 사용 불가) / 계층 간 소득역전 현상과 근로의욕·저축유인 저하 방지 노력","src":"기초연금법 제4조 | 기출 2026-15"},{"t":"기준연금액: 보건복지부장관이 전년도 기준연금액에 전국소비자물가변동률을 반영해 매년 고시. 적용기간은 해당 연도 1월부터 12월까지. 2021년 기준연금액은 30만원","src":"기초연금법 제5조제2항·제3항"},{"t":"국민연금 수급권자의 기초연금액: (기준연금액 - 소득재분배급여금액 x 2/3) + 부가연금액(기준연금액의 2분의 1). 뺀 금액이 0보다 작으면 0","src":"기초연금법 제5조제5항"},{"t":"기준연금액을 지급하는 사람: 국민연금 등 해당 없는 사람 / 지급 정지된 노령연금·분할연금 수급권자 / 장애인연금 수급권자 / 기초생활보장 수급권자로 대통령령이 정하는 사람 등. 국민연금 급여액이 기준연금액의 100분의 150 이하인 사람에게도 기준연금액","src":"기초연금법 제5조제7항 제6조제1항"},{"t":"기초연금액이 기준연금액을 초과하면 기준연금액으로 본다","src":"기초연금법 제7조"},{"t":"감액: 본인과 배우자가 모두 수급권자이면 각각의 기초연금액에서 100분의 20을 감액. 소득인정액 + 기초연금액이 선정기준액 이상이면 초과 금액 범위에서 일부 감액 가능","src":"기초연금법 제8조 | 기출 2024-16, 2026-15"},{"t":"적정성 평가: 보건복지부장관이 5년마다 기초연금 수급권자의 생활수준 소득재분배급여 변동률 물가변동률 등을 종합 고려해 평가하고 기준연금액을 조정. 노인 빈곤 실태조사와 재정 소요 전망을 함께 실시","src":"기초연금법 제9조"},{"t":"신청: 수급희망자 또는 대리인이 특별자치시장·특별자치도지사·시장·군수·구청장에게 신청. 수급희망자와 배우자는 금융·신용·보험 정보 제공 동의 서면 제출","src":"기초연금법 제10조"},{"t":"지급: 신청한 날이 속하는 달부터 수급권을 상실한 날이 속하는 달까지 매월 정기적으로 지급. 지급 정지 기간에는 지급하지 않음","src":"기초연금법 제14조"},{"t":"미지급 기초연금: 수급자 사망 시 생계를 같이한 부양의무자(배우자와 직계혈족 및 그 배우자)가 청구","src":"기초연금법 제15조"},{"t":"지급 정지(사유 발생일이 속하는 달의 다음 달부터 소멸일이 속하는 달까지): ① 금고 이상의 형을 선고받고 교정시설 또는 치료감호시설에 수용 ② 행방불명·실종 등으로 사망한 것으로 추정 ③ 국외 체류기간이 60일 이상 지속(60일이 되는 날 사유 발생) ④ 그 밖에 이에 준하는 대통령령 사유","src":"기초연금법 제16조 | 기출 2022-14, 2024-16, 2026-15"},{"t":"수급권 상실: 사망한 때 / 국적을 상실하거나 국외로 이주한 때 / 선정 요건에 해당하지 않게 된 때 (장기요양등급판정은 상실 사유 아님. 사망 추정은 지급 정지 사유)","src":"기초연금법 제17조 | 기출 2025-20, 2024-16"},{"t":"신고: 지급 정지 사유 소멸 / 수급권 상실 사유 / 소득·재산 변동 / 결혼·이혼·배우자 사망 / 그 밖의 사유를 30일 이내에 신고","src":"기초연금법 제18조"},{"t":"환수: 거짓 부정한 방법으로 받은 경우(이자 가산) / 지급 정지 기간에 지급된 경우 / 잘못 지급된 경우 환수하여야 한다","src":"기초연금법 제19조"},{"t":"수급권 보호: 양도하거나 담보로 제공할 수 없고 압류 대상으로 할 수 없다. 기초연금으로 지급받은 금품은 압류할 수 없다","src":"기초연금법 제21조 | 기출 2026-15"},{"t":"이의신청: 처분이 있음을 안 날부터 90일 이내 서면. 정당한 사유가 있으면 사유 소멸 후 60일 이내","src":"기초연금법 제22조"},{"t":"시효: 환수금을 환수할 권리와 기초연금 수급권자의 권리는 5년간 행사하지 않으면 소멸 (3년 아님)","src":"기초연금법 제23조 | 기출 2024-16"},{"t":"비용 분담: 국가가 100분의 40 이상 100분의 90 이하 범위에서 대통령령으로 정하는 비율을 부담하고 나머지는 시·도와 시·군·구가 분담","src":"기초연금법 제25조"},{"t":"업무 위탁: 신청 접수 / 조사·질문 지원 / 기초연금 지급 / 미지급 청구 접수 / 신고 접수 / 환수금 고지·독촉·징수 / 이의신청 접수 / 정보시스템 운영을 국민연금공단에 위탁할 수 있다","src":"기초연금법 제28조제2항"}]}],"함정":[{"x":"부양의무자가 「병역법」에 따라 징집되거나 소집된 경우 부양능력이 있는 것으로 본다.","o":"부양을 받을 수 없는 것으로 본다.","src":"국민기초생활 보장법 제8조의2제2항제1호 | 기출 2023-12"},{"x":"생계급여 선정기준은 기준 중위소득의 100분의 50 이상으로 한다.","o":"현행 생계급여는 100분의 30 이상(교육급여가 100분의 50 이상 의료급여가 100분의 40 이상).","src":"국민기초생활 보장법 제8조제2항 제12조 제12조의3 | 기출 2023-12"},{"x":"생계급여는 상반기ㆍ하반기로 나누어 지급하여야 한다.","o":"매월 정기적으로 지급한다.","src":"국민기초생활 보장법 제9조제2항 | 기출 2023-12"},{"x":"주거급여는 주택 매입비, 수선유지비 등이 포함된다.","o":"주거급여는 임차료 수선유지비 그 밖의 수급품. 주택 매입비는 없다.","src":"국민기초생활 보장법 제11조제1항 | 기출 2023-12"},{"x":"생계급여는 물품으로는 지급할 수 없다.","o":"금전으로 지급할 수 없거나 적당하지 않으면 물품 지급 가능.","src":"국민기초생활 보장법 제9조제1항 | 기출 2024-13"},{"x":"생계급여는 수급자에게 주거 안정에 필요한 임차료, 수선유지비, 그 밖의 수급품을 지급하는 것으로 한다.","o":"그것은 주거급여의 내용이다. 생계급여는 의복 음식물 연료비 등.","src":"국민기초생활 보장법 제8조제1항 제11조 | 기출 2024-13"},{"x":"장제급여는 자활급여를 받는 수급자가 사망한 경우 장제조치를 하는 것으로 한다.","o":"생계·주거·의료급여 중 하나 이상을 받는 수급자가 사망한 경우.","src":"국민기초생활 보장법 제14조제1항 | 기출 2024-13"},{"x":"교육급여는 보건복지부장관의 소관으로 한다.","o":"교육부장관의 소관이다.","src":"국민기초생활 보장법 제12조제2항 | 기출 2024-13"},{"x":"교육급여 및 의료급여는 시ㆍ도교육감이 실시한다.","o":"교육급여만 시·도교육감이 실시. 의료급여는 시·도지사와 시장·군수·구청장.","src":"국민기초생활 보장법 제19조제1항 | 기출 2023-17"},{"x":"보장기관은 위기개입상담원을 배치하여야 한다.","o":"이 법의 필요 배치 대상은 사회복지 전담공무원(자활급여 담당자는 따로 배치).","src":"국민기초생활 보장법 제19조제4항 | 기출 2023-17"},{"x":"생활보장위원회는 자문기구이다.","o":"심의·의결기구이다.","src":"국민기초생활 보장법 제20조제1항 | 기출 2023-17"},{"x":"소관 중앙행정기관의 장은 5년마다 기초생활보장 시행계획을 수립하여야 한다.","o":"3년마다 기초생활보장 기본계획을 수립한다.","src":"국민기초생활 보장법 제20조의2제1항 | 기출 2023-17"},{"x":"시장ㆍ군수ㆍ구청장은 중앙생활보장위원회를 둔다.","o":"중앙생활보장위원회는 보건복지부에 둔다.","src":"국민기초생활 보장법 제20조 | 기출 2023-8"},{"x":"「입양특례법」에 따라 국내에 입양된 아동은 25세까지 수급권자로 특례 적용된다.","o":"출제 오답(바른 연령 미확인). 기초생활보장법 입양 특례는 시행령이 정하는 아동 연령 범위.","src":"보충(원문 미확인) | 기출 2025-21"},{"x":"보건복지부장관은 수행기관의 통합정보전산망 사용 요청에 대하여 특별한 사정이 없는 한 모든 정보를 제공하여야 한다.","o":"출제 오답(바른 문장 미확인). 수행기관은 보호대책을 마련하고 정보주체 동의를 받아야 한다.","src":"보충(원문 미확인) | 기출 2025-19"},{"x":"시ㆍ도지사는 의료급여증을 발급하여야 한다.","o":"시장·군수·구청장이 수급권자 신청 시 발급한다.","src":"의료급여법 제8조제1항 | 기출 2024-15"},{"x":"급여비용의 재원을 충당하기 위하여 보건복지부에 의료급여기금을 설치한다.","o":"시·도에 의료급여기금을 설치한다.","src":"의료급여법 제25조제1항 | 기출 2024-15"},{"x":"시ㆍ도지사는 상환받은 대지급금을 의료급여기금에 납입하여야 한다.","o":"대지급금을 상환받은 시장·군수·구청장이 의료급여기금에 납입한다.","src":"의료급여법 제21조제3항 | 기출 2024-15"},{"x":"수급권자가 의료급여를 거부한 경우 시ㆍ도지사는 의료급여를 중지해야 한다.","o":"시장·군수·구청장이 중지하여야 하고 거부한 경우 가구원 전부에 대해 중지.","src":"의료급여법 제17조 | 기출 2024-15"},{"x":"시장ㆍ군수ㆍ구청장은 수급권자가 의료급여를 거부한 경우라도 의료급여를 중지하여서는 안 된다.","o":"거부한 경우 의료급여를 중지하여야 한다.","src":"의료급여법 제17조제1항 | 기출 2026-14"},{"x":"의료급여에 관한 업무는 수급권자의 출생지를 관할하는 시장ㆍ군수ㆍ구청장이 한다.","o":"수급권자의 거주지를 관할하는 시·도지사와 시장·군수·구청장이 한다.","src":"의료급여법 제5조 | 기출 2025-21"},{"x":"「지역보건법」 에 따라 설치된 보건소는 의료급여기관이 될 수 없다.","o":"보건소·보건의료원·보건지소는 의료급여기관이다.","src":"의료급여법 제9조제1항제2호 | 기출 2025-21"},{"x":"시장ㆍ군수ㆍ구청장은 수급권자가 정당한 이유 없이 의료급여기관의 진료에 관한 지시에 따르지 아니한 경우에도 의료급여를 제한해서는 아니 된다.","o":"이 경우 의료급여를 하지 아니한다(보건복지부장관이 필요하다고 인정하면 예외).","src":"의료급여법 제15조제1항제2호 | 기출 2025-21"},{"x":"보건복지부장관은 선정기준액을 정하는 경우 65세 이상인 사람 중 기초연금 수급자가 100분의 90 수준이 되도록 한다.","o":"100분의 70 수준이 되도록 한다.","src":"기초연금법 제3조제2항 | 기출 2026-15"},{"x":"국민연금기금은 기초연금 지급을 위한 재원으로 사용할 수 있다.","o":"국민연금기금은 기초연금 지급 재원으로 사용할 수 없다.","src":"기초연금법 제4조제2항 | 기출 2026-15"},{"x":"기초연금 수급자의 국외 체류기간이 30일 이상 지속되는 경우 기초연금의 지급이 정지된다.","o":"60일 이상 지속되는 경우.","src":"기초연금법 제16조제1항제3호 | 기출 2026-15"},{"x":"기초연금으로 지급받은 금품은 압류될 수 있다.","o":"압류할 수 없다.","src":"기초연금법 제21조제2항 | 기출 2026-15"}]},"#7":{"묶음":[{"머리":"국민연금법 총칙·관장·위원회","줄":[{"t":"국민연금법 목적: 국민의 노령 장애 또는 사망에 대하여 연금급여를 실시해 생활 안정과 복지 증진에 이바지","src":"국민연금법 제1조"},{"t":"관장: 국민연금사업은 보건복지부장관이 맡아 주관한다(기획재정부장관 아님)","src":"국민연금법 제2조 | 기출 2024-19"},{"t":"근로자: 직업의 종류와 상관없이 사업장에서 노무를 제공하고 임금을 받아 생활하는 자(법인의 이사와 임원 포함)","src":"국민연금법 제3조제1항제1호"},{"t":"사용자: 해당 근로자가 소속된 사업장의 사업주","src":"국민연금법 제3조제1항제2호"},{"t":"평균소득월액: 매년 사업장가입자 및 지역가입자 전원의 기준소득월액을 평균한 금액","src":"국민연금법 제3조제1항제4호"},{"t":"기준소득월액: 연금보험료와 급여를 산정하기 위해 가입자의 소득월액을 기준으로 정하는 금액","src":"국민연금법 제3조제1항제5호"},{"t":"부담금은 사용자가 부담하는 금액 / 기여금은 사업장가입자가 부담하는 금액","src":"국민연금법 제3조제1항제11호·제12호"},{"t":"수급권: 이 법에 따른 급여를 받을 권리. 수급권자: 수급권을 가진 자. 수급자: 급여를 받고 있는 자 (수급권자를 급여를 받을 권리라고 정의한 선지는 오답)","src":"국민연금법 제3조제1항제14호~제16호 | 기출 2024-19"},{"t":"배우자 남편 아내에는 사실상의 혼인관계에 있는 자를 포함한다","src":"국민연금법 제3조제2항 | 기출 2024-19"},{"t":"국민연금심의위원회: 보건복지부에 둔다. 심의 사항은 제도 및 재정 계산 / 급여 / 연금보험료 / 기금 / 보건복지부장관이 부의하는 사항. 위원장은 보건복지부차관","src":"국민연금법 제5조"},{"t":"국민연금공단: 보건복지부장관의 위탁을 받아 설립. 업무는 가입자 기록 관리 / 연금보험료 부과 / 급여 결정 및 지급 / 복지사업 / 자금 대여 / 노후준비서비스 / 조사연구 / 기금운용 인력 양성 / 국제협력 등. 연금보험료 징수는 건강보험공단에 위탁","src":"국민연금법 제24조 제25조 제88조"}]},{"머리":"가입자","줄":[{"t":"가입 대상: 국내에 거주하는 국민으로서 18세 이상 60세 미만(65세 미만 아님). 공무원연금·군인연금·사학연금·별정우체국법 적용 대상자 등은 제외","src":"국민연금법 제6조 | 기출 2024-19"},{"t":"가입자 종류 4가지: 사업장가입자 / 지역가입자 / 임의가입자 / 임의계속가입자","src":"국민연금법 제7조"},{"t":"사업장가입자: 당연적용사업장의 18세 이상 60세 미만 근로자와 사용자. 퇴직연금등수급권자는 제외(연계 신청 시 예외). 18세 미만 근로자는 사업장가입자로 보되 원하지 않으면 제외. 생계급여·의료급여 수급자는 희망에 따라 제외","src":"국민연금법 제8조"},{"t":"지역가입자: 사업장가입자가 아닌 18세 이상 60세 미만. 제외 대상은 별도 소득 없는 배우자(가입 제외자 사업장·지역·임의계속가입자 노령연금 수급권자 퇴직연금등수급권자의 배우자) / 퇴직연금등수급권자 / 18세 이상 27세 미만 학생·군 복무 등 소득 없는 자 / 생계급여·의료급여 수급자 / 1년 이상 행방불명자","src":"국민연금법 제9조"},{"t":"임의가입자: 사업장가입자·지역가입자 외의 18세 이상 60세 미만이 공단에 신청해 가입. 신청으로 탈퇴 가능","src":"국민연금법 제10조"},{"t":"임의계속가입자: 60세가 된 가입자 또는 가입자였던 자가 65세가 될 때까지 신청해 가입(연금보험료 납부 사실 없는 자 / 노령연금 수급 중인 자 / 반환일시금 수령자는 제외). 특수직종근로자 특례 있음","src":"국민연금법 제13조"},{"t":"사업장가입자 자격 취득: 당연적용사업장에 고용된 때 또는 사용자가 된 때 / 사업장이 당연적용사업장이 된 때. 지역가입자는 사업장가입자 자격 상실 시 등. 임의가입자는 신청 수리일","src":"국민연금법 제11조"},{"t":"사업장가입자 자격 상실: 사망 / 국적 상실·국외 이주 / 사용관계 종료 / 60세가 된 때 → 해당일의 다음 날 상실. 가입 대상 제외자가 된 때는 해당일 상실","src":"국민연금법 제12조제1항"},{"t":"사고 선박·항공기 탑승자 등 생사를 알 수 없는 사람은 대통령령에 따라 사망한 것으로 추정","src":"국민연금법 제15조"}]},{"머리":"가입기간","줄":[{"t":"가입기간은 월 단위로 계산한다. 자격을 취득한 날이 속하는 달의 다음 달부터 자격 상실일의 전날이 속하는 달까지. 취득일이 초일이거나 임의계속가입자이거나 가입자가 희망하면 취득한 달부터 산입","src":"국민연금법 제17조제1항 | 기출 2026-16"},{"t":"연금보험료를 내지 않은 기간은 산입하지 않는다. 사용자가 기여금을 공제하고 보험료를 내지 않으면 그 기간의 2분의 1을 근로자 가입기간으로 산입(1개월 미만은 1개월)","src":"국민연금법 제17조제2항"},{"t":"군 복무 크레딧: 현역병 전환복무 상근예비역 사회복무요원의 복무기간을 12개월 한도로 가입기간에 추가 산입(병역 6개월 미만은 제외). 재원은 국가가 전부 부담","src":"국민연금법 제18조"},{"t":"출산 크레딧: 자녀 2명 이하는 자녀 1명마다 12개월을 가산. 3명 이상은 첫째·둘째 24개월에 2자녀를 초과하는 자녀 1명마다 18개월을 더한다. 부모가 모두 가입자이면 합의로 1명에게 산입하고 합의가 없으면 균등 배분. 재원은 국가가 전부 또는 일부 부담 (2026 기출 정답 문장은 둘째부터 12개월 적용)","src":"국민연금법 제19조 | 기출 2026-16"},{"t":"실업 크레딧: 18세 이상 60세 미만 가입자(였던 자)가 고용보험법상 구직급여를 받는 경우 신청하면 그 기간을 추가 산입. 1년을 초과할 수 없다. 인정소득은 구직급여 산정 기초 임금일액을 월액으로 환산한 금액의 절반","src":"국민연금법 제19조의2 | 기출 2026-16"},{"t":"가입기간 합산: 자격을 상실한 뒤 다시 취득하면 전후 가입기간을 합산한다. 가입 종류가 변동되면 각 종류별 가입기간을 합산","src":"국민연금법 제20조 | 기출 2024-19, 2026-16"}]},{"머리":"급여의 종류·공통 사항","줄":[{"t":"급여 종류 4가지: 노령연금 / 장애연금 / 유족연금 / 반환일시금 (장해급여 장애인연금은 이 법의 급여가 아님. 사망일시금은 급여 종류 열거 외 별도 규정 제80조)","src":"국민연금법 제49조 | 기출 2021-16, 2022-17"},{"t":"급여는 수급권자의 청구에 따라 공단이 지급. 연금액은 지급사유에 따라 기본연금액과 부양가족연금액을 기초로 산정","src":"국민연금법 제50조"},{"t":"연금 지급: 지급 사유가 생긴 날이 속하는 달의 다음 달부터 수급권 소멸일이 속하는 달까지. 매월 25일 지급(지급일이 토요일이나 공휴일이면 그 전날)","src":"국민연금법 제54조"},{"t":"미지급 급여: 수급권자 사망 시 배우자·자녀·부모·손자녀·조부모·형제자매 순으로 청구하고 사망한 날부터 5년 이내 청구","src":"국민연금법 제55조"},{"t":"중복급여 조정: 둘 이상 수급권이 생기면 수급권자 선택으로 하나만 지급. 선택하지 않은 유족연금이면 유족연금액의 100분의 30을 추가 지급","src":"국민연금법 제56조"},{"t":"수급권 보호: 양도·압류·담보 제공을 할 수 없다. 급여수급전용계좌 입금액도 압류 불가","src":"국민연금법 제58조"},{"t":"급여 제한: 고의로 질병·부상·사고를 일으켜 장애를 입으면 장애연금을 지급하지 않을 수 있다. 가입자 등을 고의로 사망하게 한 유족 등에게는 유족연금 등 지급하지 않음","src":"국민연금법 제82조"},{"t":"지급 정지: 정당한 사유 없이 서류 제출 요구·진단 요구에 응하지 않거나 신고를 하지 않은 때 등 급여의 전부 또는 일부 지급 정지 가능","src":"국민연금법 제86조"}]},{"머리":"노령연금","줄":[{"t":"노령연금 수급권자: 가입기간 10년 이상인 가입자 또는 가입자였던 자에게 60세(특수직종근로자 55세)부터 생존하는 동안 지급","src":"국민연금법 제61조제1항"},{"t":"조기노령연금: 가입기간 10년 이상 55세 이상인 자가 소득 있는 업무에 종사하지 않으면 본인이 희망하는 경우 60세 전에 청구해 받을 수 있다","src":"국민연금법 제61조제2항"},{"t":"지급 연기: 60세 이상 65세 미만 수급권자가 65세 전까지 연금의 전부 또는 일부 지급을 연기할 수 있다. 연기 1개월마다 1천분의 6 가산. 일부 연기는 1천분의 500~900 다섯 단계","src":"국민연금법 제62조"},{"t":"노령연금액: 가입기간 20년 이상이면 기본연금액. 10년 이상 20년 미만이면 기본연금액의 1천분의 500 + 10년 초과 1년마다 1천분의 50. 여기에 부양가족연금액을 더한다","src":"국민연금법 제63조제1항"},{"t":"조기노령연금액 비율: 55세 1천분의 700 / 56세 760 / 57세 820 / 58세 880 / 59세 940 (청구가 연령 도달 다음 달 이후이면 1개월마다 1천분의 5 가산)","src":"국민연금법 제63조제2항"},{"t":"소득활동에 따른 감액: 60~65세 미만 노령연금 수급권자가 소득 있는 업무에 종사하면 초과소득월액 구간(200만원 이상 300만원 미만 15만원+초과분의 1천분의 150 / 300~400만원 30만원+1천분의 200 / 400만원 이상 50만원+1천분의 250)을 뺀다. 감액은 노령연금액의 2분의 1 한도","src":"국민연금법 제63조의2"},{"t":"분할연금: 혼인 기간(별거 가출 등 실질 혼인관계가 없던 기간 제외)이 5년 이상인 자가 ① 배우자와 이혼 ② 배우자였던 자가 노령연금 수급권자 ③ 60세가 된 요건을 모두 갖추면 받는다. 분할연금액은 노령연금액 중 혼인 기간에 해당하는 연금액을 균등하게 나눈 금액. 요건을 갖춘 때부터 5년 이내 청구","src":"국민연금법 제64조"},{"t":"분할연금 수급권은 취득 후 배우자였던 자에게 생긴 사유로 노령연금 수급권이 소멸·정지되어도 영향을 받지 않는다. 분할연금 수급권자에게 노령연금 수급권이 발생하면 합산 지급","src":"국민연금법 제65조"},{"t":"조기노령연금 지급 정지: 60세 미만 수급자가 소득 있는 업무에 종사하거나 본인이 정지를 신청하면 정지. 60세 도달 시 등 재지급","src":"국민연금법 제66조"}]},{"머리":"장애연금","줄":[{"t":"장애연금 수급권자 요건: 가입자 또는 가입자였던 자가 질병·부상으로 장애가 있고 ① 초진일 당시 18세 이상이고 노령연금 지급 연령 미만 ② 가입대상기간의 3분의 1 이상 보험료 납부 / 초진일 5년 전부터 초진일까지 3년 이상 납부 / 초진일 당시 가입기간 10년 이상 중 하나","src":"국민연금법 제67조제1항"},{"t":"장애결정 기준일: 초진일부터 1년 6개월이 지나기 전에 완치일이 있으면 완치일. 1년 6개월까지 완치일이 없으면 1년 6개월이 되는 날의 다음 날","src":"국민연금법 제67조제2항"},{"t":"장애연금 불지급: 초진일이 가입 대상 제외 기간이거나 국외이주·국적상실 기간 중인 경우 / 반환일시금을 지급받은 경우. 장애등급은 1급~4급","src":"국민연금법 제67조제3항·제4항"}]},{"머리":"유족연금","줄":[{"t":"유족연금 지급 대상 사망자: ① 노령연금 수급권자 ② 가입기간 10년 이상인 가입자 또는 가입자였던 자 ③ 연금보험료를 낸 기간이 가입대상기간의 3분의 1 이상인 가입자 또는 가입자였던 자 ④ 사망일 5년 전부터 사망일까지 3년 이상 납부한 가입자 또는 가입자였던 자(체납 3년 이상 제외) ⑤ 장애등급 2급 이상인 장애연금 수급권자","src":"국민연금법 제72조제1항"},{"t":"유족의 범위: 사망자에 의하여 생계를 유지하던 ① 배우자 ② 자녀(25세 미만 또는 장애상태) ③ 부모(배우자의 부모 포함 60세 이상 또는 장애상태) ④ 손자녀(19세 미만 또는 장애상태) ⑤ 조부모(배우자의 조부모 포함 60세 이상 또는 장애상태). 순위에 따라 최우선 순위자에게만 지급","src":"국민연금법 제73조"},{"t":"유족연금액: 가입기간 10년 미만 기본연금액의 1천분의 400 / 10년 이상 20년 미만 1천분의 500 / 20년 이상 1천분의 600 + 부양가족연금액. 노령연금 수급권자가 사망한 경우 그가 받던 노령연금액 초과 불가","src":"국민연금법 제74조"},{"t":"유족연금 수급권 소멸: 수급권자 사망 / 배우자인 수급권자 재혼 / 자녀·손자녀 파양 / 장애상태가 아닌 자녀가 25세 또는 손자녀가 19세가 된 때","src":"국민연금법 제75조"},{"t":"유족연금 지급 정지: 배우자는 수급권 발생 후 3년 동안 지급하고 55세가 될 때까지 정지(장애상태 / 25세 미만 자녀 생계 유지 / 소득 있는 업무 미종사 시 정지 안 함). 소재를 1년 이상 알 수 없는 경우 정지","src":"국민연금법 제76조"}]},{"머리":"반환일시금·사망일시금","줄":[{"t":"반환일시금 지급 사유: 가입기간 10년 미만인 자가 60세가 된 때 / 가입자 또는 가입자였던 자가 사망한 때(유족연금이 지급되는 경우 제외) / 국적을 상실하거나 국외로 이주한 때. 액수는 납부한 연금보험료(사업장가입자는 사용자 부담금 포함)에 이자를 더한 금액","src":"국민연금법 제77조"},{"t":"반환일시금 수급권 소멸: 다시 가입자가 된 때 / 노령연금 수급권 취득 / 장애연금 수급권 취득 / 유족이 유족연금 수급권 취득","src":"국민연금법 제79조"},{"t":"사망일시금: 가입자 노령연금 수급권자 장애등급 3급 이상 장애연금 수급권자가 사망했는데 유족연금 대상 유족이 없으면 배우자·자녀·부모·손자녀·조부모·형제자매·4촌 이내 방계혈족 순으로 지급. 가입자 사망 시 반환일시금 상당액(최종 기준소득월액 평균의 4배 한도)","src":"국민연금법 제80조"}]},{"머리":"보험료·기금·불복·시효","줄":[{"t":"연금보험료: 사업장가입자의 기여금과 부담금은 각각 기준소득월액의 1천분의 65(합계 1천분의 130). 지역가입자·임의가입자·임의계속가입자는 본인이 기준소득월액의 1천분의 130 부담","src":"국민연금법 제88조제3항·제4항"},{"t":"납부 기한: 다음 달 10일까지(농어업인은 신청하면 분기별로 해당 분기의 다음 달 10일까지)","src":"국민연금법 제89조"},{"t":"납부 예외: 사업 중단·실직·휴직 / 병역의무 수행 / 학교 재학 / 교정시설 수용 / 치료감호시설 수용 / 1년 미만 행방불명 / 소득 감소 등. 내지 않은 기간은 가입기간에 산입하지 않음","src":"국민연금법 제91조"},{"t":"추후 납부(추납): 10년 미만의 범위에서 납부 예외 기간 등에 상응하는 보험료를 추후 납부 신청 가능","src":"국민연금법 제92조"},{"t":"징수권 소멸 등: 지역가입자 등의 보험료를 징수할 권리는 가입자 사망 / 노령연금 또는 반환일시금 수령 / 소멸시효 완성 때 소멸","src":"국민연금법 제99조"},{"t":"국민연금기금: 보건복지부장관이 설치하고 관리·운용. 재원은 연금보험료 / 기금 운용 수익금 / 적립금 / 공단 결산상 잉여금. 국민연금기금운용위원회가 기금운용을 심의·의결(위원 임기 2년 1차 연임 회의 연 4회 이상)","src":"국민연금법 제101조~제103조"},{"t":"불복: 심사청구는 공단 또는 건강보험공단에 처분을 안 날부터 90일 이내 문서로 하고 처분이 있은 날부터 180일 경과 시 제기 불가. 재심사청구는 결정통지를 받은 날부터 90일 이내에 국민연금재심사위원회(보건복지부 위원장 포함 20명 이내)","src":"국민연금법 제108조~제111조"},{"t":"시효: 보험료 등 징수권 3년 / 급여를 받을 권리와 과오납금 반환 및 환수금 환수 5년 / 가입기간 10년 미만 60세 반환일시금 10년","src":"국민연금법 제115조"},{"t":"외국인: 외국인도 당연히 사업장가입자 또는 지역가입자가 된다(본국 법이 상호주의에 맞지 않으면 제외). 사회보장협정이 있으면 그 협정에 따른다","src":"국민연금법 제126조 제127조"}]},{"머리":"건강보험법 총칙·계획·위원회","줄":[{"t":"국민건강보험법 목적: 질병·부상의 예방·진단·치료·재활과 출산·사망 및 건강증진에 대해 보험급여를 실시해 국민보건 향상과 사회보장 증진에 이바지","src":"국민건강보험법 제1조"},{"t":"건강보험사업은 보건복지부장관이 맡아 주관한다","src":"국민건강보험법 제2조"},{"t":"근로자: 직업 종류와 관계없이 근로 대가로 보수를 받아 생활하는 사람(법인의 이사 등 임원 포함)으로서 공무원과 교직원은 제외","src":"국민건강보험법 제3조제1호"},{"t":"사용자: 근로자가 속한 사업장의 사업주 / 공무원이 소속된 기관의 장으로서 대통령령이 정하는 사람 / 사립학교를 설립·운영하는 자","src":"국민건강보험법 제3조제2호"},{"t":"국민건강보험종합계획: 보건복지부장관이 건강보험정책심의위원회 심의를 거쳐 5년마다 수립. 시행계획은 매년 수립·시행하고 추진실적을 매년 평가하며 국회 소관 상임위원회에 보고","src":"국민건강보험법 제3조의2 | 기출 2024-17"},{"t":"종합계획 포함 사항: 건강보험정책의 기본목표 및 추진방향 / 보장성 강화 추진계획 / 중장기 재정 전망 및 운영 / 보험료 부과체계 / 요양급여비용 / 건강증진 사업 / 취약계층 지원 / 통계 및 정보 관리 / 그 밖에 대통령령이 정하는 사항","src":"국민건강보험법 제3조의2제2항"},{"t":"건강보험정책심의위원회: 건강보험정책을 심의·의결하기 위해 보건복지부장관 소속으로 둔다. 심의 사항은 종합계획 및 시행계획(의결 제외) / 요양급여의 기준 / 요양급여비용 / 직장가입자 보험료율 / 지역가입자 보험료율과 재산보험료부과점수당 금액 / 보험료 부과 제도 개선(의결 제외) / 그 밖의 주요 사항","src":"국민건강보험법 제4조제1항 | 기출 2024-17"},{"t":"심의위원회 구성: 위원장 1명 부위원장 1명 포함 25명. 위원장은 보건복지부차관. 위원 임기 3년(공무원 위원 제외)","src":"국민건강보험법 제4조제2항~제5항"}]},{"머리":"가입자·피부양자","줄":[{"t":"적용 대상: 국내에 거주하는 국민은 가입자 또는 피부양자가 된다. 의료급여법에 따라 의료급여를 받는 사람(수급권자)과 의료보호를 받는 유공자등 의료보호대상자는 제외(유공자는 신청 시 가입)","src":"국민건강보험법 제5조제1항 | 기출 2024-17"},{"t":"피부양자: 직장가입자에게 주로 생계를 의존하는 사람으로 소득·재산이 보건복지부령 기준 이하인 ① 배우자 ② 직계존속(배우자의 직계존속 포함) ③ 직계비속(배우자의 직계비속 포함)과 그 배우자 ④ 형제·자매","src":"국민건강보험법 제5조제2항"},{"t":"가입자 종류: 직장가입자와 지역가입자","src":"국민건강보험법 제6조제1항"},{"t":"직장가입자: 모든 사업장의 근로자 및 사용자와 공무원 및 교직원. 제외 대상은 고용 기간 1개월 미만 일용근로자 / 현역병·전환복무자·군간부후보생 / 선거로 취임하는 무보수 공무원 / 대통령령이 정하는 사업장의 근로자 등","src":"국민건강보험법 제6조제2항"},{"t":"지역가입자: 직장가입자와 그 피부양자를 제외한 가입자","src":"국민건강보험법 제6조제3항 | 기출 2024-17"},{"t":"자격 취득: 국내에 거주하게 된 날. 수급권자이었던 사람은 그 대상자에서 제외된 날 / 피부양자이었던 사람은 그 자격을 잃은 날 / 유공자등 의료보호대상자이었던 사람은 제외된 날. 사용자·세대주는 취득일부터 14일 이내 보험자에게 신고","src":"국민건강보험법 제8조"},{"t":"자격 변동: 지역가입자가 적용대상사업장의 사용자·근로자가 된 날 / 직장가입자가 다른 사업장의 사용자·근로자가 된 날 / 사용관계가 끝난 날의 다음 날 / 지역가입자가 다른 세대로 전입한 날. 변동일부터 14일 이내 신고","src":"국민건강보험법 제9조"},{"t":"자격 상실: 사망한 날의 다음 날 / 국적을 잃은 날의 다음 날 / 국내에 거주하지 아니하게 된 날의 다음 날(당일 아님) / 직장가입자의 피부양자가 된 날 / 수급권자가 된 날 / 유공자등 의료보호대상자가 되어 적용배제신청을 한 날","src":"국민건강보험법 제10조 | 기출 2024-17"}]},{"머리":"보험자·공단·심사평가원","줄":[{"t":"보험자: 국민건강보험공단(건강보험심사평가원 아님). 공단은 법인이며 주된 사무소 소재지에서 설립등기로 성립","src":"국민건강보험법 제13조 제15조 | 기출 2026-17"},{"t":"공단의 업무: 가입자 및 피부양자의 자격 관리 / 보험료와 그 밖의 징수금의 부과·징수 / 보험급여의 관리 / 질병의 조기발견·예방·건강관리 예방사업 / 보험급여 비용의 지급 / 자산의 관리·운영 및 증식사업 / 의료시설의 운영 / 건강보험 교육훈련 및 홍보 / 조사연구 및 국제협력 / 징수위탁근거법(국민연금법 고용산재보험료징수법 임금채권보장법 석면피해구제법)에 따라 위탁받은 업무 / 그 밖의 위탁 업무","src":"국민건강보험법 제14조제1항 | 기출 2021-18, 2022-16"},{"t":"요양급여비용 심사는 공단이 아니라 심사평가원 업무이다. 의료시설의 운영은 공단 업무","src":"국민건강보험법 제14조 제63조 | 기출 2021-18"},{"t":"임원: 이사장 1명 이사 14명 감사 1명(이사장·이사 5명·감사는 상임). 이사장 임기 3년 이사와 감사 임기 각 2년","src":"국민건강보험법 제20조"},{"t":"재정운영위원회: 공단에 두고 요양급여비용 계약 결손처분 등 보험재정 사항을 심의·의결. 직장가입자 대표 10명 / 지역가입자 대표 10명 / 공익대표 10명. 위원 임기 2년","src":"국민건강보험법 제33조 제34조"},{"t":"심사평가원: 요양급여비용을 심사하고 요양급여의 적정성을 평가하기 위해 설립. 업무는 요양급여비용의 심사 / 요양급여의 적정성 평가 / 심사기준 및 평가기준 개발 / 관련 조사연구 및 국제협력 / 다른 법률에 따른 급여비용 심사·평가 위탁 업무","src":"국민건강보험법 제62조 제63조 | 기출 2022-16, 2026-17"},{"t":"진료심사평가위원회: 심사평가원에 두며 위원장 포함 상근 90명 이내 비상근 1천명 이내","src":"국민건강보험법 제66조"}]},{"머리":"요양급여","줄":[{"t":"요양급여 7가지: 진찰·검사 / 약제·치료재료의 지급 / 처치·수술 및 그 밖의 치료 / 예방·재활 / 입원 / 간호 / 이송","src":"국민건강보험법 제41조제1항"},{"t":"요양급여 범위: 약제 외에는 비급여대상으로 정한 것을 제외한 일체. 약제는 보건복지부장관이 요양급여대상으로 결정·고시한 것","src":"국민건강보험법 제41조제2항"},{"t":"선별급여: 경제성·치료효과성 등이 불확실해 추가 근거가 필요하거나 경제성이 낮아도 건강회복에 잠재적 이득이 있는 경우 예비적 요양급여로 지정. 보건복지부장관이 주기적으로 적합성 평가","src":"국민건강보험법 제41조의4"},{"t":"요양기관(간호와 이송은 제외): 의료기관 / 약국 / 한국희귀·필수의약품센터 / 보건소·보건의료원·보건지소 / 보건진료소. 정당한 이유 없이 요양급여를 거부하지 못한다","src":"국민건강보험법 제42조"},{"t":"본인일부부담금: 요양급여를 받는 자가 대통령령에 따라 비용의 일부 부담. 연간 본인부담상한액 초과 금액은 공단이 부담","src":"국민건강보험법 제44조"},{"t":"요양급여비용: 공단 이사장과 대통령령이 정하는 의약계 대표의 계약으로 정한다(계약기간 1년). 직전 계약기간 만료연도 5월 31일까지 계약 체결, 불발 시 보건복지부장관이 6월 30일까지 심의위원회 의결로 결정. 이사장은 재정운영위원회 의결을 거쳐 계약","src":"국민건강보험법 제45조"},{"t":"비용 청구: 요양기관이 심사평가원에 심사청구 → 심사평가원이 심사 후 공단과 요양기관에 통보 → 공단이 지급. 적정성 평가 결과에 따라 가산·감액","src":"국민건강보험법 제47조"},{"t":"요양비: 긴급하거나 부득이한 사유로 준요양기관에서 요양을 받거나 요양기관이 아닌 장소에서 출산한 경우 공단이 요양비로 지급","src":"국민건강보험법 제49조"},{"t":"부가급여: 임신·출산 진료비 / 장제비 / 상병수당 / 그 밖의 급여를 대통령령에 따라 실시할 수 있다","src":"국민건강보험법 제50조 | 기출 2025-22"},{"t":"장애인 특례: 등록장애인인 가입자 및 피부양자에게 보조기기에 대해 보험급여를 할 수 있다","src":"국민건강보험법 제51조"},{"t":"건강검진: 공단이 가입자와 피부양자에 대해 실시. 일반건강검진(직장가입자 세대주인 지역가입자 20세 이상 지역가입자 20세 이상 피부양자) / 암검진 / 영유아건강검진(6세 미만)","src":"국민건강보험법 제52조 | 기출 2025-22"}]},{"머리":"급여의 제한·정지","줄":[{"t":"급여 제한(하지 아니한다): 고의 또는 중대한 과실로 인한 범죄행위에 원인이 있거나 고의 사고 / 고의 또는 중대한 과실로 공단·요양기관의 요양 지시에 따르지 않음 / 문서 제출 거부·질문·진단 기피 / 업무 또는 공무로 생긴 질병·부상·재해로 다른 법령의 보험급여나 보상을 받게 되는 경우","src":"국민건강보험법 제53조제1항 | 기출 2025-22"},{"t":"다른 법령에 따라 국가·지방자치단체로부터 보험급여에 상당하는 급여를 받으면 그 한도에서 하지 않는다. 보험료 체납(보수 외 소득월액보험료 또는 세대단위 보험료)이 대통령령 기간 이상이면 완납 시까지 급여를 하지 않을 수 있다","src":"국민건강보험법 제53조제2항·제3항"},{"t":"급여 정지: 국외에 체류하는 경우 / 현역병 등 직장가입자 제외 사유에 해당하게 된 경우 / 교도소 등에 수용된 경우 (현역병·수용 시 요양급여비용 지급은 별도)","src":"국민건강보험법 제54조"},{"t":"부당이득 징수: 속임수 등 부당한 방법으로 보험급여를 받은 사람 요양기관 준요양기관 보조기기 판매업자에게 징수","src":"국민건강보험법 제57조"},{"t":"구상권: 제3자의 행위로 보험급여사유가 생겨 급여를 한 경우 급여 비용 한도에서 제3자에게 손해배상 청구권","src":"국민건강보험법 제58조"},{"t":"수급권 보호: 보험급여를 받을 권리는 양도하거나 압류할 수 없다","src":"국민건강보험법 제59조"}]},{"머리":"보험료","줄":[{"t":"보험료 징수 기간: 자격 취득일이 속하는 달의 다음 달부터 자격 상실일의 전날이 속하는 달까지(매월 1일 취득이면 그 달부터)","src":"국민건강보험법 제69조제2항"},{"t":"직장가입자 월별 보험료: 보수월액보험료(보수월액 x 보험료율) + 보수 외 소득월액보험료. 지역가입자: 세대 단위로 소득(소득월액 x 보험료율) + 재산(재산보험료부과점수 x 점수당 금액)","src":"국민건강보험법 제69조제4항·제5항"},{"t":"직장가입자 보험료율은 1천분의 80의 범위에서 심의위원회 의결로 대통령령이 정한다. 국외 업무 종사 직장가입자는 그 보험료율의 100분의 50","src":"국민건강보험법 제73조"},{"t":"보험료 면제: 직장가입자가 급여정지 사유(국외 체류 1개월 이상 등 현역병 수용)에 해당하면 면제. 지역가입자는 세대 보험료 산정에서 그 가입자의 소득과 재산 제외","src":"국민건강보험법 제74조"},{"t":"보험료 경감 대상: 섬·벽지·농어촌 거주자 / 65세 이상 / 등록장애인 / 국가유공자 / 휴직자 / 생활이 어려운 사람 등","src":"국민건강보험법 제75조"},{"t":"보험료 부담: 직장가입자 보수월액보험료는 직장가입자와 사업주(공무원은 국가·지방자치단체 / 교직원은 사용자)가 각 100분의 50씩 부담. 사립학교 교원은 본인 50 사용자 30 국가 20. 보수 외 소득월액보험료는 직장가입자 부담. 지역가입자는 세대 전원이 연대 부담","src":"국민건강보험법 제76조"},{"t":"납부의무: 보수월액보험료는 사용자(2명 이상이면 연대). 보수 외 소득월액보험료는 직장가입자. 지역가입자는 세대 전원 연대. 사용자는 근로자 부담분을 보수에서 공제해 납부","src":"국민건강보험법 제77조"},{"t":"납부기한: 그 달의 보험료를 다음 달 10일까지. 보수 외 소득월액보험료와 지역가입자 보험료는 분기별 납부 가능","src":"국민건강보험법 제78조"},{"t":"연체금: 납부기한이 지난 날부터 매 1일마다 체납금액의 1천500분의 1(상한 1천분의 20). 30일이 지나면 6천분의 1을 더 징수(합계 상한 1천분의 50)","src":"국민건강보험법 제80조"},{"t":"정부지원: 국가는 매년 보험료 예상 수입액의 100분의 14에 상당하는 금액을 국고에서 공단에 지원. 국민건강증진기금에서도 지원받을 수 있다","src":"국민건강보험법 제108조의2"}]},{"머리":"불복·시효·특례","줄":[{"t":"이의신청: 공단 처분은 공단에 심사평가원 처분은 심사평가원에 처분을 안 날부터 90일 이내 문서로 하고 처분이 있은 날부터 180일 경과 시 제기 불가","src":"국민건강보험법 제87조"},{"t":"심판청구: 이의신청 결정에 불복하면 보건복지부 건강보험분쟁조정위원회(위원장 포함 60명 이내)에 청구. 이후 행정소송","src":"국민건강보험법 제88조~제90조"},{"t":"시효 3년: 보험료·연체금·가산금 징수권 / 과오납금 환급권 / 보험급여를 받을 권리 / 보험급여 비용을 받을 권리 / 과다 본인일부부담금 반환권 / 근로복지공단의 권리","src":"국민건강보험법 제91조"},{"t":"요양기관 업무정지: 보건복지부장관이 1년의 범위에서 명할 수 있다. 업무정지에 갈음해 부당 부담금액의 5배 이하 과징금(12개월 분할납부)","src":"국민건강보험법 제98조 제99조"},{"t":"외국인 특례: 국내체류 재외국민·외국인도 일정 요건을 갖추면 직장가입자 지역가입자 피부양자가 될 수 있다","src":"국민건강보험법 제109조"},{"t":"실업자 특례(임의계속가입): 사용관계가 끝난 사람 중 직장가입자 자격 유지기간이 통산 1년 이상이면 신청해 직장가입자 자격을 유지. 보수월액은 최근 12개월 평균. 보험료는 본인이 전액 부담","src":"국민건강보험법 제110조"}]},{"머리":"고용보험법 총칙","줄":[{"t":"고용보험법 목적: 실업의 예방 고용의 촉진 직업능력의 개발과 향상 직업지도·직업소개 기능 강화 실업 시 생활에 필요한 급여로 생활안정과 구직 활동을 촉진","src":"고용보험법 제1조"},{"t":"피보험자: 고용산재보험료징수법에 따라 보험에 가입되었거나 가입된 것으로 보는 근로자 예술인 노무제공자 / 고용보험에 가입한 자영업자","src":"고용보험법 제2조제1호"},{"t":"이직: 피보험자와 사업주 사이의 고용관계가 끝나게 되는 것","src":"고용보험법 제2조제2호"},{"t":"실업: 근로의 의사와 능력이 있음에도 불구하고 취업하지 못한 상태에 있는 것 (근로의 의사와 능력이 없는 상태라는 선지는 오답)","src":"고용보험법 제2조제3호 | 기출 2022-19, 2024-20"},{"t":"실업의 인정: 직업안정기관의 장이 수급자격자가 실업한 상태에서 적극적으로 직업을 구하기 위해 노력하고 있다고 인정하는 것","src":"고용보험법 제2조제4호 | 기출 2024-20"},{"t":"일용근로자: 1개월 미만 동안 고용되는 사람 (3개월·6개월 미만이라는 선지는 오답)","src":"고용보험법 제2조제6호 | 기출 2022-19, 2024-20"},{"t":"보험은 고용노동부장관이 관장한다","src":"고용보험법 제3조"},{"t":"고용보험사업 4가지: 고용안정·직업능력개발 사업 / 실업급여 / 육아휴직 급여 / 출산전후휴가 급여 등. 보험연도는 정부의 회계연도에 따른다","src":"고용보험법 제4조 | 기출 2025-24"},{"t":"국고의 부담: 국가는 매년 보험사업에 드는 비용의 일부를 일반회계에서 부담하여야 한다(지방자치단체 아님). 관리·운영 비용은 예산 범위에서 부담할 수 있다","src":"고용보험법 제5조 | 기출 2022-19, 2024-20"},{"t":"고용보험위원회: 고용노동부에 둔다. 위원장 포함 20명 이내이고 위원장은 고용노동부차관. 위원은 근로자·사용자·공익·정부 대표를 같은 수로 구성. 보험제도 개선 / 보험료율 결정 / 사업 평가 / 기금운용 계획 등을 심의","src":"고용보험법 제7조"},{"t":"적용 범위: 근로자를 사용하는 모든 사업 또는 사업장. 대통령령으로 정하는 사업은 제외","src":"고용보험법 제8조"},{"t":"적용 제외: 소정근로시간이 대통령령 시간 미만인 근로자 / 국가공무원·지방공무원(별정직·임기제는 본인 의사로 가입 가능) / 사립학교교직원 연금법 적용자 / 그 밖의 대통령령 정하는 사람. 65세 이후 고용되거나 자영업을 개시한 사람에게는 실업급여 규정을 적용하지 않음","src":"고용보험법 제10조"},{"t":"피보험자격 취득일: 근로자는 이 법이 적용되는 사업에 고용된 날. 상실일: 이직한 날의 다음 날 / 사망한 날의 다음 날 / 적용 제외 근로자가 된 날 / 보험관계 소멸일","src":"고용보험법 제13조 제14조"}]},{"머리":"실업급여 종류·수급권 보호","줄":[{"t":"실업급여 종류: 구직급여와 취업촉진 수당","src":"고용보험법 제37조제1항 | 기출 2022-19, 2024-21"},{"t":"취업촉진 수당 4가지: 조기재취업 수당 / 직업능력개발 수당 / 광역 구직활동비 / 이주비 (구직급여는 취업촉진 수당이 아님)","src":"고용보험법 제37조제2항 | 기출 2021-17, 2022-19, 2024-21"},{"t":"실업급여를 받을 권리는 양도·압류하거나 담보로 제공할 수 없다. 실업급여수급계좌 예금 중 대통령령 금액 이하는 압류 불가","src":"고용보험법 제38조 | 기출 2024-20"}]},{"머리":"구직급여","줄":[{"t":"구직급여 수급 요건(모두 충족): ① 기준기간 동안 피보험 단위기간 합산 180일 이상 ② 근로의 의사와 능력이 있음에도 취업하지 못한 상태 ③ 이직사유가 수급자격 제한 사유에 해당하지 않을 것 ④ 재취업을 위한 노력을 적극적으로 할 것 ⑤ 일용근로자였던 사람은 근로일수 요건(신청월 직전 달 초일부터 신청일까지 근로일 수가 총 일수의 3분의 1 미만 / 건설일용근로자는 신청일 이전 14일간 연속 근로내역 없음) ⑥ 일용근로자는 90일 이상 일용근로 요건","src":"고용보험법 제40조제1항"},{"t":"기준기간: 이직일 이전 18개월(36개월 아님). 질병·부상 등으로 계속 30일 이상 보수를 받지 못한 경우 18개월에 그 일수를 가산(3년 한도). 1주 소정근로시간 15시간 미만 및 소정근로일수 2일 이하 근로자는 24개월","src":"고용보험법 제40조제2항 | 기출 2021-17"},{"t":"피보험 단위기간: 피보험기간 중 보수 지급의 기초가 된 날을 합하여 계산","src":"고용보험법 제41조"},{"t":"실업의 신고: 구직급여를 지급받으려는 사람은 이직 후 지체 없이 직업안정기관에 출석하여 실업을 신고하여야 한다. 신고에는 구직 신청과 수급자격 인정신청 포함. 이직확인서 발급 요청 가능","src":"고용보험법 제42조 | 기출 2021-17"},{"t":"수급자격의 인정: 직업안정기관의 장에게 인정 신청. 마지막 이직 사업을 기준으로 인정 여부 결정","src":"고용보험법 제43조"},{"t":"실업의 인정: 수급자격자가 실업한 상태에 있는 날 중 직업안정기관의 장으로부터 실업의 인정을 받은 날에 대해 지급. 실업신고일부터 1주~4주 범위에서 지정한 실업인정일에 출석해 재취업 노력을 신고","src":"고용보험법 제44조"},{"t":"기초일액: 수급자격 인정과 관련된 마지막 이직 당시 근로기준법상 평균임금. 통상임금보다 적으면 통상임금","src":"고용보험법 제45조"},{"t":"구직급여일액: 기초일액의 100분의 60. 최저기초일액(이직 전 1일 소정근로시간 x 최저임금)이 적용되면 그 기초일액의 100분의 80(최저구직급여일액)","src":"고용보험법 제46조"},{"t":"수급기간: 이직일의 다음 날부터 12개월 내에 소정급여일수를 한도로 지급. 임신·출산·육아 등 취업 불가 사유를 신고하면 최대 4년까지 가산","src":"고용보험법 제48조"},{"t":"대기기간: 실업의 신고일부터 7일간은 대기기간으로 보아 구직급여를 지급하지 않는다(14일은 오답). 건설일용근로자는 신고일부터 지급","src":"고용보험법 제49조 | 기출 2021-17"},{"t":"소정급여일수: 대기기간이 끝난 다음 날부터 피보험기간과 연령에 따라 별표 1에서 정한 일수까지. 피보험기간은 이직 당시 적용 사업에서 고용된 기간이며 종전 적용 사업의 피보험자격 상실일부터 3년 이내 재취득하면 합산","src":"고용보험법 제50조"},{"t":"소정급여일수 별표 1: 30세 미만 120~240일 / 30세 이상 50세 미만 120~270일 / 50세 이상 및 장애인 120~270일 (피보험기간 1년 미만 120일 → 10년 이상 최대)","src":"고용보험법 별표 1 | 보충(원문 미확인)"},{"t":"연장급여 3가지: 훈련연장급여(직업능력개발 훈련 중 소정급여일수 초과 지급) / 개별연장급여(취업이 특히 곤란하고 생활이 어려운 자에게 60일 범위) / 특별연장급여(고용노동부장관이 실업 급증 등 사유로 60일 범위에서 기간을 정해 실시)","src":"고용보험법 제51조~제53조"},{"t":"지급일: 대통령령에 따라 실업의 인정을 받은 일수분을 지급","src":"고용보험법 제56조"},{"t":"이직 사유에 따른 수급자격 제한: ① 중대한 귀책사유로 해고된 피보험자(형법 또는 직무 관련 법률 위반으로 금고 이상 형 선고 / 사업에 막대한 지장을 초래하거나 재산상 손해를 끼침 / 정당한 사유 없이 장기간 무단 결근) ② 자기 사정으로 이직한 피보험자(전직·자영업 이직 / 귀책사유가 있는데 해고되지 않고 사업주 권고로 이직 / 정당하지 않은 사유 이직)","src":"고용보험법 제58조 | 기출 2023-18"},{"t":"사업기밀을 경쟁관계에 있는 사업자에게 제공한 경우도 중대한 귀책사유(사업에 막대한 지장 초래 등) 해당","src":"고용보험법 제58조제1호나목 | 기출 2023-18"},{"t":"훈련 거부 등에 따른 지급 제한: 직업안정기관이 소개한 직업의 취직 거부 또는 지시한 직업능력개발 훈련 거부 시 구직급여 지급 정지. 정지 기간은 1개월 범위","src":"고용보험법 제60조"},{"t":"부정행위 시: 거짓·부정한 방법으로 받거나 받으려 한 사람에게는 그 날부터의 구직급여 지급 안 함. 반환 명령에 더해 2배 이하(사업주와 공모 시 5배 이하) 추가 징수","src":"고용보험법 제61조 제62조"}]},{"머리":"취업촉진 수당","줄":[{"t":"조기재취업 수당: 수급자격자가 안정된 직업에 재취직하거나 스스로 영리 사업을 영위하는 경우 대통령령 기준에 해당하면 지급. 금액은 소정급여일수 중 미지급일수 비율에 따라 산정","src":"고용보험법 제64조 | 기출 2024-21"},{"t":"직업능력개발 수당: 직업안정기관의 장이 지시한 직업능력개발 훈련 등을 받는 기간에 지급","src":"고용보험법 제65조 | 기출 2024-21"},{"t":"광역 구직활동비: 직업안정기관의 소개에 따라 광범위한 지역에서 구직 활동을 하는 경우 필요하다고 인정하면 지급","src":"고용보험법 제66조 | 기출 2024-21"},{"t":"이주비: 취업 또는 훈련을 위해 주거를 이전하는 경우 필요하다고 인정하면 지급","src":"고용보험법 제67조 | 기출 2024-21"}]},{"머리":"육아휴직·출산전후휴가 급여","줄":[{"t":"육아휴직 급여: 육아휴직을 30일 이상(분할 사용 시 7일) 부여받은 피보험자 중 육아휴직 시작일 이전 피보험 단위기간이 합산 180일 이상인 사람에게 지급. 육아휴직 시작일 이후 1개월부터 종료일 이후 12개월 이내 신청","src":"고용보험법 제70조"},{"t":"육아휴직 급여 제한: 육아휴직 중 이직하면 이직한 때부터 지급하지 않음. 중 취업한 기간 지급하지 않음. 부정 수령 시 지급 제한","src":"고용보험법 제73조"},{"t":"출산전후휴가 급여 등: 출산전후휴가·유산사산휴가·배우자 출산휴가·난임치료휴가·배우자 유산사산휴가를 받은 피보험자 중 휴가 종료일 이전 피보험 단위기간 합산 180일 이상인 경우 지급","src":"고용보험법 제75조"}]},{"머리":"기금·불복·시효","줄":[{"t":"고용보험기금: 고용노동부장관이 설치하고 관리·운용한다(기획재정부장관 아님). 보험료 징수금 적립금 기금운용 수익금 등으로 조성","src":"고용보험법 제78조 제79조 | 기출 2022-19, 2024-20"},{"t":"기금 용도: 고용안정·직업능력개발 사업 경비 / 실업급여 지급 / 국민연금 보험료의 지원 / 육아휴직 급여 및 출산전후휴가 급여등 지급 / 보험료의 반환 / 일시 차입금의 상환금과 이자 / 법에 따른 업무를 대행하거나 위탁받은 자에 대한 출연금 / 그 밖에 대통령령 정하는 경비","src":"고용보험법 제80조 | 기출 2026-19"},{"t":"심사와 재심사: 피보험자격 취득·상실 확인 / 실업급여 / 육아휴직 급여 등에 이의가 있으면 고용보험심사관에게 심사를 청구하고 안 날부터 90일 이내. 결정에 이의가 있으면 고용보험심사위원회에 결정을 안 날부터 90일 이내 재심사 청구","src":"고용보험법 제87조"},{"t":"고용보험심사위원회: 고용노동부에 두며 근로자·사용자 대표 각 1명 이상을 포함한 15명 이내. 재심사 청구를 받으면 50일 이내 재결","src":"고용보험법 제99조"},{"t":"소멸시효 3년: 지원금을 지급받거나 반환받을 권리 / 취업촉진 수당을 지급받거나 반환받을 권리 / 구직급여를 반환받을 권리 / 육아휴직 급여 등을 반환받을 권리","src":"고용보험법 제107조"}]},{"머리":"산재보험법 총칙","줄":[{"t":"산업재해보상보험법 목적: 업무상 재해를 신속하고 공정하게 보상하고 재해근로자의 재활 및 사회 복귀를 촉진하며 재해 예방과 복지 증진 사업을 시행해 근로자 보호에 이바지","src":"산업재해보상보험법 제1조"},{"t":"보험사업은 고용노동부장관이 관장하고 보험연도는 정부의 회계연도에 따른다","src":"산업재해보상보험법 제2조"},{"t":"국가의 부담: 회계연도마다 예산 범위에서 보험사업의 사무 집행에 드는 비용을 일반회계에서 부담하여야 한다. 사업비용의 일부는 지원할 수 있다","src":"산업재해보상보험법 제3조"},{"t":"업무상의 재해: 업무상의 사유에 따른 근로자의 부상·질병·장해 또는 사망","src":"산업재해보상보험법 제5조제1호 | 기출 2022-18"},{"t":"유족: 사망한 사람의 배우자(사실상 혼인 관계 포함)·자녀·부모·손자녀·조부모 또는 형제자매","src":"산업재해보상보험법 제5조제3호"},{"t":"치유: 부상 또는 질병이 완치되거나 치료 효과를 더 이상 기대할 수 없고 증상이 고정된 상태","src":"산업재해보상보험법 제5조제4호"},{"t":"장해: 부상 또는 질병이 치유되었으나 정신적 또는 육체적 훼손으로 노동능력이 상실되거나 감소된 상태","src":"산업재해보상보험법 제5조제5호"},{"t":"중증요양상태: 업무상 부상·질병으로 노동능력이 상실·감소된 상태로서 치유되지 아니한 상태","src":"산업재해보상보험법 제5조제6호"},{"t":"진폐: 분진을 흡입하여 폐에 생기는 섬유증식성 변화를 주된 증상으로 하는 질병","src":"산업재해보상보험법 제5조제7호"},{"t":"출퇴근: 취업과 관련하여 주거와 취업장소 사이의 이동 또는 한 취업장소에서 다른 취업장소로의 이동","src":"산업재해보상보험법 제5조제8호 | 기출 2022-18"},{"t":"적용 범위: 근로자를 사용하는 모든 사업 또는 사업장(위험률·규모·장소 등을 고려해 대통령령으로 정하는 사업 제외)","src":"산업재해보상보험법 제6조"},{"t":"산업재해보상보험및예방심의위원회: 고용노동부에 두며 근로자·사용자·공익 대표를 같은 수로 구성","src":"산업재해보상보험법 제8조"},{"t":"근로복지공단: 고용노동부장관의 위탁을 받아 설립(법인). 보험급여의 결정과 지급 / 보험료 징수 / 심사 청구 심리·결정 / 산재보험 시설 설치·운영 / 진료·요양 및 재활 / 재활보조기구 연구개발 / 건강진단 등 예방 사업 / 복지 증진 사업","src":"산업재해보상보험법 제10조 제11조 | 기출 2022-18"}]},{"머리":"업무상 재해 인정","줄":[{"t":"업무상 사고: 근로계약에 따른 업무나 그에 따르는 행위를 하던 중 발생한 사고 / 사업주가 제공한 시설물 등을 이용하던 중 결함이나 관리소홀로 발생한 사고 / 사업주가 주관하거나 지시에 따라 참여한 행사나 준비 중 발생한 사고 / 휴게시간 중 사업주의 지배관리하에 있다고 볼 수 있는 행위로 발생한 사고 / 그 밖에 업무와 관련하여 발생한 사고","src":"산업재해보상보험법 제37조제1항제1호 | 기출 2021-14"},{"t":"업무상 질병: 물리적 인자 화학물질 분진 병원체 신체에 부담을 주는 업무 등 건강장해 요인에 노출되어 발생한 질병 / 업무상 부상이 원인이 된 질병 / 직장 내 괴롭힘 고객의 폭언 등 업무상 정신적 스트레스가 원인인 질병 / 그 밖에 업무와 관련하여 발생한 질병","src":"산업재해보상보험법 제37조제1항제2호"},{"t":"출퇴근 재해: 사업주가 제공한 교통수단 등 사업주의 지배관리하에서 출퇴근하는 중 사고 / 그 밖에 통상적인 경로와 방법으로 출퇴근하는 중 사고(비통상적인 경로와 방법으로 출퇴근 중 발생한 사고는 업무상 사고가 아님)","src":"산업재해보상보험법 제37조제1항제3호 | 기출 2021-14"},{"t":"근로자의 고의·자해행위나 범죄행위 또는 그것이 원인이 되어 발생한 재해는 업무상 재해로 보지 않는다(정상적 인식능력이 뚜렷하게 낮아진 상태의 행위는 예외). 업무와 재해 사이에 상당인과관계가 없으면 업무상 재해가 아니다","src":"산업재해보상보험법 제37조제1항 제2항"},{"t":"출퇴근 경로 일탈·중단 시 그 중 사고와 후 이동 중 사고는 출퇴근 재해가 아니다(일상생활에 필요한 행위로 대통령령 사유가 있으면 출퇴근 재해)","src":"산업재해보상보험법 제37조제3항"},{"t":"업무상질병판정위원회: 업무상 질병의 인정 여부를 심의하기 위해 공단 소속 기관에 둔다","src":"산업재해보상보험법 제38조"}]},{"머리":"보험급여 종류","줄":[{"t":"보험급여 8가지: ① 요양급여 ② 휴업급여 ③ 장해급여 ④ 간병급여 ⑤ 유족급여 ⑥ 상병보상연금 ⑦ 장례비 ⑧ 직업재활급여 (예방·재활급여와 실업급여는 보험급여가 아님)","src":"산업재해보상보험법 제36조제1항 | 기출 2022-18, 2025-23"},{"t":"진폐에 따른 보험급여: 요양급여 / 간병급여 / 장례비 / 직업재활급여 / 진폐보상연금 / 진폐유족연금","src":"산업재해보상보험법 제36조제1항"},{"t":"건강손상자녀의 보험급여: 요양급여 / 장해급여 / 간병급여 / 장례비 / 직업재활급여","src":"산업재해보상보험법 제36조제1항"},{"t":"보험급여는 수급권자의 청구에 따라 지급한다","src":"산업재해보상보험법 제36조제2항"},{"t":"최고 보상기준 금액은 상용근로자 5명 이상 사업체 전체 근로자 임금 평균액의 1.8배. 최저 보상기준 금액은 2분의 1(최저임금액 미만이면 최저임금액). 휴업급여·상병보상연금에는 최저 보상기준 금액을 적용하지 않는다","src":"산업재해보상보험법 제36조제7항"}]},{"머리":"요양급여·휴업급여","줄":[{"t":"요양급여: 근로자가 업무상 사유로 부상을 당하거나 질병에 걸린 경우에 지급. 산재보험 의료기관에서 요양하고 부득이하면 요양비로 갈음. 3일 이내 요양으로 치유되면 지급하지 않는다","src":"산업재해보상보험법 제40조 | 기출 2022-18"},{"t":"요양급여 범위 8가지: 진찰 및 검사 / 약제·진료재료와 의지·보조기 지급 / 처치·수술·그 밖의 치료 / 재활치료 / 입원 / 간호 및 간병 / 이송 / 그 밖에 고용노동부령 사항","src":"산업재해보상보험법 제40조제4항"},{"t":"상급종합병원 요양은 응급환자 등 부득이한 경우 외에는 상급종합병원에서 요양할 필요가 있다는 의학적 소견이 필요","src":"산업재해보상보험법 제40조제6항"},{"t":"휴업급여: 요양으로 취업하지 못한 기간에 1일당 평균임금의 100분의 70. 취업하지 못한 기간이 3일 이내이면 지급하지 않는다","src":"산업재해보상보험법 제52조"},{"t":"저소득 근로자 휴업급여: 1일당 지급액이 최저 보상기준 금액의 100분의 80 이하이면 평균임금의 100분의 90(상한 최저 보상기준 금액의 100분의 80). 최저임금액 미만이면 최저임금액","src":"산업재해보상보험법 제54조"}]},{"머리":"장해·간병·유족·상병보상연금·장례비","줄":[{"t":"장해급여: 업무상 사유로 부상·질병에 걸려 치유된 후 장해가 있는 경우. 장해등급에 따라 장해보상연금 또는 장해보상일시금(수급권자 선택). 노동력 완전상실 등급은 연금 지급 / 외국 거주 외국인은 일시금","src":"산업재해보상보험법 제57조"},{"t":"장해보상연금은 신청하면 최초 1년분 또는 2년분의 2분의 1을 미리 지급할 수 있다(100분의 5 범위 이자 공제)","src":"산업재해보상보험법 제57조제4항"},{"t":"간병급여: 요양급여를 받은 사람 중 치유 후 의학적으로 상시 또는 수시로 간병이 필요하여 실제로 간병을 받는 사람에게 지급","src":"산업재해보상보험법 제61조"},{"t":"유족급여: 근로자가 업무상 사유로 사망한 경우 유족에게 지급. 유족보상연금 또는 유족보상일시금(연금 수급 자격자가 없을 때)","src":"산업재해보상보험법 제62조 | 기출 2023-19"},{"t":"유족급여 일시금 선택: 연금 수급 자격자가 원하면 일시금의 100분의 50을 일시금으로 받고 연금은 100분의 50 감액. 연금 수급자격 상실 시 이미 지급한 연금액을 평균임금으로 나눈 일수가 1,300일에 못 미치면 차액을 일시금으로 지급","src":"산업재해보상보험법 제62조제3항·제4항"},{"t":"유족보상연금 수급자격자: 근로자 사망 당시 생계를 같이 하던 유족(외국 거주 외국인 제외) 중 배우자 + 부모·조부모 각 60세 이상 / 자녀 25세 미만 / 손자녀 25세 미만 / 형제자매 19세 미만 또는 60세 이상 / 장애인으로서 고용노동부령 장애 정도 해당자. 사망 당시 태아였던 자녀가 출생하면 포함","src":"산업재해보상보험법 제63조제1항·제2항 | 기출 2023-19"},{"t":"유족보상연금 수급 권리 순위: 배우자 → 자녀 → 부모 → 손자녀 → 조부모 → 형제자매","src":"산업재해보상보험법 제63조제3항 | 기출 2023-19"},{"t":"생계를 같이 하던 유족은 주민등록상 세대를 같이하고 동거한 유족이 대표적이며 학업·취업 등으로 주민등록을 달리하거나 동거하지 않아도 생계를 유지했다면 포함될 수 있다(판단 기준은 대통령령)","src":"산업재해보상보험법 제63조제1항 | 기출 2023-19 | 보충(시행령 원문 미확인)"},{"t":"유족보상연금 자격 상실: 사망 / 사망 근로자의 배우자 재혼(사실혼 포함) / 친족 관계 종료 / 자녀·손자녀 25세 도달 / 형제자매 19세 도달 / 장애 상태 해소 / 국적 상실 후 외국 거주·출국. 3개월 이상 행방불명이면 지급 정지. 자격 상실 시 같은 순위자 → 다음 순위자로 이전","src":"산업재해보상보험법 제64조"},{"t":"수급권자인 유족 순위(일시금 등): 생계를 같이한 배우자·자녀·부모·손자녀·조부모 → 생계를 같이하지 않던 그들 또는 생계를 같이한 형제자매 → 형제자매. 같은 순위가 2명 이상이면 똑같이 나눔. 근로자가 유언으로 수급 유족을 지정하면 그에 따름","src":"산업재해보상보험법 제65조"},{"t":"유족보상연금 수급권자가 2명 이상일 때 그 중 1명을 대표자로 선임할 수 있다","src":"산업재해보상보험법 시행령 | 기출 2023-19 | 보충(시행령 원문 미확인)"},{"t":"상병보상연금: 요양을 시작한 지 2년이 지난 날 이후 ① 부상·질병이 치유되지 않은 상태 ② 중증요양상태등급 기준 해당 ③ 요양으로 취업하지 못한 상태가 계속되면 휴업급여 대신 지급","src":"산업재해보상보험법 제66조 | 기출 2022-18"},{"t":"장례비: 업무상 사유로 사망한 경우 평균임금의 120일분을 장례를 지낸 유족에게 지급(고시 최고·최저 금액 범위). 유족이 없으면 실제 장례를 지낸 사람에게 실비","src":"산업재해보상보험법 제71조"},{"t":"직업재활급여: 장해급여자 중 훈련대상자의 직업훈련 비용 및 직업훈련수당 / 업무상 재해 발생 당시 사업에 복귀한 장해급여자에 대해 사업주가 고용 유지·직장적응훈련·재활운동을 실시할 때 지급하는 직장복귀지원금·직장적응훈련비·재활운동비","src":"산업재해보상보험법 제72조"},{"t":"합병증 등 예방관리: 치유된 사람 중 재요양 사유 발생 우려자에게 예방에 필요한 조치를 받도록 할 수 있다","src":"산업재해보상보험법 제77조"},{"t":"장해특별급여·유족특별급여: 보험가입자의 고의 또는 과실로 발생한 재해에서 수급권자가 민법상 손해배상 청구에 갈음하여 청구하면 지급. 근로자와 보험가입자 사이 합의가 있어야 하며 지급 후 동일 사유로 손해배상 청구 불가. 공단이 급여액 모두를 보험가입자에게서 징수","src":"산업재해보상보험법 제78조 제79조"},{"t":"보험급여 지급 제한: 요양 지시 위반으로 상태 악화·치유 방해 / 장해보상연금·진폐보상연금 수급권자가 재판정 전 고의로 장해 상태를 악화","src":"산업재해보상보험법 제83조"},{"t":"수급권 보호: 보험급여를 받을 권리는 퇴직하여도 소멸하지 않는다. 양도·압류·담보 제공을 할 수 없다","src":"산업재해보상보험법 제88조"}]},{"머리":"기금·불복·시효","줄":[{"t":"산업재해보상보험및예방기금: 고용노동부장관이 설치. 재원은 보험료 기금운용 수익금 적립금 결산상 잉여금 출연금·기부금 차입금 등","src":"산업재해보상보험법 제95조"},{"t":"심사 청구: 공단의 보험급여 결정 등에 불복하면 보험급여 결정 등을 한 공단 소속 기관을 거쳐 공단에 결정을 안 날부터 90일 이내 청구. 행정심판법에 따른 행정심판은 제기할 수 없다","src":"산업재해보상보험법 제103조"},{"t":"재심사 청구: 심사 청구 결정에 불복하면 고용노동부 산업재해보상보험재심사위원회(위원장 포함 90명 이내)에 결정을 안 날부터 90일 이내. 판정위원회 심의를 거친 결정은 심사 청구 없이 곧바로 재심사 청구 가능","src":"산업재해보상보험법 제106조 제107조"},{"t":"시효: 보험급여를 받을 권리 3년 / 장해급여 유족급여 장례비 진폐보상연금 진폐유족연금은 5년. 산재보험 의료기관·약국·보험가입자·국민건강보험공단 등의 권리도 3년","src":"산업재해보상보험법 제112조"}]},{"머리":"노인장기요양보험법 총칙","줄":[{"t":"노인장기요양보험법 목적: 고령이나 노인성 질병으로 일상생활을 혼자 수행하기 어려운 노인등에게 신체활동·가사활동 지원 등 장기요양급여를 제공해 노후의 건강증진 및 생활안정을 도모하고 가족의 부담을 덜어 국민의 삶의 질을 향상","src":"노인장기요양보험법 제1조"},{"t":"노인등: 65세 이상의 노인 또는 65세 미만으로 치매·뇌혈관성질환 등 대통령령이 정하는 노인성 질병을 가진 자 (60세 이상이라는 선지는 오답)","src":"노인장기요양보험법 제2조제1호 | 기출 2022-20, 2024-18"},{"t":"장기요양급여: 6개월 이상 동안 혼자서 일상생활을 수행하기 어렵다고 인정되는 자에게 신체활동·가사활동 지원 또는 간병 등의 서비스나 이에 갈음하는 현금 등 (1개월 이상은 오답)","src":"노인장기요양보험법 제2조제2호 | 기출 2022-20, 2025-25"},{"t":"장기요양사업: 장기요양보험료·국가 및 지방자치단체 부담금 등을 재원으로 노인등에게 장기요양급여를 제공하는 사업","src":"노인장기요양보험법 제2조제3호"},{"t":"장기요양기관: 지정을 받아 장기요양급여를 제공하는 기관. 장기요양요원: 기관에 소속되어 신체활동·가사활동 지원 등을 수행하는 자","src":"노인장기요양보험법 제2조제4호·제5호"},{"t":"기본원칙: 노인등이 자신의 의사와 능력에 따라 최대한 자립적으로 일상생활을 수행할 수 있도록 제공 / 심신상태·생활환경·욕구·선택을 종합 고려해 적정하게 제공 / 가족과 함께 생활하며 가정에서 받는 재가급여를 우선 제공 / 의료서비스와 연계","src":"노인장기요양보험법 제3조 | 기출 2024-18"},{"t":"국가 및 지방자치단체의 책무: 노인성질환예방사업 실시 / 적정한 수의 장기요양기관 확충과 설립 지원 / 국·공립 기관 확충 노력 / 장기요양요원 처우 개선 노력","src":"노인장기요양보험법 제4조"},{"t":"장기요양기본계획: 보건복지부장관이 5년 단위로 수립·시행. 연도별 급여 대상인원 및 재원조달 계획 / 장기요양기관·전문인력 관리 방안 / 장기요양요원 처우 / 그 밖의 사항. 지방자치단체의 장은 세부시행계획 수립","src":"노인장기요양보험법 제6조"},{"t":"실태조사: 보건복지부장관이 3년마다 정기적으로 실시하고 결과를 공표","src":"노인장기요양보험법 제6조의2"},{"t":"장기요양보험사업은 보건복지부장관이 관장하고 보험자는 국민건강보험공단. 가입자는 국민건강보험법상 가입자","src":"노인장기요양보험법 제7조 | 기출 2022-20, 2024-18"},{"t":"장기요양보험료는 건강보험료와 통합 징수(구분하여 고지)하고 각각 독립회계로 관리. 보험료율은 장기요양위원회 심의를 거쳐 대통령령으로 정함","src":"노인장기요양보험법 제8조 제9조"}]},{"머리":"인정 절차","줄":[{"t":"신청 자격: 노인등으로서 장기요양보험가입자 또는 피부양자 / 의료급여수급권자","src":"노인장기요양보험법 제12조"},{"t":"신청: 공단에 장기요양인정신청서에 의사 또는 한의사의 의사소견서를 첨부하여 제출(소견서는 등급판정위원회 자료 제출 전까지 제출 가능. 거동이 현저히 불편한 자 등은 생략 가능). 장기요양기관이 수급자를 대리하여 신청하는 것은 아님","src":"노인장기요양보험법 제13조 | 기출 2025-25"},{"t":"신청 대리: 가족·친족·이해관계인 / 사회복지전담공무원 / 치매안심센터의 장(치매환자) / 시장·군수·구청장이 지정하는 자","src":"노인장기요양보험법 제22조 | 기출 2025-25"},{"t":"조사: 공단이 신청서를 접수하면 소속 직원으로 하여금 신청인의 심신상태와 필요한 급여 종류·내용 등을 조사하게 하여야 한다. 2명 이상이 조사하도록 노력","src":"노인장기요양보험법 제14조 | 기출 2025-25"},{"t":"등급판정: 등급판정위원회가 신청자격을 충족하고 6개월 이상 혼자 일상생활을 수행하기 어렵다고 인정하는 경우 등급판정기준에 따라 수급자로 판정","src":"노인장기요양보험법 제15조제2항 | 기출 2025-25"},{"t":"등급판정 기간: 신청서 제출일부터 30일 이내에 완료. 정밀조사 필요 등 부득이한 경우 30일 이내 연장 가능","src":"노인장기요양보험법 제16조"},{"t":"장기요양인정서: 등급판정위원회가 심의를 완료하면 공단이 지체 없이 장기요양등급 / 급여의 종류 및 내용 등을 포함한 인정서를 작성해 수급자에게 송부하고 월 한도액 범위 안에서 개인별장기요양이용계획서를 함께 송부","src":"노인장기요양보험법 제17조 | 기출 2025-25"},{"t":"인정 유효기간: 최소 1년 이상으로 대통령령으로 정한다. 갱신은 유효기간 만료 전 30일까지 신청 완료","src":"노인장기요양보험법 제19조 제20조"},{"t":"등급 등 변경: 수급자는 장기요양등급·급여의 종류 또는 내용을 변경하려면 공단에 변경신청을 하여야 한다","src":"노인장기요양보험법 제21조 | 기출 2024-18"}]},{"머리":"장기요양급여의 종류","줄":[{"t":"급여의 종류 3가지: 재가급여 / 시설급여 / 특별현금급여","src":"노인장기요양보험법 제23조제1항 | 기출 2022-20, 2024-18, 2026-18"},{"t":"재가급여 6가지: ① 방문요양 ② 방문목욕 ③ 방문간호 ④ 주·야간보호 ⑤ 단기보호 ⑥ 기타재가급여(일상생활·신체활동 지원 및 인지기능 유지·향상에 필요한 용구 제공이나 가정 방문 재활 지원 등) (특별현금급여는 재가급여가 아님)","src":"노인장기요양보험법 제23조제1항제1호 | 기출 2022-20, 2024-18, 2026-18"},{"t":"방문요양: 장기요양요원이 가정 등을 방문해 신체활동 및 가사활동 등을 지원 / 방문목욕: 목욕설비를 갖춘 장비로 방문해 목욕 제공 / 방문간호: 간호사 등이 방문간호지시서에 따라 간호 진료 보조 요양 상담 구강위생 등 제공","src":"노인장기요양보험법 제23조제1항제1호가목~다목 | 기출 2026-18"},{"t":"주·야간보호: 수급자를 하루 중 일정 시간 기관에 보호하며 신체활동 지원과 심신기능 유지·향상 교육·훈련 제공. 단기보호: 보건복지부령 범위에서 일정 기간 기관에 보호(둘 다 재가급여이고 시설급여가 아님)","src":"노인장기요양보험법 제23조제1항제1호라목·마목 | 기출 2026-18"},{"t":"시설급여: 장기요양기관에 장기간 입소한 수급자에게 신체활동 지원 및 심신기능 유지·향상 교육·훈련 등을 제공","src":"노인장기요양보험법 제23조제1항제2호"},{"t":"특별현금급여 3가지: 가족요양비 / 특례요양비 / 요양병원간병비","src":"노인장기요양보험법 제23조제1항제3호 | 기출 2026-18"},{"t":"가족요양비: 도서·벽지 등 기관 부족 지역 거주자 / 천재지변 등으로 기관 이용이 어려운 자 / 신체·정신·성격 등 대통령령 사유로 가족 등으로부터 요양을 받아야 하는 자가 가족 등에게서 방문요양에 상당한 급여를 받은 때 지급","src":"노인장기요양보험법 제24조"},{"t":"특례요양비: 장기요양기관이 아닌 노인요양시설 등에서 재가·시설급여에 상당한 급여를 받은 경우 비용의 일부 지급. 요양병원간병비: 수급자가 요양병원에 입원한 때 장기요양 비용의 일부 지급","src":"노인장기요양보험법 제25조 제26조"},{"t":"통합재가서비스: 장기요양기관은 방문요양·방문목욕·방문간호·주야간보호·단기보호 전부 또는 일부를 통합해 제공할 수 있다","src":"노인장기요양보험법 제23조제3항"},{"t":"급여 제공: 수급자는 장기요양인정서와 개인별장기요양이용계획서가 도달한 날부터 급여를 받을 수 있다. 월 한도액 범위 안에서 제공(등급과 급여 종류 고려)","src":"노인장기요양보험법 제27조 제28조"},{"t":"급여 제한: 정당한 사유 없이 조사·자료제출 요구에 응하지 않으면 전부 또는 일부 제공하지 않을 수 있다. 기관의 부정 청구에 가담한 경우 중단하거나 1년의 범위에서 횟수·기간 제한","src":"노인장기요양보험법 제29조"},{"t":"본인부담금: 급여를 받는 자는 비용의 일부를 본인이 부담(특별현금급여 제외). 의료급여법상 기초생활 의료급여 수급자는 부담하지 않음. 월 한도액 초과 급여 / 인정서와 다르게 선택한 차액 / 급여 범위 밖 급여는 전부 본인 부담. 의료급여 수급권자·저소득자 등은 100분의 60 범위 감경","src":"노인장기요양보험법 제40조"}]},{"머리":"장기요양기관·요원","줄":[{"t":"장기요양기관 지정: 재가급여 또는 시설급여를 제공하려는 자는 시설·인력을 갖춰 소재지 관할 시장·군수·구청장의 지정을 받아야 한다. 지정 유효기간은 6년","src":"노인장기요양보험법 제31조 제32조의3"},{"t":"장기요양기관 의무: 급여 제공 거부 금지(정원 여유 없음 등 정당한 사유 예외) / 제공 기준에 따른 제공 / 명세서 교부 / 자료 기록·관리 / 영리 목적 본인부담금 면제·감경 금지 / 영리 목적 수급자 소개·알선·유인 금지","src":"노인장기요양보험법 제35조"},{"t":"지정 취소 또는 6개월 범위 업무정지: 거짓 부정 지정(필요적 취소) / 급여외행위 제공 / 지정기준 부적합 / 급여 거부 / 본인부담금 면제·감경 / 수급자 소개·알선 / 1년 이상 무신고 휴업 / 거짓 급여비용 청구 / 종사자의 수급자 폭행·성희롱·방임·금품 유용·정서적 학대 / 업무정지 중 급여 제공(필요적 취소) 등","src":"노인장기요양보험법 제37조"},{"t":"지정취소 후 3년이 지나지 않거나 업무정지 중인 자는 장기요양기관으로 지정받을 수 없다","src":"노인장기요양보험법 제37조제8항"},{"t":"급여비용 청구: 장기요양기관은 재가·시설급여를 제공한 경우 공단에 장기요양급여비용을 청구하여야 한다(시·도지사 아님). 공단이 심사 후 공단부담금 지급","src":"노인장기요양보험법 제38조 | 기출 2022-20"},{"t":"장기요양요원지원센터: 국가와 지방자치단체가 설치·운영할 수 있다. 업무는 요원의 권리 침해에 관한 상담 및 지원 / 역량강화 교육지원 / 건강검진 등 건강관리 사업 / 그 밖의 대통령령 사항","src":"노인장기요양보험법 제47조의2 | 기출 2023-23"},{"t":"부당이득 징수: 공단은 부정 등으로 급여를 받은 자 급여비용을 받은 자에게 징수. 구상권: 제3자의 행위로 급여한 경우 비용 한도에서 손해배상 청구","src":"노인장기요양보험법 제43조 제44조"}]},{"머리":"위원회·공단·불복·국고","줄":[{"t":"장기요양위원회: 보건복지부장관 소속. 심의 사항은 보험료율 / 가족요양비·특례요양비·요양병원간병비 지급기준 / 재가 및 시설 급여비용 / 그 밖의 주요 사항. 위원장 1인 부위원장 1인 포함 16~22인. 위원장은 보건복지부차관. 임기 3년","src":"노인장기요양보험법 제45조 제46조 | 기출 2023-23"},{"t":"관리운영기관은 공단. 공단 업무는 자격관리 / 보험료 부과·징수 / 신청인 조사 / 등급판정위원회 운영 및 등급 판정 / 인정서 작성 / 급여 관리 및 평가 / 정보 제공·상담 / 급여비용 심사·지급 / 부당이득금 부과·징수 / 노인성질환예방사업 등","src":"노인장기요양보험법 제48조"},{"t":"등급판정위원회: 공단에 두고 시·군·구 단위로 설치. 위원장 포함 15인. 시장·군수·구청장이 추천한 위원 7인과 의사·한의사 1인 이상 포함. 임기 3년 한 차례 연임 가능. 과반수 출석 개의 출석위원 과반수 찬성 의결","src":"노인장기요양보험법 제52조 제53조 | 기출 2023-23"},{"t":"장기요양급여심사위원회: 공단에 두며 위원장 포함 10명 이하","src":"노인장기요양보험법 제53조의2"},{"t":"심사청구: 공단 처분을 안 날부터 90일 이내 문서로 하고 처분이 있은 날부터 180일 경과 시 제기 불가. 장기요양심사위원회는 공단에 두며 위원장 포함 50명 이내","src":"노인장기요양보험법 제55조"},{"t":"재심사청구: 결정통지를 받은 날부터 90일 이내 보건복지부장관 소속 장기요양재심사위원회(위원장 포함 20인 이내 공무원 아닌 위원이 과반수)","src":"노인장기요양보험법 제56조"},{"t":"국가의 부담: 매년 예산 범위에서 장기요양보험료 예상수입액의 100분의 20에 상당하는 금액을 공단에 지원. 의료급여수급권자의 급여비용 등과 관리운영비는 국가와 지방자치단체가 전액 부담","src":"노인장기요양보험법 제58조"},{"t":"수급권 보호: 장기요양급여를 받을 권리는 양도 압류 담보 제공할 수 없다","src":"노인장기요양보험법 제66조"}]},{"머리":"국민연금 연금액 산정·환수·반납","줄":[{"t":"기본연금액: (균등부분 A값 3년 평균 + 소득비례부분 B값)을 합한 금액 x 1천분의 1천290. 가입기간이 20년을 초과하면 초과 1년마다 1천분의 50을 더한다","src":"국민연금법 제51조제1항"},{"t":"균등부분: 연금 수급 3년 전·2년 전·전년도 평균소득월액을 물가변동률로 환산해 합산하고 3으로 나눈 금액. 소득비례부분: 가입 중 매년 기준소득월액을 재평가율로 현재가치 환산해 합산한 뒤 총 가입기간으로 나눈 금액","src":"국민연금법 제51조제1항제1호·제2호"},{"t":"추가 산입 기간의 기준소득월액: 연금보험료를 내지 않은 사용자 공제 기간(2분의 1 산입) 및 군 복무 크레딧은 2분의 1 / 출산 크레딧은 균등부분 금액","src":"국민연금법 제51조제1항제2호가목~다목"},{"t":"연금액은 매년 전국소비자물가변동률에 따라 조정(국민연금심의위원회 심의)하고 적용기간은 해당 연도 1월부터 12월까지","src":"국민연금법 제51조제2항·제3항"},{"t":"부양가족연금액: 배우자 연 15만원 / 19세 미만이거나 장애상태인 자녀 연 10만원 / 60세 이상이거나 장애상태인 부모 연 10만원 (수급권자에 의하여 생계를 유지하는 자)","src":"국민연금법 제52조제1항"},{"t":"부양가족연금 제외: 연금 수급권자·퇴직연금등수급권자·직역연금 유족연금 수급권자. 2명 이상 수급권자의 계산 대상이 될 수 없다. 사망 / 생계유지 종료 / 이혼 / 자녀 양자·파양 / 자녀 19세 도달 / 장애 해소 시 제외","src":"국민연금법 제52조제3항~제5항"},{"t":"장애상태: 장애등급 1급 또는 2급에 해당하는 상태이거나 장애인복지법상 장애의 정도가 심한 장애인으로 대통령령이 정하는 상태","src":"국민연금법 제52조의2"},{"t":"급여 환수: 거짓·부정 수령 / 신고의무자의 신고 불이행 또는 지연 / 사망 추정 후 생존 확인 / 상속권 상실 유족 지급 / 그 밖의 잘못 지급은 환수하여야 한다. 일부 경우 이자 가산","src":"국민연금법 제57조"},{"t":"반납금: 반환일시금을 받은 자가 다시 가입자가 되면 지급받은 반환일시금에 이자를 더한 금액을 공단에 낼 수 있고 납부하면 그에 상응하는 기간을 가입기간에 넣어 계산","src":"국민연금법 제78조"},{"t":"진단: 공단은 장애에 따른 수급권자나 부양가족연금 계산 대상자에게 지정 의사의 진단을 요구하거나 소속 직원으로 장애 상태를 확인하게 할 수 있다","src":"국민연금법 제120조"}]}],"함정":[{"x":"재가급여에는 방문요양, 방문목욕, 특별현금급여가 포함된다.","o":"특별현금급여는 재가급여가 아니라 별도 종류.","src":"노인장기요양보험법 제23조제1항 | 기출 2024-18"},{"x":"장기요양기관은 수급자에게 재가급여 또는 시설급여를 제공한 경우 시·도지사에게 장기요양급여비용을 청구하여야 한다.","o":"공단에 청구한다.","src":"노인장기요양보험법 제38조제1항 | 기출 2022-20"},{"x":"국민연금사업은 기획재정부장관이 맡아 주관한다.","o":"보건복지부장관이 맡아 주관한다.","src":"국민연금법 제2조 | 기출 2024-19"},{"x":"“수급권자”란 이 법에 따른 급여를 받을 권리를 말한다.","o":"급여를 받을 권리는 수급권. 수급권자는 수급권을 가진 자.","src":"국민연금법 제3조제1항제14호·제15호 | 기출 2024-19"},{"x":"국내에 거주하는 국민으로서 18세 이상 65세 미만인 자는 국민연금 가입 대상이 된다.","o":"18세 이상 60세 미만. 65세까지는 임의계속가입자.","src":"국민연금법 제6조 제13조 | 기출 2024-19"},{"x":"「국민연금법」을 적용할 때 배우자에는 사실상의 혼인관계에 있는 자는 포함되지 않는다.","o":"사실상의 혼인관계에 있는 자를 포함한다.","src":"국민연금법 제3조제2항 | 기출 2024-19"},{"x":"가입자의 자격을 상실한 후 다시 그 자격을 취득한 자에 대하여는 전후의 가입기간을 합산한다.","o":"출제 오답으로 분류됐으나 현행 제20조제1항은 전후 가입기간을 합산한다고 정한다(기출 원문 문구 재확인 필요).","src":"국민연금법 제20조제1항 | 기출 2026-16"},{"x":"건강보험 가입자는 국내에 거주하지 아니하게 된 날에 그 자격을 잃는다.","o":"국내에 거주하지 아니하게 된 날의 다음 날에 잃는다.","src":"국민건강보험법 제10조제1항제3호 | 기출 2024-17"},{"x":"회계연도마다 예산안을 독자적으로 편성하고 지출할 수 있다.","o":"출제 오답(바른 문장 미확인). 공단의 회계와 예산은 법 제35조·제36조에 정해져 있다.","src":"보충(원문 미확인) | 기출 2025-22"},{"x":"고용보험기금은 기획재정부장관이 관리ㆍ운용한다.","o":"고용노동부장관이 관리·운용한다.","src":"고용보험법 제79조제1항 | 기출 2022-19, 2024-20"},{"x":"지방자치단체는 매년 보험사업에 드는 비용의 일부를 일반회계에서 부담하여야 한다.","o":"국가가 매년 보험사업에 드는 비용의 일부를 일반회계에서 부담하여야 한다.","src":"고용보험법 제5조제1항 | 기출 2024-20"},{"x":"취업촉진 수당의 종류로는 구직급여, 직업능력개발 수당 등이 있다.","o":"취업촉진 수당은 조기재취업 수당 직업능력개발 수당 광역 구직활동비 이주비. 구직급여는 실업급여의 다른 종류.","src":"고용보험법 제37조 | 기출 2022-19"},{"x":"“실업”이란 근로의 의사와 능력이 없어 취업하지 못한 상태에 있는 것을 말한다.","o":"근로의 의사와 능력이 있음에도 취업하지 못한 상태.","src":"고용보험법 제2조제3호 | 기출 2022-19"},{"x":"“실업의 인정”이란 근로의 의사와 능력이 있음에도 불구하고 취업하지 못한 상태에 있는 것을 말한다.","o":"그것은 실업의 정의. 실업의 인정은 직업안정기관의 장이 수급자격자가 실업 상태에서 적극적으로 직업을 구하고 있다고 인정하는 것.","src":"고용보험법 제2조제3호·제4호 | 기출 2024-20"},{"x":"“일용근로자”란 6개월 미만 동안 고용되는 사람을 말한다.","o":"1개월 미만.","src":"고용보험법 제2조제6호 | 기출 2022-19"},{"x":"“일용근로자”란 3개월 미만 동안 고용되는 사람을 말한다.","o":"1개월 미만.","src":"고용보험법 제2조제6호 | 기출 2024-20"},{"x":"실업급여를 받을 권리는 양도 또는 압류하거나 담보로 제공할 수 있다.","o":"양도·압류·담보 제공을 할 수 없다.","src":"고용보험법 제38조제1항 | 기출 2024-20"},{"x":"구직급여를 지급받으려는 사람은 이직 후 지체없이 직업안정기관에 출석하여 실업을 신고하여야 한다.","o":"이 문장은 현행 제42조제1항과 같다. 출제 시 틀린 선지로 분류된 것은 원문 재확인 필요.","src":"고용보험법 제42조제1항 | 기출 2021-17"},{"x":"구직급여의 수급 요건으로서 기준기간은 피보험자의 이직일 이전 36개월로 한다.","o":"이직일 이전 18개월.","src":"고용보험법 제40조제2항 | 기출 2021-17"},{"x":"실업 신고일부터 계산하기 시작하여 14일간의 대기기간 중에는 구직급여를 지급하지 않는다.","o":"7일간.","src":"고용보험법 제49조제1항 | 기출 2021-17"},{"x":"이주비는 구직급여의 종류에 해당한다.","o":"이주비는 취업촉진 수당의 종류.","src":"고용보험법 제37조제2항 | 기출 2021-17"},{"x":"보험급여에는 간병급여, 상병보상연금, 실업급여 등이 있다.","o":"실업급여는 고용보험법상 급여. 산재보험 보험급여는 요양급여 휴업급여 장해급여 간병급여 유족급여 상병보상연금 장례비 직업재활급여.","src":"산업재해보상보험법 제36조제1항 | 기출 2022-18"},{"x":"근로자의 소득으로 생계의 전부를 유지하고 있던 유족으로서 학업으로 주민등록을 달리하였거나 동거하지 않았던 사람은 유족에 해당되지 않는다.","o":"생계를 유지하던 유족은 주민등록을 달리하거나 동거하지 않았어도 해당할 수 있다.","src":"산업재해보상보험법 시행령 | 기출 2023-19 | 보충(시행령 원문 미확인)"},{"x":"업무상의 사유로 근로자가 장착한 의족이 파손된 경우는 「산업재해보상보험법」상 요양급여의 대상인 근로자의 부상에 포함되지 않는다.","o":"의족 파손도 요양급여 대상인 부상에 포함된다(대법원 판례 취지).","src":"보충(판례 추정) | 기출 2023-22"},{"x":"“장기요양급여”란 장기요양등급판정 결과에 따라 1개월 이상 동안 혼자서 일상생활을 수행하기 어렵다고 인정되는 자에게 신체활동ㆍ가사활동의 지원 또는 간병 등의 서비스를 말한다.","o":"6개월 이상.","src":"노인장기요양보험법 제2조제2호 | 기출 2022-20"},{"x":"“노인등”이란 60세 이상의 노인 또는 60세 미만의 자로서 치매ㆍ뇌혈관성질환 등 대통령령으로 정하는 노인성 질병을 가진 자를 말한다.","o":"65세 이상, 65세 미만.","src":"노인장기요양보험법 제2조제1호 | 기출 2022-20"},{"x":"재가급여에는 방문요양, 방문목욕, 특별현금급여가 있다.","o":"특별현금급여는 별도 급여 종류. 재가급여는 방문요양 방문목욕 방문간호 주야간보호 단기보호 기타재가급여.","src":"노인장기요양보험법 제23조 | 기출 2022-20, 2024-18"},{"x":"단기보호는 시설급여이다.","o":"단기보호는 재가급여이다.","src":"노인장기요양보험법 제23조제1항제1호마목 | 기출 2026-18"},{"x":"주ㆍ야간보호는 시설급여이다.","o":"재가급여이다.","src":"노인장기요양보험법 제23조제1항제1호라목 | 기출 2026-18"},{"x":"방문간호는 시설급여이다.","o":"재가급여이다.","src":"노인장기요양보험법 제23조제1항제1호다목 | 기출 2026-18"},{"x":"부양가족이 있으면 장기요양급여는 지급되지 않는다.","o":"부양가족 유무와 관계없이 등급판정위원회 판정에 따라 급여를 받는다.","src":"노인장기요양보험법 제15조 | 기출 2026-18"},{"x":"장기요양기관은 수급자를 대리하여 장기요양인정을 신청한다.","o":"신청 대리는 가족·친족·이해관계인 사회복지전담공무원 치매안심센터장 지정인이 한다.","src":"노인장기요양보험법 제22조 | 기출 2025-25"}]},"#8":{"묶음":[{"머리":"아동복지법 총칙·계획·기구","줄":[{"t":"아동복지법 목적: 아동이 건강하게 출생하여 행복하고 안전하게 자랄 수 있도록 아동의 복지를 보장","src":"아동복지법 제1조"},{"t":"기본 이념: 어떠한 차별도 받지 않고 자람 / 안전한 가정환경에서 행복하게 자람 / 아동에 관한 모든 활동에서 아동의 이익이 최우선 고려 / 보호와 지원을 받을 권리","src":"아동복지법 제2조"},{"t":"아동: 18세 미만인 사람","src":"아동복지법 제3조제1호 | 기출 2025-16 비교"},{"t":"보호자: 친권자 후견인 아동을 보호·양육·교육하거나 그러한 의무가 있는 자 또는 업무·고용 등의 관계로 사실상 아동을 보호·감독하는 자","src":"아동복지법 제3조제3호 | 기출 2026-20"},{"t":"보호대상아동: 보호자가 없거나 보호자로부터 이탈된 아동 또는 보호자가 학대하는 등 양육하기에 적당하지 않거나 양육 능력이 없는 경우의 아동","src":"아동복지법 제3조제4호"},{"t":"지원대상아동: 조화롭고 건강한 성장에 필요한 기초 조건이 갖추어지지 않아 사회적·경제적·정서적 지원이 필요한 아동","src":"아동복지법 제3조제5호"},{"t":"가정위탁: 성범죄 가정폭력 아동학대 정신질환 등의 전력이 없는 보건복지부령 기준 적합 가정에 보호대상아동을 일정 기간 위탁","src":"아동복지법 제3조제6호"},{"t":"아동학대관련범죄: 아동학대범죄의 처벌 등에 관한 특례법상 아동학대범죄 + 아동에 대한 형법 살인의 죄(제250조~제255조)","src":"아동복지법 제3조제7호의2 | 기출 2021-19"},{"t":"어린이날은 매년 5월 5일 / 어린이주간은 5월 1일~7일. 아동학대예방의 날은 매년 11월 19일(예방주간은 그날부터 1주일)","src":"아동복지법 제6조 제23조 | 기출 2021-11"},{"t":"아동정책기본계획: 보건복지부장관이 5년마다 수립하고 미리 관계 중앙행정기관의 장과 협의. 아동정책조정위원회 심의를 거쳐 확정","src":"아동복지법 제7조 | 기출 2024-23"},{"t":"연도별 시행계획: 보건복지부장관 관계 중앙행정기관의 장 시·도지사가 매년 수립·시행","src":"아동복지법 제8조"},{"t":"아동정책조정위원회: 국무총리 소속(보건복지부장관 소속 아님). 위원장 포함 25명 이내이고 위원장은 국무총리. 당연직 위원은 교육부 법무부 행정안전부 문화체육관광부 산업통상부 보건복지부 고용노동부 성평등가족부 기획예산처 장관 + 위촉위원 15명 이내","src":"아동복지법 제10조 | 기출 2022-24, 2024-23"},{"t":"국가아동권리보장원: 국가가 설립. 아동정책 자료 개발·분석 / 기본계획 수립 및 시행계획 평가 지원 / 위원회 운영 지원 / 아동보호서비스 기술지원 / 아동학대예방사업 / 가정위탁사업 활성화 / 지역 아동복지 지원 / 입양 체계 구축·운영(국내입양에 관한 특별법 및 국제입양에 관한 법률) / 아동 관련 조사·통계·교육·홍보","src":"아동복지법 제10조의2 | 기출 2022-24, 2026-20"},{"t":"아동종합실태조사: 보건복지부장관이 3년마다 아동의 양육·생활환경 언어·인지 발달 정서적·신체적 건강 아동안전 아동학대 등을 조사해 공표","src":"아동복지법 제11조"},{"t":"아동복지심의위원회: 시·도지사와 시장·군수·구청장이 소속으로 둔다. 심의 사항은 시행계획 / 보호조치 / 퇴소조치 / 보호기간 연장 및 종료 / 재보호조치 / 친권상실 선고 청구 / 후견인 선임·변경 청구 / 지원대상아동 선정 / 그 밖의 사항","src":"아동복지법 제12조"},{"t":"아동복지전담공무원: 시·도 및 시·군·구에 둘 수 있다. 사회복지사 자격을 가진 사람","src":"아동복지법 제13조"},{"t":"아동위원: 시·군·구에 둔다(시·도 아님). 명예직이되 수당을 지급할 수 있다","src":"아동복지법 제14조 | 기출 2022-24, 2024-23, 2026-20"}]},{"머리":"보호조치·자립지원","줄":[{"t":"보호조치 6가지: ① 상담·지도 ② 친족 가정에서 보호·양육 ③ 적합한 유형의 가정에 위탁 ④ 아동복지시설 입소 ⑤ 전문치료기관 또는 요양소 입원·입소 ⑥ 입양과 관련하여 필요한 조치. 시·도지사 또는 시장·군수·구청장이 한다","src":"아동복지법 제15조제1항"},{"t":"보호조치 ③~⑥을 하기 전에 상담 건강검진 심리검사 가정환경 조사를 실시하고 아동이 충분히 이해하도록 설명. 아동의 의사를 존중하고 보호자 의견을 들어야 한다(아동학대행위자 등은 제외)","src":"아동복지법 제15조제3항·제5항"},{"t":"일시보호조치: 아동일시보호시설 학대피해아동쉼터 위탁가정 등에서 보호","src":"아동복지법 제15조제6항"},{"t":"양육상황 점검: 보호조치(②~⑥) 중인 보호대상아동의 양육상황을 매년 점검(분기별·3년마다 아님)","src":"아동복지법 제15조의3 | 기출 2022-24, 2024-23"},{"t":"퇴소조치: 보호조치 중 아동이 18세에 달하였거나 보호 목적이 달성되었다고 인정되면 보호조치를 종료하거나 퇴소시켜야 한다","src":"아동복지법 제16조"},{"t":"보호기간 연장: 18세에 달한 보호대상아동이 연장 의사가 있으면 25세에 달할 때까지 연장하여야 한다. 대학 이하 재학 중이거나 직업 교육·훈련 중이면 추가 연장 가능","src":"아동복지법 제16조의3 | 기출 2026-20"},{"t":"금지행위: 아동 매매 / 음란한 행위 시킴·매개 및 성적 학대 / 신체적 학대 / 정서적 학대 / 유기·방임 / 장애 아동 공중 관람 / 구걸 시킴 / 유해 곡예 / 무권한 양육 알선 및 금품 취득 / 아동을 위한 금품 목적 외 사용","src":"아동복지법 제17조"},{"t":"아동학대 예방과 방지: 국가와 지방자치단체가 정책 수립 / 연구·교육·홍보·실태조사 / 신고체제 / 피해아동 보호·치료 / 가정 지원. 시·도지사 또는 시장·군수·구청장이 아동학대 신고접수·현장조사·응급보호 업무를 수행","src":"아동복지법 제22조"},{"t":"자립지원 대상: 가정위탁보호 중인 사람 / 아동복지시설 보호 중인 사람 / 보호조치 종료·퇴소 후 5년이 지나지 않은 사람 / 18세 전 종료·퇴소자로 보건복지부장관이 인정한 사람","src":"아동복지법 제38조제2항"},{"t":"자립지원 조치: 교육·주거·생활·의료 지원 / 자립정착금·자립수당 / 진로·직업 상담 및 취업 지원 / 자산형성지원 / 실태조사·연구 / 사후관리체계 / 심리 상담","src":"아동복지법 제38조제1항"},{"t":"자립지원계획: 보장원장 가정위탁지원센터장 아동복지시설의 장이 보호하고 있는 15세 이상의 아동을 대상으로 매년 개별 자립지원계획을 수립","src":"아동복지법 제39조 | 기출 2022-24"},{"t":"다함께돌봄센터: 초등학교 정규교육 이외의 시간 방과 후 돌봄서비스(아동 안전 보호 / 균형 급식·간식 / 등·하교 전후·야간·긴급 돌봄 / 체험활동 프로그램 연계 / 돌봄 상담·정보 제공·서비스 연계)","src":"아동복지법 제44조의2 | 기출 2023-24"},{"t":"보호가 필요한 아동을 발견하고 양육환경을 개선하기 위해 이용할 수 있는 자료와 정보에는 요양급여 실시 기록 / 영유아건강검진 실시 기록 / 학교생활기록 정보 / 단전 가구정보 등이 포함된다","src":"보충(원문 미확인) | 기출 2023-25"}]},{"머리":"아동보호전문기관·가정위탁·시설","줄":[{"t":"아동보호전문기관: 시·도 및 시·군·구에 1개소 이상 두며 지방자치단체가 설치(통합 설치 가능). 비영리법인에 위탁 운영 가능","src":"아동복지법 제45조"},{"t":"아동보호전문기관 업무: 피해아동·가족·아동학대행위자·사례관리대상자를 위한 상담·치료 및 교육 / 아동학대예방 교육 및 홍보 / 피해아동 가정의 사후관리 / 그 밖의 대통령령 사항. 아동학대 신고접수·현장조사·응급보호는 시·도지사 또는 시장·군수·구청장의 업무","src":"아동복지법 제46조제2항 제22조제3항 | 기출 2025-13"},{"t":"아동권리보장원의 장은 아동학대가 종료된 이후에도 아동학대의 재발 여부를 확인하여야 한다","src":"보충(원문 미확인) | 기출 2022-24"},{"t":"가정위탁지원센터: 시·도 및 시·군·구에 둔다. 가정위탁사업 홍보 및 가정 발굴 / 조사·상담 / 교육 / 사례관리 / 친부모 가정 복귀 지원 / 자립계획 및 사례 관리 / 정보 제공","src":"아동복지법 제48조 제49조"},{"t":"아동복지시설 설치: 국가 또는 지방자치단체는 설치할 수 있고 그 외의 자는 관할 시장·군수·구청장에게 신고한 후 설치","src":"아동복지법 제50조 | 기출 2026-20"},{"t":"아동복지시설 종류 14가지: 아동양육시설 / 아동일시보호시설 / 아동보호치료시설 / 공동생활가정 / 자립지원시설 / 아동상담소 / 아동전용시설 / 지역아동센터 / 협동돌봄센터 / 아동보호전문기관 / 가정위탁지원센터 / 보장원 / 자립지원전담기관 / 학대피해아동쉼터 (다함께돌봄센터는 별도 규정)","src":"아동복지법 제52조제1항"},{"t":"아동전용시설: 국가와 지방자치단체는 아동이 항상 이용할 수 있는 아동전용시설을 설치하도록 노력하여야 한다","src":"아동복지법 제53조 | 기출 2024-23"},{"t":"학대피해아동쉼터: 시·도지사 및 시장·군수·구청장이 설치·운영할 수 있다. 피해아동 보호·숙식 제공 / 심리상담·치료 / 학습·정서 지원","src":"아동복지법 제53조의2"},{"t":"시설 개선·사업정지(6개월 이내)·위탁취소·시설장 교체·폐쇄 명령: 설치기준 미달 / 법인 설립허가 취소 / 운영 불필요 / 아동학대행위 확인 / 거짓 경비 지원 / 정지기간 중 사업 / 법 위반","src":"아동복지법 제56조"},{"t":"이 법에 따라 지급된 금품과 받을 권리는 압류하지 못한다","src":"아동복지법 제64조"}]},{"머리":"노인복지법","줄":[{"t":"노인복지법 목적: 노인의 질환을 사전예방·조기발견하고 질환상태에 맞는 치료·요양으로 심신의 건강을 유지하며 노후 생활안정에 필요한 조치로 보건복지증진에 기여","src":"노인복지법 제1조"},{"t":"부양의무자: 배우자(사실상 혼인관계 포함)와 직계비속 및 그 배우자(사실상 혼인관계 포함)","src":"노인복지법 제1조의2제1호 | 기출 2026-23"},{"t":"보호자: 부양의무자 또는 업무·고용 등의 관계로 사실상 노인을 보호하는 자","src":"노인복지법 제1조의2제2호"},{"t":"노인학대: 노인에 대하여 신체적·정신적·정서적·성적 폭력 및 경제적 착취 또는 가혹행위를 하거나 유기 또는 방임을 하는 것","src":"노인복지법 제1조의2제4호 | 기출 2021-19"},{"t":"기본이념: 노인은 존경받으며 건전하고 안정된 생활을 보장받는다 / 능력에 따라 적당한 일에 종사하고 사회적 활동에 참여할 기회를 보장받는다 / 심신의 건강을 유지하고 지식과 경험을 활용해 사회 발전에 기여하도록 노력한다","src":"노인복지법 제2조"},{"t":"노인실태조사: 보건복지부장관이 3년마다 실시하고 공표","src":"노인복지법 제5조"},{"t":"노인의 날은 매년 10월 2일 / 경로의 달은 10월 / 어버이날은 5월 8일 / 노인학대예방의 날은 6월 15일","src":"노인복지법 제6조 | 기출 2021-11"},{"t":"노인복지상담원: 특별자치도와 시·군·구에 둔다","src":"노인복지법 제7조 | 기출 2026-23"},{"t":"노인사회참여 지원: 노인의 지역봉사 활동기회 확대 / 적합 직종 개발 / 근로능력 있는 노인에게 일할 기회 우선 제공 노력. 노인지역봉사기관 노인취업알선기관 등 지원","src":"노인복지법 제23조"},{"t":"지역봉사지도원: 국가 또는 지방자치단체가 사회적 신망과 경험이 있는 노인으로 지역봉사를 희망하는 사람을 위촉할 수 있다","src":"노인복지법 제24조 | 기출 2026-23"},{"t":"건강진단: 국가 또는 지방자치단체는 65세 이상에 대하여 건강진단과 보건교육을 실시할 수 있다","src":"노인복지법 제27조 | 기출 2022-22"},{"t":"홀로 사는 노인: 방문요양·돌봄 서비스와 안전확인 등 보호조치를 취하여야 한다. 독거노인종합지원센터는 보건복지부장관이 설치·운영할 수 있다(노인복지시설 종류가 아님)","src":"노인복지법 제27조의2 제27조의3 | 기출 2021-20, 2026-23"},{"t":"상담·입소 조치: 65세 이상의 자 또는 보호자 상담·지도 / 거택 보호가 곤란한 자의 노인주거복지시설·재가노인복지시설 입소 / 항상 보호가 필요하고 경제적 이유로 곤란한 자의 노인의료복지시설 입소. 65세 미만도 노쇠현상이 현저하면 가능","src":"노인복지법 제28조"},{"t":"노인복지시설 7가지: ① 노인주거복지시설 ② 노인의료복지시설 ③ 노인여가복지시설 ④ 재가노인복지시설 ⑤ 노인보호전문기관 ⑥ 노인일자리지원기관 ⑦ 학대피해노인 전용쉼터 (독거노인종합지원센터는 제외)","src":"노인복지법 제31조 | 기출 2021-20"},{"t":"노인주거복지시설: 양로시설 / 노인공동생활가정 / 노인복지주택","src":"노인복지법 제32조제1항 | 기출 2022-22"},{"t":"노인복지주택 입소자격: 60세 이상의 노인(65세 아님). 배우자와 부양 책임이 있는 24세 미만 자녀·손자녀 또는 장애로 부양하는 24세 이상 자녀·손자녀는 함께 입소 가능","src":"노인복지법 제33조의2 | 기출 2022-22, 2024-22"},{"t":"노인의료복지시설: 노인요양시설 / 노인요양공동생활가정 (노인요양공동생활가정은 노인의료복지시설이고 주거복지시설이 아님)","src":"노인복지법 제34조 | 기출 2024-22"},{"t":"노인여가복지시설: 노인복지관 / 경로당 / 노인교실. 노인복지관은 여가복지시설","src":"노인복지법 제36조 | 기출 2026-23"},{"t":"재가노인복지시설 서비스: 방문요양서비스 / 주·야간보호서비스 / 단기보호서비스 / 방문 목욕서비스 / 그 밖의 서비스","src":"노인복지법 제38조"},{"t":"요양보호사: 노인복지시설 설치·운영자가 두어야 하며 요양보호사교육기관 교육과정을 마치고 시·도지사의 자격시험에 합격하여야 한다. 자격증은 시·도지사가 교부(보건복지부장관 아님). 대여·알선 금지","src":"노인복지법 제39조의2 | 기출 2022-22"},{"t":"요양보호사 자격 취소(시·도지사): 결격사유 해당 / 금지행위 위반 처벌 / 거짓·부정 취득은 반드시 취소. 영리 목적 불필요 요양서비스 알선·유인 / 자격증 대여·양도·위조는 임의 취소(청문 필수)","src":"노인복지법 제39조의14 | 기출 2022-22"},{"t":"요양보호사 결격: 정신질환자(전문의가 적합하다고 인정한 사람 제외) / 마약·대마·향정신성의약품 중독자 / 피성년후견인 / 금고 이상 실형 집행 종료·면제 전 / 집행유예 기간 중 / 법원 판결로 자격 정지·상실 / 취소 후 1년 미경과","src":"노인복지법 제39조의13"},{"t":"긴급전화: 국가 및 지방자치단체는 노인학대를 예방하고 수시로 신고를 받을 수 있도록 긴급전화를 설치하여야 한다","src":"노인복지법 제39조의4"},{"t":"중앙노인보호전문기관: 국가가 지역 간 연계체계를 구축하고 노인학대를 예방하기 위해 설치·운영하여야 한다. 노인인권보호 정책제안 / 연구·프로그램 개발 / 홍보·교육자료 / 실적 취합 / 지역기관 관리·업무지원 / 상담원 심화교육 / 협력체계 / 중앙노인학대사례판정위원회 운영","src":"노인복지법 제39조의5제1항 | 기출 2024-22"},{"t":"지역노인보호전문기관: 시·도에 둔다(시·군·구 아님). 신고전화 운영 및 사례접수 / 현장조사 / 피해노인·학대자 상담 / 법률 지원 요청 / 기록 보관 / 일반인 예방교육 / 재발방지 교육 / 지역노인학대사례판정위원회 운영","src":"노인복지법 제39조의5제2항 | 기출 2024-22"},{"t":"노인학대 신고: 누구든지 노인학대를 알게 된 때에는 노인보호전문기관 또는 수사기관에 신고할 수 있다. 직무상 65세 이상 노인에 대한 학대를 알게 된 신고의무자(의료인 사회복지사 노인복지시설 종사자 장기요양기관 종사자 119구급대원 가정폭력상담소 종사자 등 16종)는 즉시 신고하여야 한다","src":"노인복지법 제39조의6 | 기출 2022-22"},{"t":"노인 금지행위: 폭행·상해 / 성폭행·성희롱 / 유기·방임 / 구걸을 하게 하거나 노인을 이용한 구걸 / 노인을 위한 금품 목적 외 사용 / 정서적 학대","src":"노인복지법 제39조의9 | 기출 2025-14"},{"t":"학대피해노인 전용쉼터: 국가와 지방자치단체가 설치·운영할 수 있고 노인보호전문기관에 운영을 위탁할 수 있다","src":"노인복지법 제39조의19"},{"t":"노인일자리전담기관: 노인인력개발기관 노인취업알선기관 노인일자리지원기관","src":"노인 일자리 및 사회활동 지원에 관한 법률 | 기출 2022-22 | 보충(원문 미확인)"},{"t":"비용: 건강진단·상담·입소 조치 소요비용과 노인복지시설 설치·운영 비용은 국가 또는 지방자치단체가 부담하며 시설 운영 비용은 보조할 수 있다","src":"노인복지법 제45조 제47조"}]},{"머리":"장애인복지법","줄":[{"t":"장애인복지법 목적: 장애인의 인간다운 삶과 권리보장을 위한 국가와 지방자치단체 등의 책임을 명백히 하고 의료·교육·직업재활·생활환경 개선 등 사업을 정해 사회통합에 이바지","src":"장애인복지법 제1조"},{"t":"장애인: 신체적·정신적 장애로 오랫동안 일상생활이나 사회생활에서 상당한 제약을 받는 자. 이 법 적용 장애인은 대통령령이 정하는 종류·기준에 해당하는 자","src":"장애인복지법 제2조제1항·제2항"},{"t":"신체적 장애: 주요 외부 신체 기능의 장애 내부기관의 장애 등 / 정신적 장애: 발달장애 또는 정신 질환으로 발생하는 장애","src":"장애인복지법 제2조제2항"},{"t":"장애인학대: 신체적·정신적·정서적·언어적·성적 폭력이나 가혹행위 경제적 착취 유기 또는 방임 (경제적 착취도 학대에 포함)","src":"장애인복지법 제2조제3항 | 기출 2021-19"},{"t":"기본이념: 장애인의 완전한 사회 참여와 평등을 통하여 사회통합을 이루는 데에 있다","src":"장애인복지법 제3조 | 기출 2026-22"},{"t":"장애인의 권리: 인간으로서 존엄과 가치 존중 / 모든 분야의 활동 참여 / 장애인 관련 정책결정과정에 우선적으로 참여","src":"장애인복지법 제4조"},{"t":"장애인정책종합계획: 보건복지부장관이 관계 중앙행정기관의 장과 협의하여 5년마다 수립·시행(3년 아님). 장애인정책조정위원회 심의를 미리 거쳐야 하고 추진성과를 매년 평가","src":"장애인복지법 제10조의2 | 기출 2022-23"},{"t":"장애인정책조정위원회: 국무총리 소속(보건복지부장관 소속 아님)","src":"장애인복지법 제11조 | 기출 2025-15"},{"t":"지방장애인복지위원회: 지방자치단체에 두고 사업의 기획·조사·실시 사항을 심의","src":"장애인복지법 제13조"},{"t":"장애인의 날은 매년 4월 20일(5월 20일 아님) / 장애인 주간은 그날부터 1주간","src":"장애인복지법 제14조 | 기출 2021-11, 2025-15"},{"t":"장애실태조사: 보건복지부장관이 3년마다 실시(5년 아님)","src":"장애인복지법 제31조 | 기출 2022-23, 2025-15"},{"t":"장애인 등록: 장애인·법정대리인 등이 시장·군수·구청장에게 등록하면 장애인등록증을 교부. 등록증은 양도·대여 금지","src":"장애인복지법 제32조"},{"t":"재외동포 및 외국인 중 국내거소신고자 / 재외국민 주민등록자 / 영주 체류자격 외국인등록자 / 결혼이민자 / 난민인정자는 장애인 등록 가능 (난민인정자 포함)","src":"장애인복지법 제32조의2 | 기출 2022-23, 2025-15"},{"t":"등록 취소: 사망 / 기준에 맞지 않게 됨 / 정당한 사유 없이 장애 진단 명령 불이행 / 취소 신청","src":"장애인복지법 제32조의3"},{"t":"장애인복지상담원: 시·군·구에 둔다","src":"장애인복지법 제33조"},{"t":"장애수당: 장애 정도와 경제적 수준을 고려해 지급할 수 있다. 기초생활보장법상 생계급여·의료급여 수급 장애인에게는 반드시 지급. 장애인연금법상 중증장애인에게는 지급하지 않는다","src":"장애인복지법 제49조 | 기출 2025-15"},{"t":"장애아동수당과 보호수당: 국가와 지방자치단체가 지급할 수 있다. 생계·의료급여 수급 장애아동에게는 장애아동수당을 지급하여야 한다","src":"장애인복지법 제50조"},{"t":"활동지원급여: 국가와 지방자치단체가 일상·사회생활을 위해 지원할 수 있다","src":"장애인복지법 제55조"},{"t":"장애인복지시설 5가지: 장애인 거주시설 / 장애인 지역사회재활시설 / 장애인 자립생활지원시설 / 장애인 직업재활시설 / 장애인 의료재활시설 / 그 밖의 대통령령 시설","src":"장애인복지법 제58조 | 기출 2023-24"},{"t":"시설 설치: 국가와 지방자치단체는 설치 가능. 그 외의 자는 시설 소재지 관할 시장·군수·구청장에게 신고. 폐쇄명령 후 1년 미경과자는 신고 불가. 장애인 거주시설 정원은 30명 초과 불가(예외 있음)","src":"장애인복지법 제59조"},{"t":"장애인학대 신고: 누구든지 신고할 수 있다. 직무상 알게 된 신고의무자(사회복지전담공무원 사회복지시설 종사자 활동지원인력 의료인 119구급대원 어린이집 교직원 학교 종사자 등 25종)는 지체 없이 장애인권익옹호기관 또는 수사기관에 신고","src":"장애인복지법 제59조의4"},{"t":"장애인권익옹호기관: 중앙은 국가가 설치·운영하여야 하고 지역은 시·도에 1개소 이상 둔다. 지역기관은 학대 신고접수·현장조사·응급보호 / 상담·사후관리 / 예방교육·홍보 / 장애인학대사례판정위원회 운영","src":"장애인복지법 제59조의11"},{"t":"피해장애인 쉼터: 시·도지사(특별시장·광역시장·특별자치시장·도지사·특별자치도지사)가 설치·운영할 수 있다(보건복지부장관 아님)","src":"장애인복지법 제59조의13 | 기출 2022-23"},{"t":"장애인 거주시설의 서비스 최저기준: 보건복지부장관이 마련하여야 하고 시설 운영자는 최저기준 이상으로 유지하여야 한다(시설의 장이 마련하는 것 아님)","src":"장애인복지법 제60조의3 | 기출 2022-23"},{"t":"시설 개선·사업정지·시설장 교체·폐쇄 명령: 장애인복지실시기관이 시설기준 미달 / 보고 거부 / 법인 설립허가 취소 / 회계 부정·인권침해 / 운영 불필요 / 성폭력·학대관련범죄 발생 / 법 위반 시","src":"장애인복지법 제62조"},{"t":"장애인 지원 시책: 장애발생 예방 / 의료와 재활치료 / 사회적응 훈련 / 교육 / 직업 / 정보 접근 / 편의시설 / 경제적 부담 경감(세제 조치 이용료 감면) 등","src":"장애인복지법 제17조~제30조"},{"t":"이의신청: 복지조치가 있음을 안 날부터 90일 이내 문서로 장애인복지실시기관에 하고 기관은 30일 이내 심사·결정. 불복 시 행정심판","src":"장애인복지법 제84조"},{"t":"이 법에 따라 장애인에게 지급되는 금품은 압류할 수 없다","src":"장애인복지법 제82조"}]}],"함정":[{"x":"시ㆍ도지사 또는 시장ㆍ군수ㆍ구청장은 보호조치 중인 보호대상아동의 양육상황을 분기별로 점검하여야 한다.","o":"매년 점검한다.","src":"아동복지법 제15조의3 | 기출 2024-23"},{"x":"시장ㆍ군수ㆍ구청장은 보호조치 중인 보호대상아동의 양육상황을 3년마다 점검하여야 한다.","o":"매년 점검한다.","src":"아동복지법 제15조의3 | 기출 2022-24"},{"x":"시ㆍ군ㆍ구에 두는 아동위원은 명예직으로 수당을 지급할 수 없다.","o":"아동위원은 명예직이되 수당을 지급할 수 있다.","src":"아동복지법 제14조제4항 | 기출 2022-24"},{"x":"특별시ㆍ광역시ㆍ도ㆍ특별자치도에 아동위원을 두고 아동위원에 대하여는 수당이 지급될 수 있다.","o":"아동위원은 시·군·구에 둔다.","src":"아동복지법 제14조제1항 | 기출 2026-20"},{"x":"보건복지부장관 소속으로 아동정책조정위원회를 둔다.","o":"국무총리 소속이다.","src":"아동복지법 제10조제1항 | 기출 2022-24"},{"x":"아동복지시설의 장은 보호하고 있는 12세 이상의 아동을 대상으로 자립지원계획을 수립하여야 한다.","o":"15세 이상의 아동.","src":"아동복지법 제39조제1항 | 기출 2022-24"},{"x":"노인복지주택에 입소할 수 있는 자는 65세 이상의 노인으로 한다.","o":"60세 이상의 노인.","src":"노인복지법 제33조의2제1항 | 기출 2024-22"},{"x":"보건복지부장관은 요양보호사가 거짓으로 자격증을 취득한 경우 그 자격을 취소하여야 한다.","o":"요양보호사 자격은 시·도지사가 취소한다.","src":"노인복지법 제39조의14 | 기출 2022-22"},{"x":"노인취업알선기관은 지역사회 등에서 노인에 의한 재화의 생산ㆍ판매 등을 직접 담당하는 기관이다.","o":"출제 오답(바른 문장 미확인). 노인취업알선기관은 노인의 취업을 알선하는 기관.","src":"보충(원문 미확인) | 기출 2024-22"},{"x":"노인요양공동생활가정은 노인들에게 일상생활에 필요한 편의를 제공함을 목적으로 하는 노인주거복지시설이다.","o":"노인요양공동생활가정은 노인의료복지시설. 주거복지시설인 노인공동생활가정과 구분.","src":"노인복지법 제32조 제34조 | 기출 2024-22"},{"x":"지역노인보호전문기관은 시ㆍ군ㆍ구에 둔다.","o":"시·도에 둔다.","src":"노인복지법 제39조의5제2항 | 기출 2024-22"},{"x":"보건복지부장관은 독거노인종합지원센터를 설치ㆍ운영할 수 있다.","o":"현행 제27조의3은 보건복지부장관의 설치·운영을 인정한다. 2026 기출에서 오답으로 분류된 이유는 원문 재확인 필요.","src":"노인복지법 제27조의3 | 기출 2026-23"},{"x":"장애인복지법상 장애인 학대에 경제적 착취는 포함되지 않는다.","o":"경제적 착취도 장애인학대에 포함된다.","src":"장애인복지법 제2조제3항 | 기출 2021-19"},{"x":"보건복지부장관은 3년마다 장애인정책종합계획을 수립ㆍ시행하여야 한다.","o":"5년마다.","src":"장애인복지법 제10조의2 | 기출 2022-23"},{"x":"보건복지부장관은 5년마다 장애실태조사를 실시하여야 한다.","o":"3년마다.","src":"장애인복지법 제31조 | 기출 2022-23"},{"x":"장애실태조사는 5년마다 실시하여야 한다.","o":"3년마다.","src":"장애인복지법 제31조 | 기출 2025-15"},{"x":"보건복지부장관은 피해장애인의 임시 보호 및 사회복귀 지원을 위하여 장애인 쉼터를 설치ㆍ운영할 수 있다.","o":"시·도지사가 설치·운영할 수 있다.","src":"장애인복지법 제59조의13 | 기출 2022-23"},{"x":"장애인복지시설의 장은 장애인 거주시설에서 제공하여야 하는 서비스의 최저기준을 마련하여야 한다.","o":"보건복지부장관이 마련하여야 한다.","src":"장애인복지법 제60조의3 | 기출 2022-23"},{"x":"보건복지부장관 소속하에 장애인정책조정위원회를 둔다.","o":"국무총리 소속.","src":"장애인복지법 제11조 | 기출 2025-15"},{"x":"재외동포 및 외국인은 장애인 등록을 할 수 없다.","o":"일정 요건을 갖추면 등록할 수 있다.","src":"장애인복지법 제32조의2 | 기출 2025-15"},{"x":"장애인의 날은 매년 5월 20일이다.","o":"매년 4월 20일.","src":"장애인복지법 제14조 | 기출 2025-15"}]},"#9":{"묶음":[{"머리":"한부모가족지원법","줄":[{"t":"한부모가족지원법 목적: 한부모가족이 안정적인 가족 기능을 유지하고 자립할 수 있도록 지원해 생활 안정과 복지 증진에 이바지","src":"한부모가족지원법 제1조"},{"t":"국가 등의 책임: 한부모가족의 복지 증진 책임 / 여건 조성과 시책 수립·시행 / 편견·차별 예방과 이해 교육·홍보 / 교육부장관과 교육감은 학교에서 이해 교육 시책 수립 / 청소년 한부모가족 자립 노력 / 모든 국민은 복지 증진에 협력","src":"한부모가족지원법 제2조"},{"t":"한부모가족의 권리: 모 또는 부는 임신·출산·양육을 이유로 합리적 이유 없이 교육·고용 등에서 차별받지 않는다. 한부모가족의 모 또는 부와 아동은 한부모가족 관련 정책결정과정에 참여할 권리가 있다. 자산과 노동능력을 최대한 활용해 자립하도록 노력","src":"한부모가족지원법 제3조 | 기출 2022-21"},{"t":"모 또는 부: 아동인 자녀를 양육하는 ① 배우자와 사별·이혼하거나 유기된 자 ② 정신·신체 장애로 장기간 노동능력을 상실한 배우자를 가진 자 ③ 교정시설·치료감호시설 입소 배우자 또는 병역복무 중인 배우자를 가진 사람 ④ 미혼자(사실혼 관계에 있는 자는 제외) ⑤ 그에 준하는 자로 성평등가족부령 정하는 자","src":"한부모가족지원법 제4조제1호 | 기출 2024-24"},{"t":"청소년 한부모: 24세 이하의 모 또는 부 (18세·25세 이하라는 선지는 오답)","src":"한부모가족지원법 제4조제1호의2 | 기출 2022-21, 2024-24, 2025-16"},{"t":"모자가족은 모가 세대주(세대원을 사실상 부양하는 자 포함)인 가족 / 부자가족은 부가 세대주인 가족 / 한부모가족은 모자가족 또는 부자가족","src":"한부모가족지원법 제4조제2호~제4호"},{"t":"아동: 18세 미만(취학 중이면 22세 미만. 병역의무를 이행하고 취학 중이면 이행한 기간을 가산한 연령 미만)","src":"한부모가족지원법 제4조제5호 | 기출 2025-16"},{"t":"지원기관: 이 법에 따른 지원을 행하는 국가나 지방자치단체. 한부모가족복지단체: 복지 증진을 목적으로 설립된 기관이나 단체","src":"한부모가족지원법 제4조제6호·제7호"},{"t":"지원대상자 특례: 혼인 관계에 있지 아니한 출산 전 임신부와 출산 후 아동을 양육하지 아니하는 모는 출산지원시설을 이용할 때 지원대상자가 된다. 부모 사망·장애·장기복역·이혼 등으로 부양받을 수 없는 아동과 그 아동을 양육하는 조부 또는 조모 / 대한민국 국적 아동을 양육하는 외국인 모 또는 부로 대통령령이 정하는 사람도 지원대상자","src":"한부모가족지원법 제5조의2 | 기출 2025-16"},{"t":"실태조사: 성평등가족부장관이 3년마다 한부모가족 실태조사를 실시하고 공표 (5년마다는 오답. 2024 기출의 여성가족부는 현재 성평등가족부)","src":"한부모가족지원법 제6조 | 기출 2024-24"},{"t":"지원대상자 조사: 시장·군수·구청장이 매년 1회 이상 관할구역 지원대상자의 가족상황·생활실태 조사","src":"한부모가족지원법 제10조"},{"t":"복지 급여 신청: 지원대상자 또는 친족·이해관계인이 관할 시장·군수·구청장에게 신청하고 금융·신용·보험 정보 제공 동의 서면을 제출","src":"한부모가족지원법 제11조"},{"t":"복지 급여의 내용: 생계비 / 아동교육지원비 / 아동양육비 / 그 밖에 대통령령으로 정하는 비용 (아동수당은 포함되지 않음)","src":"한부모가족지원법 제12조제1항 | 기출 2025-16"},{"t":"다른 법령에 따라 지원을 받으면 그 범위에서 급여하지 않으나 아동양육비는 지급할 수 있다. 미혼 한부모가 5세 이하 아동을 양육하거나 34세 이하의 모 또는 부가 아동을 양육하면 추가 급여를 실시하여야 한다. 직업훈련비와 훈련기간 중 생계비는 추가 지급 가능","src":"한부모가족지원법 제12조제2항~제4항"},{"t":"복지 자금의 대여: 사업 자금 / 아동교육비 / 의료비 / 주택자금 / 그 밖에 대통령령 자금(대여할 수 있음). 아동양육비는 대여가 아니라 지급 대상","src":"한부모가족지원법 제13조 | 기출 2022-21"},{"t":"고용 촉진: 직업능력개발훈련을 실시하여야 하고 우선 고용 노력. 공공시설 매점 우선 허가 / 시설 우선이용 / 국민주택 우선 분양 노력","src":"한부모가족지원법 제14조~제16조 제18조"},{"t":"가족지원서비스: 아동의 양육·교육 / 장애인·노인·만성질환자 부양 / 가사 / 가족관계 증진 교육·상담 / 인지청구 및 자녀양육비 청구 등 법률구조 / 유전자검사비용 지원","src":"한부모가족지원법 제17조"},{"t":"청소년 한부모 학업 지원: 학적 유지 / 교육비 / 검정고시 / 평생교육시설 교육비 지원 등. 성평등가족부장관이 청소년 한부모가 학업을 계속할 수 있도록 교육부장관에게 협조를 요청하여야 한다 (교육부장관이 요청하는 것이 아님)","src":"한부모가족지원법 제17조의2 | 기출 2024-24"},{"t":"한부모가족복지시설 5가지: ① 출산지원시설(임신·출산 및 3세 미만 출산 아동 양육 주거 지원) ② 양육지원시설(6세 미만 자녀 동반) ③ 생활지원시설(18세 미만 자녀 동반) ④ 일시지원시설(배우자의 학대로 아동 양육이나 모·부 건강에 지장 우려 시 일시적 주거·생계 지원) ⑤ 한부모가족복지상담소","src":"한부모가족지원법 제19조 | 기출 2023-21"},{"t":"시설 설치: 국가나 지방자치단체가 설치할 수 있고 그 외의 자는 시장·군수·구청장에게 신고. 청소년 한부모가 입소를 요청하면 우선 입소 조치. 시설 폐지·중단·재개는 미리 신고","src":"한부모가족지원법 제20조 제21조"},{"t":"시설 폐쇄: 시설 기준 미달 / 수탁 거부 / 보고 거부 시 사업 정지·폐지 명령이나 폐쇄","src":"한부모가족지원법 제24조"},{"t":"급여 수급권: 양도·담보 제공·압류 불가. 이의가 있으면 결정 통지일부터 90일 이내 서면으로 복지실시기관에 심사청구하고 30일 이내 결정 통보","src":"한부모가족지원법 제27조 제28조"},{"t":"한부모가족의 날은 5월 10일 (9월 7일은 사회복지의 날)","src":"보충(원문 미확인) | 기출 2024-24"}]},{"머리":"다문화가족지원법","줄":[{"t":"다문화가족지원법 목적: 다문화가족 구성원이 안정적인 가족생활을 영위하고 사회구성원으로서 역할과 책임을 다하도록 하여 삶의 질 향상과 사회통합에 이바지","src":"다문화가족지원법 제1조"},{"t":"다문화가족: 결혼이민자와 국적취득자로 이루어진 가족 / 출생이 아닌 국적취득자(인지·귀화)끼리 이루어진 가족. 결혼이민자등: 결혼이민자 + 귀화허가를 받은 자","src":"다문화가족지원법 제2조"},{"t":"아동·청소년: 24세 이하인 사람","src":"다문화가족지원법 제2조제3호"},{"t":"기본계획: 성평등가족부장관이 5년마다 수립하고 관계 중앙행정기관의 장과 협의. 다문화가족정책위원회 심의 후 확정, 국회 소관 상임위원회에 보고","src":"다문화가족지원법 제3조의2"},{"t":"다문화가족정책위원회: 국무총리 소속. 위원장 포함 20명 이내이고 위원장은 국무총리","src":"다문화가족지원법 제3조의4"},{"t":"실태조사: 3년마다","src":"다문화가족지원법 제4조"},{"t":"지원 내용: 다문화 이해교육 / 생활정보 제공 및 한국어교육 / 평등한 가족관계 유지 / 가정폭력 피해자 보호·지원 / 의료 및 건강관리(산전·산후 도우미 건강검진) / 아동·청소년 보육·교육 / 다국어 서비스","src":"다문화가족지원법 제5조~제11조"},{"t":"다문화가족지원센터: 국가·지방자치단체가 설치·운영하거나 법인·단체에 위탁. 그 외의 자는 시·도지사 또는 시장·군수·구청장의 지정. 업무는 교육·상담 / 한국어교육 / 정보제공·홍보 / 서비스 연계 / 일자리 정보·알선 / 통역·번역 / 가정폭력 방지 및 피해자 연계","src":"다문화가족지원법 제12조"},{"t":"사실혼 배우자 및 자녀: 대한민국 국민과 사실혼 관계에서 출생한 자녀를 양육하는 다문화가족 구성원에게도 준용","src":"다문화가족지원법 제14조"}]},{"머리":"건강가정기본법","줄":[{"t":"가족: 혼인·혈연·입양으로 이루어진 사회의 기본단위","src":"건강가정기본법 제3조제1호 | 기출 2023-15"},{"t":"가정: 가족구성원이 생계 또는 주거를 함께 하는 생활공동체로서 부양·양육·보호·교육 등이 이루어지는 생활단위","src":"건강가정기본법 제3조제2호"},{"t":"1인가구: 1명이 단독으로 생계를 유지하고 있는 생활단위 (성인 1명 또는 그와 생계를 같이하는 미성년자녀로 구성된 생활단위는 한부모가구 설명으로 오답)","src":"건강가정기본법 제3조제2호의2 | 기출 2023-15"},{"t":"건강가정: 가족구성원의 욕구가 충족되고 인간다운 삶이 보장되는 가정 / 건강가정사업: 가정문제 예방·해결과 가정기능 강화 사업","src":"건강가정기본법 제3조제3호·제4호"},{"t":"모든 국민은 혼인과 출산의 사회적 중요성을 인식하여야 한다. 국가와 지방자치단체는 출산·육아 환경 조성을 위해 모성·부성권 보호 및 태아 건강보장 등을 적극 지원","src":"건강가정기본법 제8조 | 기출 2023-15"},{"t":"건강가정기본계획: 성평등가족부장관이 관계 중앙행정기관의 장과 협의하여 5년마다 수립하고 국무회의 심의로 확정. 1인가구 복지 증진 대책 포함","src":"건강가정기본법 제15조 | 기출 2023-15"},{"t":"가정의 달은 5월 / 가정의 날은 5월 15일","src":"건강가정기본법 제12조"},{"t":"국가는 양성이 평등한 육아휴직제 확대와 생애주기에 따른 가족구성원의 종합적인 건강증진대책을 마련하여야 한다","src":"건강가정기본법 | 기출 2023-15 | 보충(조문 원문 미확인)"}]},{"머리":"가정폭력방지 및 피해자보호 등에 관한 법률","줄":[{"t":"가정폭력방지법 목적: 가정폭력을 예방하고 피해자를 보호·지원","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제1조"},{"t":"피해자: 가정폭력으로 인하여 직접적으로 피해를 입은 자. 아동: 18세 미만","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제2조 | 기출 2025-17"},{"t":"국가 등의 책무: 신고체계 구축 / 조사·연구·교육·홍보 / 보호시설 설치·운영 / 임대주택 우선 입주권·직업훈련 등 자립·자활 지원 / 법률구조 / 협력 체계 / 법령 정비 / 종사자 신변보호 / 신변노출 방지 / 아동 상담·치료 프로그램","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제4조"},{"t":"상담소: 국가·지방자치단체가 설치·운영하고 그 외의 자는 시장·군수·구청장에게 신고. 업무는 신고·상담 / 가족 상담 / 긴급 피해자 임시 보호·인도 / 법적 자문 협조 요청 / 경찰 인도 피해자 임시 보호 / 예방 교육·홍보 / 조사·연구","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제5조 제6조"},{"t":"보호시설: 국가·지방자치단체가 설치·운영하고 사회복지법인과 그 밖의 비영리법인은 시장·군수·구청장의 인가를 받아 설치·운영할 수 있다","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제7조 | 기출 2025-17"},{"t":"보호시설 종류: 단기보호시설(6개월 범위. 3개월씩 두 차례 연장 가능) / 장기보호시설(2년 범위 자립을 위한 주거편의) / 외국인보호시설(2년) / 장애인보호시설(2년)","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제7조의2 | 기출 2025-17"},{"t":"보호시설 업무: 숙식 제공 / 상담·치료 / 의료지원 / 수사·재판 지원 / 법률구조 협조 / 자립자활교육과 취업정보 / 다른 법률에 따른 위탁 사항","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제8조"},{"t":"피해자 의사 존중: 상담소나 보호시설의 장은 피해자 등의 명시한 의사에 반하여 보호를 할 수 없다","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제9조 | 기출 2021-24"},{"t":"비밀 엄수: 긴급전화센터·상담소·보호시설의 장이나 이를 보조하는 자 또는 그 직에 있었던 자는 직무상 알게 된 비밀을 누설하여서는 아니 된다","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제16조 | 기출 2021-24"},{"t":"치료보호: 의료기관은 요청이 있으면 상담·치료 등을 실시하여야 하고 비용은 가정폭력행위자가 부담한다. 피해자가 신청하면 국가·지방자치단체가 대신 지급 후 구상","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제18조 | 기출 2021-24"},{"t":"보호시설 보호비용 지원의 방법·절차와 전담의료기관 지정 등은 성평등가족부령 및 시장·군수·구청장의 지정 사항(기출 시점에는 여성가족부령)","src":"가정폭력방지 및 피해자보호 등에 관한 법률 | 기출 2021-24 | 보충(조문 원문 미확인)"},{"t":"피해자가 동반한 아동 취학 지원: 주소지 외의 지역에서 취학할 필요가 있을 때 원활한 취학을 지원하여야 한다","src":"가정폭력방지 및 피해자보호 등에 관한 법률 | 기출 2025-17 | 보충(조문 원문 미확인)"}]},{"머리":"정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률","줄":[{"t":"정신질환자: 망상·환각·사고나 기분의 장애 등으로 독립적으로 일상생활을 영위하는 데 중대한 제약이 있는 사람","src":"정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률 제3조제1호 | 기출 2023-20"},{"t":"정신건강증진시설: 정신의료기관 / 정신요양시설 / 정신재활시설","src":"정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률 제3조제4호 | 기출 2023-20"},{"t":"정신건강복지센터: 정신건강증진시설·사회복지시설·학교·사업장과 연계해 지역사회 정신건강증진사업을 하는 국가·지방자치단체 설치 기관이나 위탁 기관","src":"정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률 제3조제3호"},{"t":"보호의무자: 민법에 따른 후견인 또는 부양의무자. 다음은 보호의무자가 될 수 없다 ① 피성년후견인 및 피한정후견인 ② 해당 정신질환자를 상대로 소송 중이거나 소송한 사실이 있는 사람과 그 배우자 ③ 미성년자 ④ 행방불명자 ⑤ 그 밖에 의무를 이행할 수 없는 사람. 순위는 후견인 → 부양의무자 (파산선고 후 복권되지 않은 사람은 현행 결격 목록에 없음)","src":"정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률 제39조 | 기출 2023-20"},{"t":"보호의무자의 의무: 적절한 치료·요양과 사회적응 훈련을 받도록 노력 / 입원 시 본인 의사 존중과 퇴원 협조 / 자해·타해 유의와 재산권 보호 / 유기 금지","src":"정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률 제40조"},{"t":"자의입원등: 정신질환자 등이 신청서를 제출해 입원등을 할 수 있고 퇴원 신청 시 지체 없이 퇴원시켜야 하며 입원일부터 2개월마다 퇴원 의사를 확인","src":"정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률 제41조"}]}],"함정":[{"x":"피해자의 의사에 반하여 피해자 상담을 할 수 있다.","o":"상담소·보호시설의 장은 피해자 등의 명시한 의사에 반하여 보호를 할 수 없다.","src":"가정폭력방지 및 피해자보호 등에 관한 법률 제9조 | 기출 2021-24"},{"x":"교육부장관은 청소년 한부모가 학업을 계속할 수 있도록 여성가족부장관에게 협조를 요청하여야 한다.","o":"성평등가족부장관이 교육부장관에게 요청한다.","src":"한부모가족지원법 제17조의2제4항 | 기출 2024-24"},{"x":"여성가족부장관은 5년마다 한부모가족에 대한 실태조사를 실시하고 그 결과를 공표하여야 한다.","o":"3년마다(소관은 성평등가족부장관).","src":"한부모가족지원법 제6조 | 기출 2024-24"},{"x":"“청소년 한부모”란 18세 이하의 모 또는 부를 말한다.","o":"24세 이하.","src":"한부모가족지원법 제4조제1호의2 | 기출 2024-24"},{"x":"한부모가족에 대한 국민의 이해와 관심을 제고하기 위하여 매년 9월 7일을 한부모가족의 날로 한다.","o":"한부모가족의 날은 5월 10일이다. 9월 7일은 사회복지의 날.","src":"보충(원문 미확인) | 기출 2024-24"},{"x":"국가나 지방자치단체는 아동양육비를 대여할 수 있다.","o":"아동양육비는 복지 급여로 지급한다. 대여 대상은 사업자금 아동교육비 의료비 주택자금 등.","src":"한부모가족지원법 제12조 제13조 | 기출 2022-21"},{"x":"보건복지부장관은 한부모가족 지원을 위하여 한부모가족 정책에 관한 기본계획을 5년마다 수립하여야 한다.","o":"한부모가족지원법의 소관 부처는 성평등가족부이며 위 기본계획 규정이 조문에 없다. 5년마다 실태조사가 아니라 3년마다 실태조사.","src":"한부모가족지원법 제6조 | 기출 2025-16"},{"x":"청소년 한부모란 25세 이하의 모 또는 부를 말한다.","o":"24세 이하.","src":"한부모가족지원법 제4조제1호의2 | 기출 2025-16"},{"x":"혼인 관계에 있지 아니한 자로서 출산 전 임신부는 출산지원시설을 이용할 때에도 이 법에 따른 지원대상자가 될 수 없다.","o":"출산지원시설을 이용할 때에는 지원대상자가 된다.","src":"한부모가족지원법 제5조의2제1항 | 기출 2025-16"},{"x":"이 법에 따른 복지 급여는 생계비, 아동수당, 아동교육비, 아동양육비이다.","o":"생계비 아동교육지원비 아동양육비 그 밖에 대통령령 비용(아동수당 아님).","src":"한부모가족지원법 제12조 | 기출 2025-16"},{"x":"“1인가구”라 함은 성인 1명 또는 그와 생계를 같이하는 미성년자녀로 구성된 생활단위를 말한다.","o":"1명이 단독으로 생계를 유지하고 있는 생활단위.","src":"건강가정기본법 제3조제2호의2 | 기출 2023-15"},{"x":"유치원의 장, 어린이집의 원장, 초ㆍ중등학교의 장은 가정폭력의 예방과 방지를 위하여 필요한 교육을 실시하고, 그 결과를 여성가족부장관에게 제출하여야 한다.","o":"출제 오답(바른 문장 미확인). 교육 실시 후 결과 제출 상대는 조문 확인 필요.","src":"보충(원문 미확인) | 기출 2025-17"}]},"#10":{"묶음":[{"머리":"사회복지공동모금회법","줄":[{"t":"사회복지공동모금회법 목적: 공동모금을 통해 국민이 사회복지를 이해하고 참여하도록 하고 자발적 성금으로 조성된 재원을 효율적이고 공정하게 관리·운용해 사회복지증진에 이바지","src":"사회복지공동모금회법 제1조"},{"t":"사회복지공동모금: 사회복지사업이나 그 밖의 사회복지활동 지원에 필요한 재원을 조성하기 위해 이 법에 따라 기부금품을 모집하는 것","src":"사회복지공동모금회법 제2조제2호"},{"t":"기본 원칙 ① 기부하는 자의 의사에 반하여 기부금품을 모집하여서는 아니 된다","src":"사회복지공동모금회법 제3조제1항 | 기출 2021-22"},{"t":"기본 원칙 ② 공동모금재원은 지역·단체·대상자 및 사업별로 복지수요가 공정하게 충족되도록 배분하고 목적과 용도에 맞게 공정하게 관리·운용","src":"사회복지공동모금회법 제3조제2항 | 기출 2021-22"},{"t":"기본 원칙 ③ 공동모금재원의 배분은 객관적인 기준에 따라 효율적으로 이루어지도록 하고 그 결과를 공개하여야 한다","src":"사회복지공동모금회법 제3조제3항 | 기출 2021-22"},{"t":"설립: 사회복지공동모금회(모금회)를 두며 사회복지법인으로 한다. 정관을 작성하여 보건복지부장관의 인가를 받아 등기함으로써 설립된다(허가 아님)","src":"사회복지공동모금회법 제4조 | 기출 2024-25, 2026-25"},{"t":"모금회의 사업: 사회복지공동모금사업 / 공동모금재원의 배분 / 운용·관리 / 조사·연구·홍보 및 교육·훈련 / 지회 운영 / 국제교류 및 협력증진 / 다른 기부금품 모집자와의 협력 / 그 밖에 목적 달성에 필요한 사업","src":"사회복지공동모금회법 제5조"},{"t":"정관 필수 기재 10가지: 목적 / 명칭 / 주된 사무소 소재지 / 사업 / 임원 및 직원 / 이사회 / 지회의 구성 및 운영 / 재산 및 회계 / 공고 / 정관 변경","src":"사회복지공동모금회법 제6조"},{"t":"임원: 회장 1명 / 부회장 3명 / 이사(회장·부회장·사무총장 포함) 15명 이상 20명 이하 / 감사 2명. 임기 3년 한 차례만 연임 가능. 이사회는 회장이 소집하고 의장","src":"사회복지공동모금회법 제7조 제8조"},{"t":"이사 선임: 경제계·언론계·법조계·의료계 종사자 / 노동계·종교계·시민단체 종사자 / 사회복지전문가가 각각 4명 이상 포함","src":"사회복지공동모금회법 제9조"},{"t":"임원 결격: 사회복지사업법 제19조 해당자 일부 / 해임 후 5년 미경과 / 사기·공갈 등 300만원 이상 벌금형 확정 후 2년 미경과","src":"사회복지공동모금회법 제11조"},{"t":"분과실행위원회: 기획·홍보·모금·배분 분과를 두고 위원장 포함 20명 이내(모금·배분분과는 각각 20명 이상). 위원 임기 2년이며 배분분과실행위원회 위원은 한 차례만 연임 가능","src":"사회복지공동모금회법 제13조 | 기출 2022-25, 2024-25, 2026-25"},{"t":"지회: 시·도 단위 사회복지공동모금지회를 둔다. 지회장은 이사회 의결을 거쳐 회장이 임명. 지회 조성 재원은 해당 시·도 배분대상자에게 배분이 원칙. 회계연도 시작 2개월 전 지회로부터 사업계획서를 받아 보건복지부장관에게 보고","src":"사회복지공동모금회법 제14조 제15조"},{"t":"재원: 사회복지공동모금 기부금품 / 법인·단체 출연 현금·물품 / 복권수익금 / 그 밖의 수입금","src":"사회복지공동모금회법 제17조"},{"t":"기부금품의 모집: 연중 모집·접수할 수 있다. 접수 사실을 장부에 기록하고 영수증 교부","src":"사회복지공동모금회법 제18조 | 기출 2024-25"},{"t":"모금창구: 언론기관을 모금창구로 지정하고 지정된 언론기관의 명의로 모금계좌를 개설할 수 있다","src":"사회복지공동모금회법 제19조 | 기출 2022-25"},{"t":"배분기준: 매년 8월 31일까지 다음 회계연도 배분기준을 정하여 공고(배분대상 / 배분한도액 / 배분신청기간·제출 장소 / 배분심사기준 / 과부족 시 조정방법 / 제출 서류 / 그 밖의 사항). 긴급 시 별도 기준으로 지원 가능","src":"사회복지공동모금회법 제20조 | 기출 2024-25, 2026-25"},{"t":"배분 절차: 배분신청서는 해당 회계연도에만 유효 → 배분분과실행위원회가 배분금액·순위·시기 심의 → 배분계획 수립(분기별 균형 배분) → 배분 종료일부터 3개월 이내 1개 이상 전국 일간신문에 결과 공고","src":"사회복지공동모금회법 제21조~제24조"},{"t":"재원 사용: 해당 회계연도 지출이 원칙이고 재난·긴급구호 대비 적립과 이사회 의결 이월 가능. 모금 및 관리·운영 비용은 직전 회계연도 모금총액의 100분의 10 범위에서 이사회 의결로 사용","src":"사회복지공동모금회법 제25조"},{"t":"사업계획 및 예산안은 회계연도 시작 1개월 전에 보건복지부장관에게 제출하고 결산서는 회계연도 종료 후 3개월 이내 제출(회계법인 감사보고서 첨부). 회계연도는 1월 1일부터 12월 31일","src":"사회복지공동모금회법 제26조 제28조"},{"t":"지정 기부: 기부자는 배분지역·배분대상자·사용 용도를 지정할 수 있고 모금회는 지정 취지에 따라 사용하여야 한다","src":"사회복지공동모금회법 제27조 | 기출 2022-25"},{"t":"국가나 지방자치단체는 모금회에 기부금품 모집에 필요한 비용과 관리·운영에 필요한 비용을 보조할 수 있다","src":"사회복지공동모금회법 | 기출 2021-22, 2022-25, 2024-25 | 보충(현행 조문 원문 미확인)"},{"t":"집중모금을 하려면 그 모집일부터 15일 전에 그 내용을 보건복지부장관에게 보고하여야 한다","src":"사회복지공동모금회법 | 기출 2026-25 | 보충(현행 조문 원문 미확인)"},{"t":"모금회가 아닌 자는 사회복지공동모금 또는 유사 명칭을 사용하지 못한다","src":"사회복지공동모금회법 제29조"}]},{"머리":"자원봉사활동 기본법","줄":[{"t":"자원봉사활동 기본법 목적: 자원봉사활동에 관한 기본적인 사항을 규정해 자원봉사활동을 진흥하고 행복한 공동체 건설에 이바지","src":"자원봉사활동 기본법 제1조"},{"t":"기본 방향: 국민의 협동적 참여 능력을 높이는 방향 / 무보수성·자발성·공익성·비영리성·비정파성·비종파성의 원칙 / 사회적 배경에 관계없이 누구나 참여 / 민·관 협력 기본 정신 (무차별성은 원칙에 포함되지 않음)","src":"자원봉사활동 기본법 제2조 | 기출 2021-23"},{"t":"자원봉사활동: 개인 또는 단체가 지역사회·국가 및 인류사회를 위하여 대가 없이 자발적으로 시간과 노력을 제공하는 행위. 자원봉사센터: 개발·장려·연계·협력 사업을 수행하는 기관·법인·단체","src":"자원봉사활동 기본법 제3조"},{"t":"정치활동 금지: 지원을 받는 자원봉사단체와 센터는 그 명의로 특정 정당이나 특정인의 선거운동을 하여서는 아니 된다","src":"자원봉사활동 기본법 제5조"},{"t":"자원봉사활동의 범위 15가지: 사회복지·보건 증진 / 지역사회 개발 / 환경보전 / 취약계층 권익·청소년 육성 / 교육·상담 / 인권 옹호·평화 / 범죄 예방·선도 / 교통질서·기초질서 / 재난 관리·재해 구호 / 문화·관광·예술·체육 / 부패 방지·소비자 보호 / 공명선거 / 국제협력·국외봉사 / 공공행정 사무 지원 / 그 밖의 공익사업","src":"자원봉사활동 기본법 제7조"},{"t":"자원봉사진흥위원회: 행정안전부장관 소속. 정책 방향 / 국가기본계획과 연도별 시행계획 / 제도 개선을 심의","src":"자원봉사활동 기본법 제8조"},{"t":"국가기본계획: 행정안전부장관이 관계 중앙행정기관의 장과 협의하여 5년마다 수립","src":"자원봉사활동 기본법 제9조"},{"t":"자원봉사자의 날: 매년 12월 5일. 그날부터 1주일간이 자원봉사주간","src":"자원봉사활동 기본법 제13조"},{"t":"자원봉사자 보호: 안전한 환경 노력 / 보험 가입 등. 자원봉사센터: 국가기관·지방자치단체가 설치할 수 있고 법인으로 운영하거나 비영리법인에 위탁","src":"자원봉사활동 기본법 제14조 제19조"},{"t":"한국자원봉사협의회: 자원봉사단체가 설립하며 법인. 정관을 작성해 행정안전부장관의 인가를 받아 등기","src":"자원봉사활동 기본법 제17조"},{"t":"사회복지 자원봉사활동은 사회복지사업법 제9조에 따라 국가가 홍보·교육, 프로그램 개발·보급, 재해 대비 시책을 실시하여야 한다","src":"사회복지사업법 제9조 | 기출 2024-7"}]},{"머리":"국제법과 사회보장협정","줄":[{"t":"헌법에 의하여 체결·공포된 조약과 일반적으로 승인된 국제법규는 국내법과 같은 효력을 가진다. 외국인의 지위는 국제법과 조약이 정하는 바에 의하여 보장","src":"헌법 제6조"},{"t":"외국인에 대한 사회보장제도 적용: 국내에 거주하는 외국인에게는 상호주의 원칙에 따르되 관계 법령에서 정하는 바에 따른다","src":"사회보장기본법 제8조"},{"t":"사회보장협정: 대한민국이 외국과 사회보장협정을 맺은 경우 국민연금의 가입 보험료 납부 급여 수급 요건 급여액 산정 급여 지급 등에 관하여 협정이 정하는 바에 따른다","src":"국민연금법 제127조"},{"t":"국민연금 외국인: 외국인도 당연히 사업장가입자 또는 지역가입자가 된다. 다만 본국 법이 대한민국 국민에게 상응하는 연금을 적용하지 않으면 제외(상호주의)","src":"국민연금법 제126조"},{"t":"사회보장협정의 일반 효과: 양 국가에서 이중으로 보험료를 내는 이중가입 방지(가입 면제) / 양국 가입기간 합산으로 수급 요건 충족(가입기간 합산) / 연금 수급권자의 해외 송금 등","src":"보충(원문 미확인)"},{"t":"국민건강보험법상 외국 정부가 사용자인 사업장의 근로자는 외국 정부와의 합의로 따로 정할 수 있다","src":"국민건강보험법 제109조제1항"}]}],"함정":[{"x":"모금회의 정관으로 규정하지 아니한 사항은 「민법」 중 사단법인에 관한 규정을 준용한다.","o":"출제 오답(바른 문장 미확인). 현행 법에는 민법 준용 조문이 없다.","src":"사회복지공동모금회법 제16조 | 기출 2022-25"},{"x":"이 법 또는 모금회의 정관으로 규정하지 아니한 사항은「민법」중 사단법인에 관한 규정을 준용 한다.","o":"출제 오답(바른 문장 미확인). 현행 사회복지공동모금회법에는 민법 준용 조문이 없고 정관 규정 사항은 제16조(조직·운영 등은 정관으로 정함).","src":"사회복지공동모금회법 제16조 | 기출 2021-22, 2022-25"},{"x":"배분분과실행위원회는 위원장 1명을 포함하여 20명 이내의 위원으로 구성한다.","o":"배분분과실행위원회와 모금분과실행위원회는 각각 20명 이상.","src":"사회복지공동모금회법 제13조제3항 | 기출 2022-25"},{"x":"기부금품의 기부자는 배분지역, 배분대상자 또는 사용 용도를 지정할 수 없다.","o":"지정할 수 있다.","src":"사회복지공동모금회법 제27조제1항 | 기출 2022-25"},{"x":"사회복지공동모금회는 언론기관을 모금창구로 지정할 수 있으나 지정된 언론기관의 명의로 모금계좌를 개설할 수 없다.","o":"언론기관 명의로 모금계좌를 개설할 수 있다.","src":"사회복지공동모금회법 제19조 | 기출 2022-25"},{"x":"모금회는 정관을 작성하여 보건복지부장관의 허가를 받아 등기함으로써 설립된다.","o":"인가를 받아 등기함으로써 설립된다.","src":"사회복지공동모금회법 제4조제3항 | 기출 2024-25, 2026-25"},{"x":"국가나 지방자치단체는 모금회의 관리ㆍ운영에 필요한 비용을 보조할 수 없다.","o":"보조할 수 있다는 것이 기출 정답 기준. 현행 조문 원문은 재확인 필요.","src":"보충(현행 조문 원문 미확인) | 기출 2026-25"},{"x":"모금회의 배분분과실행위원회 위원의 임기는 2년이고, 연임할 수 없다.","o":"임기 2년이고 한 차례만 연임할 수 있다.","src":"사회복지공동모금회법 제13조제4항 | 기출 2026-25"},{"x":"모금회는 매년 6월 30일까지 다음 회계연도의 공동모금재원 배분기준을 정하여 공고하여야 한다.","o":"매년 8월 31일까지.","src":"사회복지공동모금회법 제20조제1항 | 기출 2026-25"}]}};
